CREATE TABLE IF NOT EXISTS "knowledge_point" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"practice_id" BIGINT NOT NULL,
	"category" VARCHAR(40) NULL DEFAULT NULL,
	"name" VARCHAR(80) NULL DEFAULT NULL,
	"source" VARCHAR(16) NULL DEFAULT NULL,
	"in_scope" BOOLEAN NOT NULL DEFAULT true,
	"priority" VARCHAR(16) NULL DEFAULT NULL,
	"evidence_json" TEXT NULL DEFAULT NULL,
	"bound_quick" TEXT NULL DEFAULT NULL,
	"bound_std" TEXT NULL DEFAULT NULL,
	"bound_deep" TEXT NULL DEFAULT NULL,
	"times_seen" INTEGER NULL DEFAULT NULL,
	"history_json" TEXT NULL DEFAULT NULL,
	"angles_json" TEXT NULL DEFAULT NULL,
	"mastery" DOUBLE PRECISION NULL DEFAULT NULL,
	"status" VARCHAR(16) NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	"updated_at" BIGINT NOT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "knowledge_point_updated_at_not_null1" CHECK (updated_at IS NOT NULL),
	CONSTRAINT "knowledge_point_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "knowledge_point_in_scope_not_null1" CHECK (in_scope IS NOT NULL),
	CONSTRAINT "knowledge_point_practice_id_not_null1" CHECK (practice_id IS NOT NULL),
	CONSTRAINT "knowledge_point_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "knowledge_point_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_kp_user_practice" ON "" ("user_id", "practice_id", "created_at");;

