INSERT INTO "memory_point" ("id", "user_id", "practice_id", "question_id", "point_names_json", "text", "created_at") VALUES
	(1, 2, 1, 3, '["ArrayList · 增删与扩容机制"]', 'ArrayList 尾部 add 平均（均摊）O(1)，中间插入/删除 O(n）', 1793081333266),
	(2, 2, 1, 3, '["ArrayList · 增删与扩容机制"]', '中间插入慢的根因：插入点之后的元素要整体后移，移动量与 n 成正比', 1793081333266),
	(3, 2, 1, 3, '["ArrayList · 增删与扩容机制"]', '扩容为原来的约 1.5 倍：newCap = oldCap + (oldCap >> 1)', 1793081333266),
	(4, 2, 1, 4, '["集合框架 · 体系结构"]', '定位方式：List 按下标、Set 按内容（equals/hashCode）、Map 按 key、Queue 按进出顺序', 1793081333274),
	(5, 2, 1, 4, '["集合框架 · 体系结构"]', 'Queue 是 FIFO，栈是 LIFO；Deque 才支持当栈用', 1793081333274),
	(6, 2, 1, 4, '["集合框架 · 体系结构"]', 'Set/Map/Deque/Queue 是接口，HashSet/HashMap/ArrayDeque 才是实现类', 1793081333274),
	(7, 2, 1, 5, '["集合 · Comparable 与 Comparator"]', 'Comparable：类内实现 compareTo，定义唯一固定排序规则', 1793081333280),
	(8, 2, 1, 5, '["集合 · Comparable 与 Comparator"]', 'Comparator：独立于元素类重写 compare，可多套规则、不改原类', 1793081333280),
	(9, 2, 1, 5, '["集合 · Comparable 与 Comparator"]', 'Comparable 的 compareTo 由排序逻辑内部调用；Comparator 以参数传入、被回调', 1793081333280),
	(10, 2, 1, 6, '["集合选型 · 综合场景"]', '有序+可重复+按下标快速读取 → ArrayList（数组下标寻址 O(1)）', 1793081333284),
	(11, 2, 1, 6, '["集合选型 · 综合场景"]', '不重复+不关心顺序 → HashSet（hashCode+equals 判重，O(1)）', 1793081333284),
	(12, 2, 1, 6, '["集合选型 · 综合场景"]', '选型题必须写理由：一句话点出底层结构与复杂度', 1793081333284),
	(13, 2, 1, 7, '["集合 · equals/hashCode 契约"]', '重写 equals 决定 key 的逻辑相等；hashCode 必须配套重写', 1793081333290),
	(14, 2, 1, 7, '["集合 · equals/hashCode 契约"]', '契约：equals 为 true → hashCode 必须相同；反之不成立', 1793081333290),
	(15, 2, 1, 7, '["集合 · equals/hashCode 契约"]', '只重写 equals 的后果：相同 key 落不同桶，put 存两次、get 取不到', 1793081333290),
	(16, 2, 1, 8, '["ConcurrentHashMap · 并发特性"]', 'Hashtable：方法级 synchronized，读写全抢同一把锁，遗留类、并发差', 1793081333295),
	(17, 2, 1, 8, '["ConcurrentHashMap · 并发特性"]', 'ConcurrentHashMap：CAS + synchronized 锁桶头节点，写锁粒度到桶级', 1793081333295),
	(18, 2, 1, 8, '["ConcurrentHashMap · 并发特性"]', 'ConcurrentHashMap 读操作无锁（volatile），读多写少时吞吐远胜 Hashtable', 1793081333295),
	(19, 2, 1, 9, '["ArrayList · 底层结构与特性"]', '数组连续存储 → 首地址 + 下标×元素大小 直接算地址，O(1) 随机访问', 1793081333299),
	(20, 2, 1, 9, '["ArrayList · 底层结构与特性"]', '中间插入/删除 → 插入点之后元素整体后移/前移，O(n)', 1793081333299),
	(21, 2, 1, 9, '["ArrayList · 底层结构与特性"]', '随机访问快与插入慢是同一个「连续存储」特性带来的两面', 1793081333299),
	(22, 2, 1, 10, '["HashMap · 扩容机制"]', '扩容触发点：add 时数组放不下（元素个数 == 当前容量）', 1793081333304),
	(23, 2, 1, 10, '["HashMap · 扩容机制"]', '扩容后新容量 ≈ 旧容量的 1.5 倍（old + old>>1），Arrays.copyOf 拷贝', 1793081333304),
	(24, 2, 1, 10, '["HashMap · 扩容机制"]', 'ArrayList 没有「阈值」概念，阈值属于 HashMap', 1793081333304),
	(25, 2, 1, 1, '["List · 线程安全方案"]', 'synchronizedList 是方法级 synchronized，锁对象是包装器内部持有的 mutex（默认即 list 本身）；复合操作与遍历都需手动用同一把锁包住', 1793081333310),
	(26, 2, 1, 1, '["List · 线程安全方案"]', '遍历 synchronizedList 必须 synchronized(list) 包住迭代，否则可能抛 ConcurrentModificationException', 1793081333310),
	(27, 2, 1, 1, '["List · 线程安全方案"]', 'CopyOnWriteArrayList 写时复制：写时复制整个数组副本再切换引用，写开销大、内存翻倍，适合读多写少、集合不大', 1793081333310),
	(28, 2, 1, 1, '["List · 线程安全方案"]', 'COW 的迭代器基于旧快照，弱一致、不反映最新写入；写多、大数据量场景不适合', 1793081333310),
	(29, 2, 1, 2, '["HashMap · 底层结构与特性"]', 'JDK 8 HashMap：数组 + 链表 + 红黑树，桶内结构随冲突程度在链表与红黑树间切换', 1793081333316),
	(30, 2, 1, 2, '["HashMap · 底层结构与特性"]', '树化条件是「链表长度 ≥ 8 且数组容量 ≥ 64」；容量不足 64 先扩容而不是树化', 1793081333316),
	(31, 2, 1, 2, '["HashMap · 底层结构与特性"]', '允许一个 null 键（0 号桶）和多个 null 值；Hashtable 不允许 null', 1793081333316),
	(32, 2, 1, 2, '["HashMap · 底层结构与特性"]', 'HashMap 非线程安全，并发写可能丢数据、读到中间状态；要线程安全用 ConcurrentHashMap', 1793081333316),
	(33, 2, 1, 17, '["集合 · fail-fast 与 fail-safe"]', 'fail-fast：迭代器用 modCount 与 expectedModCount 比对，不一致抛 CME', 1793083218720),
	(34, 2, 1, 17, '["集合 · fail-fast 与 fail-safe"]', 'expectedModCount 是创建迭代器时记的快照，list.remove 不会更新它', 1793083218720),
	(35, 2, 1, 17, '["集合 · fail-fast 与 fail-safe"]', '安全删除：it.remove()（同步 expectedModCount）/ 反向 for / removeIf', 1793083218720),
	(36, 2, 1, 18, '["HashMap · 线程安全与替代方案"]', 'ArrayList.add 是 elementData[size]=e 与 size++ 两步，非原子，并发写会覆盖丢数据', 1793083218720),
	(37, 2, 1, 18, '["HashMap · 线程安全与替代方案"]', 'CopyOnWriteArrayList：写加锁复制数组 + volatile 发布，读无锁，适合读多写少', 1793083218720),
	(38, 2, 1, 18, '["HashMap · 线程安全与替代方案"]', '并发写入可选：Collections.synchronizedList、Vector、ConcurrentLinkedQueue', 1793083218720),
	(39, 2, 1, 19, '["集合框架 · 体系结构"]', 'Collection 与 Map 是并列根接口，Map 不继承 Collection', 1793083218736),
	(40, 2, 1, 19, '["集合框架 · 体系结构"]', 'List：有序、可重复、可按下标访问；Set：不允许重复；Queue：FIFO 语义', 1793083218736),
	(41, 2, 1, 19, '["集合框架 · 体系结构"]', 'Collection 存单个元素，Map 存 key-value 键值对', 1793083218736),
	(42, 2, 1, 20, '["List · 线程安全方案"]', 'Collections.synchronizedList：方法级加锁，读写都互斥，遍历时需手动 synchronized(list)', 1793083218743),
	(43, 2, 1, 20, '["List · 线程安全方案"]', 'CopyOnWriteArrayList：读无锁、写复制数组，适合读多写少、小集合', 1793083218743),
	(44, 2, 1, 20, '["List · 线程安全方案"]', '写频繁场景别用 COW，选 synchronizedList 或加锁容器', 1793083218743),
	(45, 2, 1, 11, '["集合选型 · 综合场景"]', '高并发计数选 ConcurrentHashMap（compute/merge 原子更新），不要用 Hashtable', 1793083218749),
	(46, 2, 1, 11, '["集合选型 · 综合场景"]', 'Hashtable 全方法 synchronized，读也加锁，高并发下竞争大', 1793083218749),
	(47, 2, 1, 11, '["集合选型 · 综合场景"]', 'ConcurrentHashMap 的 get 无锁，靠 volatile 可见性保证读安全', 1793083218749),
	(48, 2, 1, 12, '["ArrayList · 底层结构与特性"]', '边遍历边删的标准写法：Iterator 的 it.remove()，它会同步 expectedModCount', 1793083218756),
	(49, 2, 1, 12, '["ArrayList · 底层结构与特性"]', '反向 for 按下标删除也可行，正向删除会下标错位漏删', 1793083218756),
	(50, 2, 1, 12, '["ArrayList · 底层结构与特性"]', 'list.remove 会改 modCount，与迭代器的 expectedModCount 不一致 → 抛 CME', 1793083218756),
	(51, 2, 1, 14, '["HashMap · put 过程"]', 'put(k,v) 返回旧值（无则 null），存在则覆盖', 1793083218762),
	(52, 2, 1, 14, '["HashMap · put 过程"]', 'putIfAbsent：key 已存在（值非 null）就不放入，返回现值；不存在才放入并返回 null', 1793083218762),
	(53, 2, 1, 14, '["HashMap · put 过程"]', 'get 未命中返回 null；r3=2 是因为 putIfAbsent 返回现值而非新值', 1793083218762),
	(54, 2, 1, 15, '["Set · 去重原理"]', '判定依据：hashCode 定位桶、equals 桶内判等，两者共同决定去重', 1793083218769),
	(55, 2, 1, 15, '["Set · 去重原理"]', '仅重写 equals 不重写 hashCode → 内容相等对象落入不同桶，equals 不被调用，去重失败', 1793083218769),
	(56, 2, 1, 15, '["Set · 去重原理"]', '约束：equals 相等 ⇒ hashCode 必须相等；反向（hashCode 相等 ⇒ equals 相等）不要求', 1793083218769),
	(57, 2, 1, 15, '["Set · 去重原理"]', '两者不一致的典型后果：对象能 equals 却不等价地散列，HashSet/List 查找、去重全部失效', 1793083218769),
	(58, 2, 1, 16, '["HashMap · 底层结构与特性","HashMap · 扩容机制","ConcurrentHashMap · 并发特性"]', 'HashSet 只存元素不存计数值；去重+计数用 HashMap<URL,Integer>，判重靠 key 的 equals/hashCode，计数靠 value', 1793083218776),
	(59, 2, 1, 16, '["HashMap · 底层结构与特性","HashMap · 扩容机制","ConcurrentHashMap · 并发特性"]', 'HashMap 扩容条件：元素数 > 容量 × 0.75，扩容约 2 倍并重新分布所有元素', 1793083218776),
	(60, 2, 1, 16, '["HashMap · 底层结构与特性","HashMap · 扩容机制","ConcurrentHashMap · 并发特性"]', '减少扩容：按 预期条数 / 0.75 设置初始容量', 1793083218776),
	(61, 2, 1, 16, '["HashMap · 底层结构与特性","HashMap · 扩容机制","ConcurrentHashMap · 并发特性"]', 'HashMap 并发 put 会丢更新；Hashtable 锁粗吞吐低，ConcurrentHashMap 锁粒度细、适合高并发只增场景', 1793083218776),
	(62, 2, 2, 23, '["volatile · 可见性与原子性边界"]', '`count++` 是读-改-写三步复合操作，不是原子操作', 1793088095549),
	(63, 2, 2, 23, '["volatile · 可见性与原子性边界"]', 'volatile 只保证可见性与禁止指令重排，**不保证复合操作的原子性**', 1793088095549),
	(64, 2, 2, 23, '["volatile · 可见性与原子性边界"]', '丢更新 = 两个线程都读到旧值，后写覆盖前写，需要用锁或 Atomic 类解决', 1793088095549),
	(65, 2, 2, 26, '["volatile · 典型使用场景"]', '优雅停机典型写法：`volatile boolean running` + 工作线程 `while (running)` 循环 + 主线程置 `false`', 1793088095549),
	(66, 2, 2, 26, '["volatile · 典型使用场景"]', 'volatile 适合**一写多读的状态标志**：只需可见性，不需要原子性、不需要互斥', 1793088095549),
	(67, 2, 2, 26, '["volatile · 典型使用场景"]', 'volatile 的可见性与禁止重排序是两个独立语义，不要混为一谈', 1793088095549),
	(68, 2, 2, 22, '["synchronized · 三种使用形式与语义"]', 'synchronized 实例方法 与 `synchronized(this)` 锁的都是**当前实例 this**，同一实例上并发调用会**互斥**', 1793088095564),
	(69, 2, 2, 22, '["synchronized · 三种使用形式与语义"]', 'synchronized 静态方法锁的是 **Class 对象**，与实例锁不是同一把锁，**不会互斥**', 1793088095564),
	(70, 2, 2, 22, '["synchronized · 三种使用形式与语义"]', '互斥与否只看是否是**同一把锁（同一个对象的 monitor）**，与方法是静态还是实例无关', 1793088095564),
	(71, 2, 2, 31, '["ReentrantLock · 与 synchronized"]', '只需最终结果正确、无顺序要求的共享变量更新 → 原子类/CAS 无锁', 1793089776389),
	(72, 2, 2, 31, '["ReentrantLock · 与 synchronized"]', '需要线程间顺序/协作 → 锁 + 条件队列（wait/notify、Condition），互斥本身不保证顺序', 1793089776389),
	(73, 2, 2, 31, '["ReentrantLock · 与 synchronized"]', '无锁优势来源：不阻塞线程、无上下文切换与唤醒调度开销', 1793089776389),
	(74, 2, 2, 32, '["CAS · 原理与三大问题"]', 'CAS = 比较当前值与期望值，一致才写入新值，不一致则重试', 1793089776407),
	(75, 2, 2, 32, '["CAS · 原理与三大问题"]', '优势：无阻塞、无上下文切换、无死锁，低竞争下性能好', 1793089776407),
	(76, 2, 2, 32, '["CAS · 原理与三大问题"]', '三大局限：自旋开销、ABA 问题、只能保证单个变量原子性', 1793089776407),
	(77, 2, 2, 33, '["synchronized · 三种使用形式与语义"]', 'synchronized(obj) 互斥的前提是所有线程锁同一个对象', 1793089776407),
	(78, 2, 2, 33, '["synchronized · 三种使用形式与语义"]', 'synchronized(类.class) 锁的是 Class 对象，与任何实例锁都不互斥', 1793089776407),
	(79, 2, 2, 33, '["synchronized · 三种使用形式与语义"]', 'new 出来的对象作为锁，每次都是一把新锁，起不到保护作用', 1793089776407),
	(80, 2, 2, 34, '["AtomicInteger · 常用方法与适用场景"]', '常用方法：get()、set()、incrementAndGet()/getAndIncrement()、compareAndSet(期望值,新值)、addAndGet(增量)', 1793089776421),
	(81, 2, 2, 34, '["AtomicInteger · 常用方法与适用场景"]', 'compareAndSet 是原子类的底层核心，返回是否更新成功', 1793089776421),
	(82, 2, 2, 34, '["AtomicInteger · 常用方法与适用场景"]', '场景选择：单变量原子更新、低竞争 → 原子类；多变量/复合操作 → 加锁', 1793089776421),
	(83, 2, 2, 35, '["synchronized · 等待唤醒与线程协作"]', 'wait/notify/notifyAll 必须在持有该对象监视器锁时调用，否则抛 IllegalMonitorStateException', 1793089776424),
	(84, 2, 2, 35, '["synchronized · 等待唤醒与线程协作"]', '条件判断必须用 while 循环复查，防虚假唤醒和条件被改', 1793089776424),
	(85, 2, 2, 35, '["synchronized · 等待唤醒与线程协作"]', 'notify 随机唤醒一个等待线程，notifyAll 唤醒该对象上全部等待线程', 1793089776424),
	(86, 2, 2, 36, '["ReentrantLock · 公平锁与非公平锁"]', '公平锁：按队列顺序获取，无饥饿，但吞吐低、开销大', 1793089776424),
	(87, 2, 2, 36, '["ReentrantLock · 公平锁与非公平锁"]', '非公平锁：可插队抢锁，吞吐高（省去唤醒/切换开销），但可能饥饿', 1793089776424),
	(88, 2, 2, 36, '["ReentrantLock · 公平锁与非公平锁"]', 'ReentrantLock 默认非公平锁；new ReentrantLock(true) 才是公平锁', 1793089776424),
	(89, 2, 2, 37, '["synchronized · 锁升级过程"]', '升级总方向：无锁→偏向锁→轻量级锁→重量级锁，只能升不能降（重量级锁降级仅在 GC 时发生）', 1793089776437),
	(90, 2, 2, 37, '["synchronized · 锁升级过程"]', '偏向锁可被撤销：撤销后退回无锁或升级为轻量级锁', 1793089776437),
	(91, 2, 2, 37, '["synchronized · 锁升级过程"]', '偏向锁撤销触发点：出现其他线程竞争、对象调用 hashCode 等', 1793089776437),
	(92, 2, 2, 40, '["volatile · 指令重排序与 happens-befo"]', '指令重排序：不改变单线程结果的前提下调整指令顺序，来源有编译器、处理器、内存系统', 1793089776437),
	(93, 2, 2, 40, '["volatile · 指令重排序与 happens-befo"]', '写写重排导致 B 先看到 y=2 却看到 x=0', 1793089776437),
	(94, 2, 2, 40, '["volatile · 指令重排序与 happens-befo"]', '防重排序用 volatile（内存屏障）或加锁；new 对象的「分配-构造-赋值」重排是经典例子', 1793089776437),
	(95, 2, 2, 39, '["volatile · 可见性与原子性边界","volatile · 典型使用场景"]', 'volatile 的作用是**可见性 + 禁止重排**，不保证复合操作的原子性，int++ 仍是非原子', 1793089776453),
	(96, 2, 2, 39, '["volatile · 可见性与原子性边界","volatile · 典型使用场景"]', 'volatile 写 = 内存屏障 + 立即刷新主内存 + MESI 使其他线程缓存失效；读 = 直接读主内存', 1793089776453),
	(97, 2, 2, 39, '["volatile · 可见性与原子性边界","volatile · 典型使用场景"]', 'AtomicInteger + CAS 解决的是「读-改-写」的原子性/丢失更新问题，volatile 单独做不到', 1793089776453),
	(98, 2, 2, 45, '["CAS · 原理与三大问题"]', 'CAS 无锁自旋，不阻塞线程，省去锁申请/释放与上下文切换开销', 1793092965393),
	(99, 2, 2, 45, '["CAS · 原理与三大问题"]', '单次自增极快、冲突窗口小 → CAS 成功率高，比 synchronized 划算', 1793092965393),
	(100, 2, 2, 45, '["CAS · 原理与三大问题"]', '高竞争下 CAS 自旋空耗 CPU、失败率高，此时加锁（或 LongAdder）更优', 1793092965393),
	(101, 2, 2, 47, '["volatile · 典型使用场景"]', 'new 对象 = 分配内存 → 初始化 → 引用赋值，三步可能被重排', 1793092965408),
	(102, 2, 2, 47, '["volatile · 典型使用场景"]', '危险是引用赋值先于构造完成发布，别的线程拿到半初始化对象', 1793092965408),
	(103, 2, 2, 47, '["volatile · 典型使用场景"]', 'volatile 禁止重排序 + 保证可见性，双检锁的成员引用必须加它', 1793092965408),
	(104, 2, 2, 50, '["synchronized · 三种使用形式与语义"]', 'synchronized(this){} 锁当前实例；synchronized(Xxx.class){} 锁 Class 对象', 1793092965409),
	(105, 2, 2, 50, '["synchronized · 三种使用形式与语义"]', '普通 synchronized 方法锁 this，静态 synchronized 方法锁类对象', 1793092965409),
	(106, 2, 2, 50, '["synchronized · 三种使用形式与语义"]', '实例锁之间互斥，实例锁与类锁之间互不互斥', 1793092965409),
	(107, 2, 2, 48, '["volatile · 可见性与原子性边界"]', '标记位是单次写/单次读，本身原子，volatile 再补上可见性就够用', 1793092965409),
	(108, 2, 2, 48, '["volatile · 可见性与原子性边界"]', 'count++ 是读-改-写复合操作，volatile 不保证其原子性，需 CAS/锁/原子类', 1793092965409),
	(109, 2, 2, 48, '["volatile · 可见性与原子性边界"]', 'volatile 的语义：单次读写可见性 + 禁止重排，不含复合操作原子性', 1793092965409),
	(110, 2, 2, 49, '["ReentrantLock · 与 synchronized","ReentrantLock · 公平锁与非公平锁","AtomicInteger · 常用方法与适用场景"]', 'synchronized 是 JVM 进程内锁，多实例部署下不互斥、防不住超卖', 1793092965425),
	(111, 2, 2, 49, '["ReentrantLock · 与 synchronized","ReentrantLock · 公平锁与非公平锁","AtomicInteger · 常用方法与适用场景"]', '方案二靠数据库行锁 + `stock>0` 条件更新原子完成判断与扣减，按受影响行数判成功', 1793092965425),
	(112, 2, 2, 49, '["ReentrantLock · 与 synchronized","ReentrantLock · 公平锁与非公平锁","AtomicInteger · 常用方法与适用场景"]', '方案三靠 Redis 单线程/Lua 原子扣减（不是 setnx），代价是与 MySQL 的一致性需对账兜底', 1793092965425),
	(113, 2, 2, 49, '["ReentrantLock · 与 synchronized","ReentrantLock · 公平锁与非公平锁","AtomicInteger · 常用方法与适用场景"]', 'QPS 不高时优先条件更新：简单、强一致、天然防超卖', 1793092965425),
	(114, 2, 2, 51, '["volatile · 可见性与原子性边界"]', 'volatile 保证可见性与有序性，**不保证原子性**', 1793151036096),
	(115, 2, 2, 51, '["volatile · 可见性与原子性边界"]', 'i++ 是读-改-写复合操作，交错执行会产生**丢失更新**', 1793151036096),
	(116, 2, 2, 51, '["volatile · 可见性与原子性边界"]', '要原子自增用 AtomicLong / synchronized / LongAdder', 1793151036096),
	(117, 2, 2, 52, '["CAS · 原理与三大问题"]', '降竞争是首选：热点拆分累加（如 LongAdder）、批量合并、失败退避', 1793151036105),
	(118, 2, 2, 52, '["CAS · 原理与三大问题"]', '限制自旋次数，重试超限后转为加锁', 1793151036105),
	(119, 2, 2, 52, '["CAS · 原理与三大问题"]', '写多读少 / 多变量需一致修改 / 重试长期失败时，改用 synchronized、Lock 更划算', 1793151036105),
	(120, 2, 2, 52, '["CAS · 原理与三大问题"]', '版本号解决的是 ABA，不是自旋开销', 1793151036105),
	(121, 2, 2, 54, '["synchronized · 三种使用形式与语义"]', 'synchronized 实例方法锁的是**当前对象实例**，与方法定义在哪个类无关', 1793151036112),
	(122, 2, 2, 54, '["synchronized · 三种使用形式与语义"]', '继承不改变锁对象：父类 synchronized 方法在子类实例上调用，锁的仍是该子类实例', 1793151036112),
	(123, 2, 2, 54, '["synchronized · 三种使用形式与语义"]', '同一对象上的 synchronized 实例方法之间互斥，只有 static 同步方法锁 Class 对象才互不干扰', 1793151036112),
	(124, 2, 2, 57, '["synchronized · 等待唤醒与线程协作"]', '等待条件不一致（生产者消费者同池等待）时用 **notifyAll**，否则会"唤醒错人"丢信号、假死', 1793151036112),
	(125, 2, 2, 57, '["synchronized · 等待唤醒与线程协作"]', '等待线程同质、唤醒任一个都能推进（如单生产单消费）时 **notify** 安全', 1793151036112),
	(126, 2, 2, 57, '["synchronized · 等待唤醒与线程协作"]', '无论 notify 还是 notifyAll，被唤醒后都要用 **while 重检条件**', 1793151036112),
	(127, 2, 2, 59, '["ReentrantLock · tryLock 超时与可中断"]', 'tryLock() / tryLock(timeout) 都返回 **boolean**，true=拿到锁', 1793151036128),
	(128, 2, 2, 59, '["ReentrantLock · tryLock 超时与可中断"]', 'tryLock() 立即判定、**不阻塞**；timeout 版最多阻塞 timeout，超时返回 false', 1793151036128),
	(129, 2, 2, 59, '["ReentrantLock · tryLock 超时与可中断"]', 'timeout 版等待期间可被中断并抛 InterruptedException', 1793151036128),
	(130, 2, 2, 68, '["ReentrantLock · 与 synchronized"]', '跨方法共享的锁声明成 `private final Object lock = new Object();`，放在类的字段位置', 1793155898836),
	(131, 2, 2, 68, '["ReentrantLock · 与 synchronized"]', '局部变量当锁=每次新对象，锁不住；普通实例变量当锁=可被换掉，锁失效', 1793155898836),
	(132, 2, 2, 68, '["ReentrantLock · 与 synchronized"]', '需要类级共享就用 `private static final Object LOCK`', 1793155898836),
	(133, 2, 2, 69, '["volatile · 典型使用场景"]', 'volatile 防的是 DCL 中『引用赋值先于构造完成』的重排，读到的是半初始化对象而非 null', 1793155898850),
	(134, 2, 2, 69, '["volatile · 典型使用场景"]', 'volatile 提供可见性 + 禁止重排序，但不保证复合操作原子性', 1793155898850),
	(135, 2, 2, 69, '["volatile · 典型使用场景"]', 'volatile 管不了 check-then-act：判空+创建仍会重复执行，互斥要靠 synchronized', 1793155898850),
	(136, 2, 2, 70, '["synchronized · 三种使用形式与语义"]', 'synchronized 实例方法 ⇔ synchronized(this)，锁的都是当前实例', 1793155898866),
	(137, 2, 2, 70, '["synchronized · 三种使用形式与语义"]', 'synchronized(this) 与 synchronized 实例方法抢同一把锁，会互斥', 1793155898866),
	(138, 2, 2, 70, '["synchronized · 三种使用形式与语义"]', 'static synchronized 锁的是 Class 对象，不与 this 互斥', 1793155898866),
	(139, 2, 2, 71, '["volatile · 可见性与原子性边界"]', 'volatile 写：立即刷新可见，之前的内存操作不会重排到写之后', 1793155898866),
	(140, 2, 2, 71, '["volatile · 可见性与原子性边界"]', 'volatile 读：每次读最新值，之后的内存操作不会重排到读之前', 1793155898866),
	(141, 2, 2, 71, '["volatile · 可见性与原子性边界"]', '边界：不保证复合操作原子性，不能替代锁，可见性≠实时通知', 1793155898866),
	(142, 2, 2, 63, '["ReentrantLock · 公平锁与非公平锁"]', 'ReentrantLock#tryLock(long timeout, TimeUnit unit)：带超时的获取，拿不到就返回 false', 1793155898881),
	(143, 2, 2, 63, '["ReentrantLock · 公平锁与非公平锁"]', '好处：等待时间差异大时可按需设定等待上限，避免线程长期阻塞堆积', 1793155898881),
	(144, 2, 2, 63, '["ReentrantLock · 公平锁与非公平锁"]', 'tryLock() 无参版：立即返回，不等待；两者都比 lock() 更可控', 1793155898881),
	(145, 2, 2, 66, '["synchronized · 锁升级过程"]', '偏向锁撤销后有竞争 → 升级为轻量级锁（CAS 自旋），竞争加剧才膨胀为重量级锁', 1793155898881),
	(146, 2, 2, 66, '["synchronized · 锁升级过程"]', '转轻量级的理由：轻度竞争下自旋开销 < 线程阻塞/唤醒开销', 1793155898881),
	(147, 2, 2, 66, '["synchronized · 锁升级过程"]', '锁升级不是严格单向：重量级锁可降级，还有批量重偏向/批量撤销', 1793155898881),
	(148, 2, 2, 73, '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","synchronized · 等待唤醒与线程协作"]', 'i++ = 读-改-写三步非原子，并发丢失更新', 1793155898897),
	(149, 2, 2, 73, '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","synchronized · 等待唤醒与线程协作"]', 'volatile 只保证可见性和有序性，救不了复合操作原子性', 1793155898897),
	(150, 2, 2, 73, '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","synchronized · 等待唤醒与线程协作"]', 'CAS = 读旧值 expected → 原子比较内存值 → 一致则写，不一致则自旋重试', 1793155898897),
	(151, 2, 2, 73, '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","synchronized · 等待唤醒与线程协作"]', '高并发 CAS 代价：自旋空转烧 CPU、缓存行反复失效，还有 ABA 问题', 1793155898897),
	(152, 2, 2, 74, '["synchronized · 锁升级过程"]', '轻量级锁 CAS 自旋抢锁失败后**膨胀为重量级锁**', 1793178905154),
	(153, 2, 2, 74, '["synchronized · 锁升级过程"]', '重量级锁膨胀**不可逆**，释放后仍是重量级状态，不会降级', 1793178905154),
	(154, 2, 2, 74, '["synchronized · 锁升级过程"]', '重量级锁之后的线程直接走阻塞/唤醒（ObjectMonitor）', 1793178905154),
	(155, 2, 2, 75, '["volatile · 典型使用场景"]', 'volatile 写 → 后续 volatile 读构成 **happens-before** 边', 1793178905165),
	(156, 2, 2, 75, '["volatile · 典型使用场景"]', '读到 volatile 标志后，**写标志之前的所有修改**都可见', 1793178905165),
	(157, 2, 2, 75, '["volatile · 典型使用场景"]', 'volatile 保证的是可见性与有序性，不是只保证自身变量', 1793178905165),
	(158, 2, 2, 76, '["volatile · 可见性与原子性边界"]', 'volatile 只保证**可见性 + 禁止重排**，不保证**原子性**', 1793178905170),
	(159, 2, 2, 76, '["volatile · 可见性与原子性边界"]', 'count++ 是**读-改-写**三步复合操作，会丢失更新', 1793178905170),
	(160, 2, 2, 76, '["volatile · 可见性与原子性边界"]', '计数用 **AtomicInteger** 或加锁，别用 volatile int 做累加', 1793178905170),
	(161, 2, 2, 77, '["synchronized · 三种使用形式与语义"]', '实例方法 synchronized 锁的是 **this**', 1793178905170),
	(162, 2, 2, 77, '["synchronized · 三种使用形式与语义"]', '静态方法 synchronized 锁的是 **Xxx.class** 类对象', 1793178905170),
	(163, 2, 2, 77, '["synchronized · 三种使用形式与语义"]', 'synchronized(this) 与实例方法锁同一个对象，二者互斥', 1793178905170),
	(164, 2, 2, 78, '["ReentrantLock · 公平锁与非公平锁"]', 'new ReentrantLock() 默认 **非公平锁**', 1793178905186),
	(165, 2, 2, 78, '["ReentrantLock · 公平锁与非公平锁"]', '公平锁按 **FIFO** 排队，开销大、吞吐低', 1793178905186),
	(166, 2, 2, 78, '["ReentrantLock · 公平锁与非公平锁"]', '非公平锁允许插队抢锁，减少唤醒与上下文切换', 1793178905186),
	(167, 2, 2, 78, '["ReentrantLock · 公平锁与非公平锁"]', '需要公平时用 new ReentrantLock(true)', 1793178905186),
	(168, 2, 2, 55, '["ReentrantLock · tryLock 超时与可中断"]', 'tryLock 的返回值要用**变量存下来**', 1793178905202),
	(169, 2, 2, 55, '["ReentrantLock · tryLock 超时与可中断"]', 'finally 里 **if (抢到锁) unlock()**，不要无条件 unlock', 1793178905202),
	(170, 2, 2, 55, '["ReentrantLock · tryLock 超时与可中断"]', '未持锁调用 unlock 抛 **IllegalMonitorStateException**', 1793178905202),
	(171, 2, 2, 67, '["Condition · 多条件等待唤醒"]', 'signal() 唤醒**一个**等待线程，signalAll() 唤醒**全部**', 1793178905209),
	(172, 2, 2, 67, '["Condition · 多条件等待唤醒"]', '共用一个 Condition 时误唤醒风险高，用 signalAll + **while 条件检查**', 1793178905209),
	(173, 2, 2, 67, '["Condition · 多条件等待唤醒"]', '生产者/消费者分属两个 Condition，可 signal 精确唤醒，效率更高', 1793178905209),
	(174, 2, 2, 79, '["volatile · 指令重排序与 happens-befo"]', '重排发生在三个环节：**编译器、处理器（乱序执行）、内存系统**', 1793178905218),
	(175, 2, 2, 79, '["volatile · 指令重排序与 happens-befo"]', '单线程靠 **as-if-serial** 语义，重排不改变结果', 1793178905218),
	(176, 2, 2, 79, '["volatile · 指令重排序与 happens-befo"]', '多线程下缺同步，重排会暴露**中间状态**', 1793178905218),
	(177, 2, 2, 79, '["volatile · 指令重排序与 happens-befo"]', 'volatile 写 flag 可禁止写前操作被重排到写后', 1793178905218),
	(178, 2, 2, 80, '["ReentrantLock · 与 synchronized"]', '**unlock 必须写在 finally 里**，与 lock() 严格配对，覆盖提前 return 与异常两条路径', 1793178905228),
	(179, 2, 2, 80, '["ReentrantLock · 与 synchronized"]', '漏写 unlock（或写在不会执行的分支）→ **锁永不释放**，其他线程 lock() 后永久阻塞、程序卡死', 1793178905228),
	(180, 2, 2, 80, '["ReentrantLock · 与 synchronized"]', '现象是**单锁泄漏导致线程永久阻塞**，不是严格意义的死锁（无循环等待）', 1793178905228),
	(181, 2, 2, 80, '["ReentrantLock · 与 synchronized"]', 'ReentrantLock 可重入：**lock 几次就要 unlock 几次**，少一次同样不释放', 1793178905228),
	(182, 2, 2, 83, '["synchronized · 锁升级过程"]', '偏向锁：只有一个线程反复进入同步块、无竞争时存在，记录线程 ID 免 CAS', 1793238532164),
	(183, 2, 2, 83, '["synchronized · 锁升级过程"]', '轻量级锁：少量线程交替执行、无长时间竞争，用户态 CAS 自旋拿锁', 1793238532164),
	(184, 2, 2, 83, '["synchronized · 锁升级过程"]', '重量级锁：竞争激烈、自旋不划算，升级为内核阻塞/唤醒的互斥量', 1793238532164),
	(185, 2, 2, 83, '["synchronized · 锁升级过程"]', '锁只升级不降级（偏向锁可撤销回无锁），目的是用低开销路径覆盖常见无竞争/轻竞争场景', 1793238532164),
	(186, 2, 2, 85, '["synchronized · 三种使用形式与语义"]', 'synchronized 实例方法锁的是 this（当前对象），同一个对象的两个实例同步方法互斥', 1793238532192),
	(187, 2, 2, 85, '["synchronized · 三种使用形式与语义"]', 'static synchronized 锁的是 Class 对象，与实例锁是两把不同的锁，互不阻塞', 1793238532192),
	(188, 2, 2, 85, '["synchronized · 三种使用形式与语义"]', '普通方法无锁，可与任何同步方法并行', 1793238532192),
	(189, 2, 2, 87, '["synchronized · 等待唤醒与线程协作"]', 'wait 必须在持有锁的同步块内、放在 while(条件不满足) 循环里，防虚假唤醒', 1793238532192),
	(190, 2, 2, 87, '["synchronized · 等待唤醒与线程协作"]', '自己打印并更新共享状态后 notify/notifyAll 唤醒对方线程', 1793238532192),
	(191, 2, 2, 87, '["synchronized · 等待唤醒与线程协作"]', 'wait/notify 要在同一把锁（同一对象监视器）上调用，共享变量的读写也要在该锁内', 1793238532192),
	(192, 2, 2, 88, '["ReentrantLock · 公平锁与非公平锁"]', 'ReentrantLock(true) 是公平锁，无参构造默认非公平锁', 1793238532208),
	(193, 2, 2, 88, '["ReentrantLock · 公平锁与非公平锁"]', '公平锁按队列 FIFO 出队，非公平锁允许新线程插队抢锁，吞吐更高但可能饥饿', 1793238532208),
	(194, 2, 2, 88, '["ReentrantLock · 公平锁与非公平锁"]', '公平锁适合对顺序/公平性有要求的场景，一般场景用默认非公平即可', 1793238532208),
	(195, 2, 2, 90, '["Condition · 多条件等待唤醒"]', '一个 ReentrantLock 上创建 notFull / notEmpty 两个 Condition，生产者消费者各等各的队列', 1793238532224),
	(196, 2, 2, 90, '["Condition · 多条件等待唤醒"]', '等待用 while(条件) await()，防虚假唤醒；生产者放完 signal notEmpty，消费者取完 signal notFull', 1793238532224),
	(197, 2, 2, 90, '["Condition · 多条件等待唤醒"]', '多 Condition 精准唤醒，避免 notifyAll 惊群和无效上下文切换', 1793238532224),
	(198, 2, 2, 91, '["volatile · 指令重排序与 happens-befo"]', '普通变量写可能滞留工作内存、读线程可能缓存旧值——这是可见性问题，与重排序是两个独立成因', 1793238532224),
	(199, 2, 2, 91, '["volatile · 指令重排序与 happens-befo"]', 'volatile 写之前的所有写 happens-before 后续对该 volatile 变量的读，所以 flag 加 volatile 能带出 a=1', 1793238532224),
	(200, 2, 2, 91, '["volatile · 指令重排序与 happens-befo"]', '只给 flag 加 volatile 就够，a 不需要加（a 的可见性由 flag 的 volatile 语义传递保证）', 1793238532224),
	(201, 2, 2, 82, '["volatile · 典型使用场景"]', '单写多读的状态标志用 volatile，靠可见性保证读线程立刻看到，与写操作是否原子无关', 1793238532240),
	(202, 2, 2, 82, '["volatile · 典型使用场景"]', '热点计数 counter++ 非原子，volatile 无效，要用 AtomicLong/LongAdder 或加锁', 1793238532240),
	(203, 2, 2, 82, '["volatile · 典型使用场景"]', '共享引用字段加 volatile：一是更新可见，二是禁止重排，避免读到未构造完的对象', 1793238532240),
	(204, 2, 2, 92, '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","ReentrantLock · 与 synchronized"]', '**volatile 只保证可见性 + 禁止重排，不保证原子性**，不能用于 count++/i++ 这类读-改-写复合操作；适合状态标志、单次读写、独立赋值场景', 1793238532240),
	(205, 2, 2, 92, '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","ReentrantLock · 与 synchronized"]', '**CAS 失败是自旋重试**（CPU 空转重试直到成功或让出），**synchronized 抢锁失败是阻塞让出 CPU**、待持有者释放后唤醒重抢', 1793238532240),
	(206, 2, 2, 92, '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","ReentrantLock · 与 synchronized"]', '**CAS 适合临界区短、高频、竞争不极端**的场景；**synchronized 适合临界区长、竞争激烈**的场景（CAS 长临界区会大量自旋浪费 CPU）', 1793238532240),
	(207, 2, 2, 92, '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","ReentrantLock · 与 synchronized"]', '计数用 **AtomicLong/CAS 无锁化**；慢查询临界区用 **ReadWriteLock / 快照 / 写时复制** 把长操作与高频写隔离，避免长时间阻塞高频计数', 1793238532240),
	(208, 2, 2, 86, '["volatile · 可见性与原子性边界"]', 'volatile 保证可见性与禁止指令重排序，**不保证复合操作的原子性**。', 1793238567236),
	(209, 2, 2, 86, '["volatile · 可见性与原子性边界"]', '单写单读的 **volatile 标志位（如停止标记）** 场景是正确的，靠写入原子 + 可见性。', 1793238567236),
	(210, 2, 2, 86, '["volatile · 可见性与原子性边界"]', '**count++ 是读-改-写复合操作**，多线程下 volatile 无法阻止丢失更新，需用 AtomicInteger 或加锁。', 1793238567236),
	(211, 2, 2, 86, '["volatile · 可见性与原子性边界"]', '判断 volatile 是否够用的口诀：**单赋值可见即可用，复合操作必须锁或 CAS**。', 1793238567236),
	(212, 2, 2, 99, '["volatile · 指令重排序与 happens-befo"]', '指令重排有两个来源：编译器优化 + 处理器乱序执行，JMM 要同时约束。', 1793240844238),
	(213, 2, 2, 99, '["volatile · 指令重排序与 happens-befo"]', 'volatile 靠内存屏障同时禁止编译器与处理器重排，不只是"刷新内存"。', 1793240844238),
	(214, 2, 2, 99, '["volatile · 指令重排序与 happens-befo"]', 'volatile 写之前的操作不后移、volatile 读之后的操作不前移，两端合起来才推出 flag=true ⇒ data=42 可见。', 1793240844238),
	(215, 2, 2, 99, '["volatile · 指令重排序与 happens-befo"]', 'volatile 写 happens-before 后续对该变量的 volatile 读。', 1793240844238),
	(216, 2, 2, 102, '["synchronized · 等待唤醒与线程协作"]', 'notify 不释放锁，通知线程退出同步块后被唤醒线程才可能抢到锁。', 1793240844250),
	(217, 2, 2, 102, '["synchronized · 等待唤醒与线程协作"]', '必须 while 复查条件的原因：虚假唤醒 + 唤醒线程条件未必成立 + 等锁期间条件可能又被改。', 1793240844250),
	(218, 2, 2, 102, '["synchronized · 等待唤醒与线程协作"]', 'wait/notify 必须在持有该对象监视器锁的同步块内调用，否则抛 IllegalMonitorStateException。', 1793240844250),
	(219, 2, 2, 96, '["ReentrantLock · tryLock 超时与可中断"]', 'tryLock() 抛 InterruptedException 时锁未获取成功，绝不能 unlock。', 1793240844259),
	(220, 2, 2, 96, '["ReentrantLock · tryLock 超时与可中断"]', '正确处理 = 恢复中断标记 Thread.currentThread().interrupt() + 按"获取锁失败"分支处理。', 1793240844259),
	(221, 2, 2, 96, '["ReentrantLock · tryLock 超时与可中断"]', '不能简单 catch 后继续：会吞掉中断信号，且后续代码在无锁状态下访问共享资源。', 1793240844259),
	(222, 2, 2, 97, '["Condition · 多条件等待唤醒"]', 'Condition.await() 返回后必须 while 复查条件，因为虚假唤醒 + 条件可能已被其他线程改掉。', 1793240844268),
	(223, 2, 2, 97, '["Condition · 多条件等待唤醒"]', 'signal 不等于条件成立，只是把线程移出等待队列，醒来还要重抢锁。', 1793240844268),
	(224, 2, 2, 97, '["Condition · 多条件等待唤醒"]', 'await 会原子地释放绑定的锁并进入等待，返回前重新获得锁。', 1793240844268),
	(225, 2, 2, 98, '["volatile · 典型使用场景"]', 'volatile 引用保证的是"引用赋值"的可见性与有序性，不保证被指向对象内部字段的并发修改。', 1793240844278),
	(226, 2, 2, 98, '["volatile · 典型使用场景"]', '整体替换引用 = 安全发布（写引用前的字段写都对读到新引用的线程可见）；就地改字段不写引用 = 无任何可见性保证。', 1793240844278),
	(227, 2, 2, 98, '["volatile · 典型使用场景"]', 'volatile 只解决可见性/有序性，不解决原子性：复合操作、多字段一致更新必须加锁或用不可变对象。', 1793240844278),
	(228, 2, 2, 103, '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","ReentrantLock · 与 synchronized"]', 'check-then-act 是经典竞态：查询与写入之间无互斥，两线程都判定"无记录"而重复执行。', 1793240844287),
	(229, 2, 2, 103, '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","ReentrantLock · 与 synchronized"]', '唯一约束只能拦截记录重复写入，拦截不了扣款动作本身。', 1793240844287),
	(230, 2, 2, 103, '["AtomicInteger · 常用方法与适用场景","CAS · 原理与三大问题","ReentrantLock · 与 synchronized"]', '幂等方案 = 扣款与幂等记录写入同事务 + 唯一键冲突回滚，或用 SELECT FOR UPDATE / 乐观锁做互斥。', 1793240844287),
	(231, 2, 2, 104, '["volatile · 指令重排序与happens-befor"]', '普通变量的写写、读读都可能被编译器/CPU 重排序，没有内存屏障约束', 1793326387347),
	(232, 2, 2, 104, '["volatile · 指令重排序与happens-befor"]', 'flag=true 仍可能读到旧 data 的原因是缺 happens-before 保证，不是缓存不一致', 1793326387347),
	(233, 2, 2, 104, '["volatile · 指令重排序与happens-befor"]', '加 volatile 修饰 flag 即可：volatile 写之前的写不会重排到其后，读之后的读不会提前', 1793326387347),
	(234, 2, 2, 112, '["synchronized锁升级 · 单向不可逆与不可降级"]', '锁升级路径：无锁→偏向锁→轻量级锁→重量级锁，只能升不能降', 1793326387366),
	(235, 2, 2, 112, '["synchronized锁升级 · 单向不可逆与不可降级"]', '不可逆的原因：重量级锁下有线程在 monitor 等待队列阻塞，降级会丢失等待者、破坏互斥', 1793326387366),
	(236, 2, 2, 112, '["synchronized锁升级 · 单向不可逆与不可降级"]', '偏向锁可撤销回到无锁，但膨胀成重量级锁后不能再降回轻量级/偏向', 1793326387366),
	(237, 2, 2, 105, '["volatile · 禁止指令重排"]', '对象创建三步：分配内存 → 执行构造 → 引用赋值，可能被重排为 分配→赋值→构造', 1793326387382),
	(238, 2, 2, 105, '["volatile · 禁止指令重排"]', '不加 volatile 的后果：别的线程读到非 null 但未构造完成的半成品对象', 1793326387382),
	(239, 2, 2, 105, '["volatile · 禁止指令重排"]', 'volatile 的作用是禁止这三步重排 + 保证写读的可见性，锁只保证互斥不解决重排', 1793326387382),
	(240, 2, 2, 107, '["synchronized · 竞态条件导致重复扣款"]', '查库判断+更新属于 check-then-act，中间无锁就是竞态条件', 1793326387393),
	(241, 2, 2, 107, '["synchronized · 竞态条件导致重复扣款"]', '根因：复合操作非原子，多个线程基于同一旧值判断导致丢失更新/超扣', 1793326387393),
	(242, 2, 2, 107, '["synchronized · 竞态条件导致重复扣款"]', '解法可加锁或用带条件的原子更新（如 UPDATE ... WHERE balance >= ?），但本题只考原因', 1793326387393),
	(243, 2, 2, 108, '["volatile · 不保证复合操作原子性"]', 'volatile 只管可见性+禁止重排，不管原子性', 1793326387403),
	(244, 2, 2, 108, '["volatile · 不保证复合操作原子性"]', 'i++ 是读-改-写三步，volatile 无法保证这三步不被打断', 1793326387403),
	(245, 2, 2, 108, '["volatile · 不保证复合操作原子性"]', '计数正确要用 AtomicInteger/LongAdder、锁，或原子类的 incrementAndGet', 1793326387403),
	(246, 2, 2, 109, '["ReentrantLock · tryLock 超时与可中断"]', 'tryLock(timeout)：超时返回 false、成功返回 true，可避免无限等待，但默认不响应中断', 1793326387411),
	(247, 2, 2, 109, '["ReentrantLock · tryLock 超时与可中断"]', 'lockInterruptibly()：等待期间被中断抛 InterruptedException，适合可取消/优雅停机场景', 1793326387411),
	(248, 2, 2, 109, '["ReentrantLock · tryLock 超时与可中断"]', 'lock() 被中断不抛异常、只置中断标志后继续等待，这是三者的对照点', 1793326387411),
	(249, 2, 2, 110, '["volatile · 禁止指令重排序"]', 'DCL 的问题根源：构造与引用赋值可重排 + 锁外读没有 happens-before', 1793326387421),
	(250, 2, 2, 110, '["volatile · 禁止指令重排序"]', 'volatile 保证「要么看到 null、要么看到完整构造好的实例」', 1793326387421),
	(251, 2, 2, 110, '["volatile · 禁止指令重排序"]', 'synchronized 只保证临界区互斥与可见性，管不了锁外读到的半成品引用', 1793326387421),
	(252, 2, 2, 106, '["synchronized · 方法锁与静态方法锁的对象差异"]', '实例 synchronized 锁 this，静态 synchronized 锁 Class 对象', 1793326387436),
	(253, 2, 2, 106, '["synchronized · 方法锁与静态方法锁的对象差异"]', '锁对象不同就不互斥：实例 vs 静态、两个实例之间都不互斥', 1793326387436),
	(254, 2, 2, 106, '["synchronized · 方法锁与静态方法锁的对象差异"]', '只有锁同一个对象（同一实例/同一个 Class）才互斥', 1793326387436),
	(255, 2, 2, 113, '["volatile · 指令重排序与 happens-befo","volatile · 典型使用场景","volatile · 可见性与原子性边界"]', 'volatile 只保证可见性与单次读/写的原子性，不保证 count++ 这类读—改—写复合操作的原子性', 1793326387446),
	(256, 2, 2, 113, '["volatile · 指令重排序与 happens-befo","volatile · 典型使用场景","volatile · 可见性与原子性边界"]', 'count++ 丢数原因：读、改、写三步之间可被其他线程插入，后写覆盖前写', 1793326387446),
	(257, 2, 2, 113, '["volatile · 指令重排序与 happens-befo","volatile · 典型使用场景","volatile · 可见性与原子性边界"]', '不加 synchronized 的替代方案：AtomicInteger 等原子类（CAS 自旋）、LongAdder（高并发计数降竞争）', 1793326387446),
	(258, 2, 2, 113, '["volatile · 指令重排序与 happens-befo","volatile · 典型使用场景","volatile · 可见性与原子性边界"]', '多字段联合更新 volatile 不够：封装不可变对象整体替换引用，或用 synchronized 保证互斥', 1793326387446),
	(259, 2, 2, 114, '["volatile · 指令重排序与 happens-befo"]', 'DCL 中 volatile 的作用是**禁止指令重排序**，防止其他线程拿到半初始化对象', 1793348292769),
	(260, 2, 2, 114, '["volatile · 指令重排序与 happens-befo"]', '对象创建三步：分配内存→执行构造→引用赋值，后两步可被重排成「赋引用→执行构造」', 1793348292769),
	(261, 2, 2, 114, '["volatile · 指令重排序与 happens-befo"]', '危险后果：第一个判空看到 instance 非 null，实际构造未完成，读到脏字段', 1793348292769),
	(262, 2, 2, 114, '["volatile · 指令重排序与 happens-befo"]', '根本原因在 JMM 层面：写引用与写字段之间没有天然的 happens-before 保证', 1793348292769),
	(263, 2, 2, 115, '["CAS · 原理与三大问题"]', 'CAS 自增流程：读当前值→算 newValue→比较并交换→失败则自旋重试，AtomicLong.incrementAndGet 即此循环', 1793348292790),
	(264, 2, 2, 115, '["CAS · 原理与三大问题"]', 'CAS 用一条 CPU 原子指令完成「比较+替换」，无锁但有自旋', 1793348292790),
	(265, 2, 2, 115, '["CAS · 原理与三大问题"]', 'ABA：值 A→B→A 后 CAS 只看最终值，误以为没被改过', 1793348292790),
	(266, 2, 2, 115, '["CAS · 原理与三大问题"]', 'ABA 解法：AtomicStampedReference 加版本号，或对引用加时间戳', 1793348292790),
	(267, 2, 2, 94, '["synchronized · 三种使用形式与语义"]', '实例方法、synchronized(this) → 锁当前实例', 1793348292806),
	(268, 2, 2, 94, '["synchronized · 三种使用形式与语义"]', '静态方法、synchronized(X.class) → 锁该类的 Class 对象', 1793348292806),
	(269, 2, 2, 94, '["synchronized · 三种使用形式与语义"]', '实例锁只在一个实例内互斥，类锁对所有实例和静态资源互斥', 1793348292806),
	(270, 2, 2, 94, '["synchronized · 三种使用形式与语义"]', '判断口诀：看锁的是实例还是 Class 对象', 1793348292806),
	(271, 2, 2, 116, '["ReentrantLock · 与 synchronized"]', '可中断/可超时加锁选 ReentrantLock：tryLock(timeout, unit) 超时返回 false', 1793348292808),
	(272, 2, 2, 116, '["ReentrantLock · 与 synchronized"]', 'synchronized 无超时 API，拿不到锁只能无限阻塞', 1793348292808),
	(273, 2, 2, 116, '["ReentrantLock · 与 synchronized"]', '取舍：ReentrantLock 灵活但必须 finally 中手动 unlock', 1793348292808),
	(274, 2, 2, 116, '["ReentrantLock · 与 synchronized"]', '不需要超时、不需要公平/多条件时优先 synchronized，写法更简洁', 1793348292808),
	(275, 2, 2, 121, '["happens-before 与 volatile 禁止重排"]', 'happens-before：A hb B，则 A 的结果对 B 可见、顺序在 B 之前', 1793348292822),
	(276, 2, 2, 121, '["happens-before 与 volatile 禁止重排"]', 'volatile 写 happens-before 之后对该 volatile 变量的读', 1793348292822),
	(277, 2, 2, 121, '["happens-before 与 volatile 禁止重排"]', 'volatile 写/读构成内存屏障，普通读写不能跨越它重排序', 1793348292822),
	(278, 2, 2, 121, '["happens-before 与 volatile 禁止重排"]', 'happens-before 保证的是可见性和顺序，不是执行时间先后', 1793348292822),
	(279, 2, 2, 122, '["synchronized · 锁对象辨析（实例/类/方法）"]', 'synchronized(this) 锁当前实例，synchronized(X.class) 锁 Class 对象', 1793348292838),
	(280, 2, 2, 122, '["synchronized · 锁对象辨析（实例/类/方法）"]', '两者锁对象不同，互不阻塞（不互斥）', 1793348292838),
	(281, 2, 2, 122, '["synchronized · 锁对象辨析（实例/类/方法）"]', '实例锁作用于单个实例，类锁作用于所有实例与静态资源', 1793348292838),
	(282, 2, 2, 122, '["synchronized · 锁对象辨析（实例/类/方法）"]', '同一把锁（同为实例或同为 Class）才互相阻塞', 1793348292838),
	(283, 2, 2, 123, '["原子性 · 复合操作不保证原子"]', 'check-then-act 是复合操作，检查与执行之间存在时间窗口', 1793348292854),
	(284, 2, 2, 123, '["原子性 · 复合操作不保证原子"]', '中间被其他线程改状态 → 检查结果过期 → 超卖/重复提交等并发问题', 1793348292854),
	(285, 2, 2, 123, '["原子性 · 复合操作不保证原子"]', '必须把「检查+执行」放在同一临界区整体加锁', 1793348292854),
	(286, 2, 2, 123, '["原子性 · 复合操作不保证原子"]', '典型例子：if (库存>0) 扣减，两线程都通过检查就会超卖', 1793348292854),
	(287, 2, 2, 117, '["CAS · 适用场景选型（无锁 vs 加锁）"]', '低竞争计数：AtomicInteger/CAS，无锁、性能好', 1793348292869),
	(288, 2, 2, 117, '["CAS · 适用场景选型（无锁 vs 加锁）"]', '高竞争计数：synchronized，自旋失败率高时 CAS 反而更慢', 1793348292869),
	(289, 2, 2, 117, '["CAS · 适用场景选型（无锁 vs 加锁）"]', 'CAS 代价是自旋重试，竞争越激烈失败越多、CPU 空转越严重', 1793348292869),
	(290, 2, 2, 117, '["CAS · 适用场景选型（无锁 vs 加锁）"]', '超高并发计数可考虑 LongAdder 分段累加降低冲突', 1793348292869),
	(291, 2, 2, 129, '["CAS · 高竞争下的自旋与退化到锁"]', '自旋退出判据：自旋次数/时间达到阈值就停止，线程挂起转阻塞', 1793348328644),
	(292, 2, 2, 129, '["CAS · 高竞争下的自旋与退化到锁"]', 'HotSpot 有自适应自旋：按上次自旋成败动态调整本次阈值', 1793348328644),
	(293, 2, 2, 129, '["CAS · 高竞争下的自旋与退化到锁"]', '自旋是拿 CPU 换响应，阻塞是让出 CPU，阈值决定二者切换点', 1793348328644),
	(294, 2, 2, 118, '["synchronized · 方法锁与静态方法锁的对象差异"]', '静态 synchronized 锁 Class 对象（如 Foo.class），实例 synchronized 锁 this', 1793348328660),
	(295, 2, 2, 118, '["synchronized · 方法锁与静态方法锁的对象差异"]', '监视器不同即不互斥；要互斥必须锁同一对象', 1793348328660),
	(296, 2, 2, 118, '["synchronized · 方法锁与静态方法锁的对象差异"]', 'static 同步方法与非 static 同步方法可以并发执行', 1793348328660),
	(297, 2, 2, 119, '["自增操作 · 非原子导致计数丢失"]', 'count++ = 读-改-写三步，非原子，并发下丢更新', 1793348328660),
	(298, 2, 2, 119, '["自增操作 · 非原子导致计数丢失"]', '修正：synchronized/Lock 同步三步，或 AtomicInteger（CAS）、LongAdder', 1793348328660),
	(299, 2, 2, 119, '["自增操作 · 非原子导致计数丢失"]', 'volatile 不能保证 count++ 的原子性，只保证可见性', 1793348328660),
	(300, 2, 2, 124, '["ReentrantLock · 可重入次数上限"]', '可重入 = 同一线程可重复获取自己持有的同一把锁，记录重入次数', 1793348328676),
	(301, 2, 2, 124, '["ReentrantLock · 可重入次数上限"]', '递归加锁不会自我死锁；死锁来自多把锁交叉获取', 1793348328676),
	(302, 2, 2, 124, '["ReentrantLock · 可重入次数上限"]', '持锁过深的风险：持锁时间长、栈中锁记录膨胀、可能升级为重量级锁', 1793348328676),
	(303, 2, 2, 125, '["synchronized · 竞态条件导致重复扣款"]', 'check-then-act（先检查后执行）是典型竞态来源', 1793348328693),
	(304, 2, 2, 125, '["synchronized · 竞态条件导致重复扣款"]', '根因：复合操作无原子性、无互斥，检查与执行间有时间窗口', 1793348328693),
	(305, 2, 2, 125, '["synchronized · 竞态条件导致重复扣款"]', '修复方向：同一同步块/Lock/原子 CAS 把三步变成原子', 1793348328693),
	(306, 2, 2, 126, '["wait/notify · 唤醒后仍需竞争锁"]', 'notify 只把线程移入同步队列，返回 wait 前必须重新抢到锁', 1793348328693),
	(307, 2, 2, 126, '["wait/notify · 唤醒后仍需竞争锁"]', 'wait 被唤醒后条件可能已变，必须 while 循环重检条件', 1793348328693),
	(308, 2, 2, 126, '["wait/notify · 唤醒后仍需竞争锁"]', 'wait 释放锁、notify 不释放锁，两者都需持有监视器', 1793348328693),
	(309, 2, 2, 132, '["ReentrantLock · tryLock 超时与可中断","Condition · 多条件等待唤醒","ReentrantLock · 公平锁与非公平锁"]', 'await = 原子地「释放锁 + 进入 condition 等待队列」，必须先持有锁，否则抛 IllegalMonitorStateException', 1793348328710),
	(310, 2, 2, 132, '["ReentrantLock · tryLock 超时与可中断","Condition · 多条件等待唤醒","ReentrantLock · 公平锁与非公平锁"]', 'signal = 唤醒一个等待线程转入同步队列，被唤醒线程要等 signal 线程释放锁后竞争到锁才从 await 返回', 1793348328710),
	(311, 2, 2, 132, '["ReentrantLock · tryLock 超时与可中断","Condition · 多条件等待唤醒","ReentrantLock · 公平锁与非公平锁"]', 'signalAll 唤醒全部 → 惊群、逐个抢锁、性能下降，必须配合 while 重检条件才能守住一次放行一个', 1793348328710),
	(312, 2, 2, 127, '["volatile · 引用替换与对象字段修改的可见性差异","volatile · 指令重排序与happens-befor","volatile · 状态标志位典型用法"]', '半初始化根源：普通字段无可见性+指令重排，引用先于构造完成发布', 1793348328726),
	(313, 2, 2, 127, '["volatile · 引用替换与对象字段修改的可见性差异","volatile · 指令重排序与happens-befor","volatile · 状态标志位典型用法"]', 'volatile 引用 = 安全发布，读到的一定是构造完成的对象，前提是对象不可变、不逸出 this', 1793348328726),
	(314, 2, 2, 127, '["volatile · 引用替换与对象字段修改的可见性差异","volatile · 指令重排序与happens-befor","volatile · 状态标志位典型用法"]', 'volatile 够用判据：单引用原子替换 + 只读；需要原子性/互斥（读改写、check-then-act、多字段一致）时必须加锁', 1793348328726),
	(315, 2, 2, 130, '["synchronized · 实例锁与类锁的锁定对象","synchronized锁升级 · 升级后状态变化与降级","synchronized · 实例锁与类锁互斥关系"]', '实例 synchronized 方法锁 this（对象实例），静态 synchronized 方法锁 Class 对象，两者互不干扰。', 1793348328726),
	(316, 2, 2, 130, '["synchronized · 实例锁与类锁的锁定对象","synchronized锁升级 · 升级后状态变化与降级","synchronized · 实例锁与类锁互斥关系"]', 'synchronized(this) 与实例 synchronized 方法锁同一对象，可互斥；换锁对象（如 synchronized(other) 或 new Object()）则不互斥。', 1793348328726),
	(317, 2, 2, 130, '["synchronized · 实例锁与类锁的锁定对象","synchronized锁升级 · 升级后状态变化与降级","synchronized · 实例锁与类锁互斥关系"]', '判互斥的唯一标准：两段代码竞争的**是不是同一把锁对象**。', 1793348328726),
	(318, 2, 2, 131, '["CAS · 自旋开销与高并发下的性能退化","volatile · DCL单例中的指令重排与对象逸出","synchronized锁升级 · 单向不可逆与不可降级"]', 'volatile 只保证可见性与禁止重排序，**不保证原子性**，`count++` 这类读-改-写复合操作仍会丢更新。', 1793348328744),
	(319, 2, 2, 131, '["CAS · 自旋开销与高并发下的性能退化","volatile · DCL单例中的指令重排与对象逸出","synchronized锁升级 · 单向不可逆与不可降级"]', '准确计数用 AtomicLong（CAS）或 synchronized（锁互斥）；volatile 计数器只能用于"一写多读"或状态标志。', 1793348328744),
	(320, 2, 2, 131, '["CAS · 自旋开销与高并发下的性能退化","volatile · DCL单例中的指令重排与对象逸出","synchronized锁升级 · 单向不可逆与不可降级"]', '可见性不等于原子性：读到最新值后，多个线程仍可能基于同一旧值各自计算再写回。', 1793348328744),
	(321, 2, 2, 128, '["volatile · 保证可见性但不保证原子性","CAS · 高竞争下的适用性与放弃策略","volatile对引用替换与字段修改的差异"]', 'LongAdder 用 base + Cell 分段 + CAS 累加，sum() 汇总，**不丢增量**，只是 sum() 非原子快照；高并发下吞吐优于 AtomicLong。', 1793348328760),
	(322, 2, 2, 128, '["volatile · 保证可见性但不保证原子性","CAS · 高竞争下的适用性与放弃策略","volatile对引用替换与字段修改的差异"]', '`x++` 是读-改-写三步，volatile 只保证可见性/禁重排，救不了复合操作的原子性。', 1793348328760),
	(323, 2, 2, 128, '["volatile · 保证可见性但不保证原子性","CAS · 高竞争下的适用性与放弃策略","volatile对引用替换与字段修改的差异"]', '选型：低并发/需强一致用 AtomicLong 或 synchronized；超高并发统计用 LongAdder；volatile 只适合一写多读或标志位。', 1793348328760),
	(324, 2, 4, 134, '["线程池工作流程 · 主干执行链路"]', '线程池处理顺序：核心线程 → 入队 → 最大线程 → 拒绝', 1793609767363),
	(325, 2, 4, 134, '["线程池工作流程 · 主干执行链路"]', '判断顺序固定，与参数大小无关', 1793609767363),
	(326, 2, 4, 135, '["拒绝策略 · AbortPolicy"]', '默认拒绝策略 AbortPolicy，抛 RejectedExecutionException', 1793609767385),
	(327, 2, 4, 135, '["拒绝策略 · AbortPolicy"]', '被拒绝的任务不入队、不执行，直接丢弃，异常抛回调用方', 1793609767385),
	(328, 2, 4, 136, '["四种内置线程池 · 逐一识别"]', '一批任务并发跑：newFixedThreadPool（配合 CountDownLatch/Future 等待完成）', 1793609767396),
	(329, 2, 4, 136, '["四种内置线程池 · 逐一识别"]', '单线程顺序执行：newSingleThreadExecutor', 1793609767396),
	(330, 2, 4, 136, '["四种内置线程池 · 逐一识别"]', '定时/周期任务：newScheduledThreadPool', 1793609767396),
	(331, 2, 4, 137, '["拒绝策略 · CallerRunsPolicy"]', 'CallerRunsPolicy：由提交任务的调用线程自己执行', 1793609767407),
	(332, 2, 4, 137, '["拒绝策略 · CallerRunsPolicy"]', '形成反压、不丢任务，但会拉长调用方响应时间', 1793609767407),
	(333, 2, 4, 140, '["线程池参数 · workQueue"]', '无界队列（LinkedBlockingQueue）：线程数最多到核心数，max 不生效，易 OOM', 1793609767416),
	(334, 2, 4, 140, '["线程池参数 · workQueue"]', '有界队列（ArrayBlockingQueue）：队满才建新线程到 max，之后拒绝', 1793609767416),
	(335, 2, 4, 140, '["线程池参数 · workQueue"]', '同步移交队列（SynchronousQueue）：不存储，直接移交，无空闲线程就建新线程', 1793609767416),
	(336, 2, 4, 133, '["线程池参数 · handler"]', '拒绝策略触发条件：线程数达最大且队列已满', 1793609767427),
	(337, 2, 4, 133, '["线程池参数 · handler"]', '作用：兜底处理，把丢不丢任务变成显式策略选择', 1793609767427),
	(338, 2, 4, 61, '["自定义线程池 · 线程数怎么定"]', 'CPU 密集：线程数约核数+1，多了只会上下文切换争抢', 1793609767436),
	(339, 2, 4, 61, '["自定义线程池 · 线程数怎么定"]', 'IO 密集：线程数约核数×2 或更高，线程多在等 IO', 1793609767436),
	(340, 2, 4, 61, '["自定义线程池 · 线程数怎么定"]', '经验公式不是定值，需按实际压测调整', 1793609767436),
	(341, 2, 4, 84, '["自定义线程池 · 自定义线程工厂与命名规范"]', 'ThreadFactory 管的是线程怎么被创建：名字、daemon、优先级、异常处理器', 1793609767447),
	(342, 2, 4, 84, '["自定义线程池 · 自定义线程工厂与命名规范"]', '默认线程名 pool-x-thread-y 看不出业务归属，排查困难', 1793609767447),
	(343, 2, 4, 138, '["线程池 · 核心工作流程"]', '提交任务四步走：核心线程没满建核心线程 → 队列没满入队 → 队列满且没到最大线程数建非核心线程 → 都满了走拒绝策略', 1793609767456),
	(344, 2, 4, 138, '["线程池 · 核心工作流程"]', '先入队再扩容：队列没满时绝不会创建非核心线程，这是很多人答反的地方', 1793609767456),
	(345, 2, 4, 138, '["线程池 · 核心工作流程"]', '每一步的判断都是「当前线程数 vs 阈值」或「队列是否满」，先判断后动作', 1793609767456),
	(346, 2, 4, 139, '["四种内置线程池 · 为什么不推荐直接用 Executors 创建"]', 'FixedThreadPool、SingleThreadExecutor：无界 LinkedBlockingQueue → 任务堆积 OOM', 1793609767468),
	(347, 2, 4, 139, '["四种内置线程池 · 为什么不推荐直接用 Executors 创建"]', 'CachedThreadPool、ScheduledThreadPoolExecutor 的 maximumPoolSize 是 Integer.MAX_VALUE，但 Cached 的 OOM 主因是线程数无限增长（SynchronousQueue 不存任务）', 1793609767468),
	(348, 2, 4, 139, '["四种内置线程池 · 为什么不推荐直接用 Executors 创建"]', '手写 new ThreadPoolExecutor 的核心收益：给 workQueue 设容量上限、线程名前缀、显式拒绝策略', 1793609767468),
	(349, 2, 4, 139, '["四种内置线程池 · 为什么不推荐直接用 Executors 创建"]', '归因口诀：先看队列有界没界，再看最大线程数是不是 MAX_VALUE', 1793609767468),
	(350, 2, 4, 145, '["自定义线程池 · 为什么要自定义"]', 'FixedThreadPool 风险：LinkedBlockingQueue 容量 Integer.MAX_VALUE，任务堆积 OOM', 1793612080526),
	(351, 2, 4, 145, '["自定义线程池 · 为什么要自定义"]', 'CachedThreadPool 风险：maximumPoolSize 为 Integer.MAX_VALUE，线程无限创建耗尽内存', 1793612080526),
	(352, 2, 4, 145, '["自定义线程池 · 为什么要自定义"]', '手动 new ThreadPoolExecutor 显式定队列长度、核心/最大线程数、拒绝策略，线程命名便于排查', 1793612080526),
	(353, 2, 4, 146, '["线程池七大参数 · 逐个含义"]', '七大参数：corePoolSize、maximumPoolSize、keepAliveSize/keepAliveTime、TimeUnit、workQueue、threadFactory、RejectedExecutionHandler', 1793612080545),
	(354, 2, 4, 146, '["线程池七大参数 · 逐个含义"]', 'core/maximum 决定线程数量与扩容上限，workQueue 决定积压与拒绝触发时机', 1793612080545),
	(355, 2, 4, 146, '["线程池七大参数 · 逐个含义"]', 'RejectedExecutionHandler 是拒绝策略，不是异常处理', 1793612080545),
	(356, 2, 4, 147, '["自定义线程池 · 参数怎么定"]', '核心线程数估算：并发数 ≈ QPS × 单任务耗时，100 × 0.2s ≈ 20', 1793612080559),
	(357, 2, 4, 147, '["自定义线程池 · 参数怎么定"]', '最大线程数的作用是限制线程总数、作为突发缓冲，不是防 OOM', 1793612080559),
	(358, 2, 4, 147, '["自定义线程池 · 参数怎么定"]', '不能丢任务 → 拒绝策略选 CallerRunsPolicy 或自定义持久化重试', 1793612080559),
	(359, 2, 4, 148, '["线程池参数 · corePoolSize 与 maximumPoolSize"]', 'corePoolSize 是常驻线程数，maximumPoolSize 是线程数上限', 1793612080570),
	(360, 2, 4, 148, '["线程池参数 · corePoolSize 与 maximumPoolSize"]', '执行顺序：核心线程满 → 任务入队 → 队列满才扩到最大线程数', 1793612080570),
	(361, 2, 4, 148, '["线程池参数 · corePoolSize 与 maximumPoolSize"]', '日常配置 maximumPoolSize 略大于 corePoolSize，只作突发兜底', 1793612080570),
	(362, 2, 4, 141, '["自定义线程池 · 为什么不用 Executors"]', '阿里手册：禁止用 Executors 创建线程池，必须手动 ThreadPoolExecutor 显式指定参数', 1793612080580),
	(363, 2, 4, 141, '["自定义线程池 · 为什么不用 Executors"]', 'Fixed/SingleThread 走无界队列，Cached 最大线程数 MAX_VALUE，Scheduled 队列无界', 1793612080580),
	(364, 2, 4, 141, '["自定义线程池 · 为什么不用 Executors"]', '共同风险：任务或线程堆积导致 OOM', 1793612080580),
	(365, 2, 4, 142, '["线程池队列类型 · 三种典型选择"]', '有界队列：可控积压、触发拒绝策略做反压，适合大多数业务', 1793612080592),
	(366, 2, 4, 142, '["线程池队列类型 · 三种典型选择"]', '无界队列：任务量可控时宁排队不丢，代价是失去流量控制', 1793612080592),
	(367, 2, 4, 142, '["线程池队列类型 · 三种典型选择"]', 'SynchronousQueue 不存储直接移交，适合短平快、低延迟的小量任务', 1793612080592),
	(368, 2, 4, 143, '["自定义线程池 · 自定义线程工厂与命名规范"]', '自定义 ThreadFactory 最大价值：线程命名，jstack/日志一眼定位归属', 1793612080603),
	(369, 2, 4, 143, '["自定义线程池 · 自定义线程工厂与命名规范"]', '治理侧：统一设守护线程、优先级、线程组等属性', 1793612080603),
	(370, 2, 4, 143, '["自定义线程池 · 自定义线程工厂与命名规范"]', '可统一挂 UncaughtExceptionHandler，避免任务异常静默丢失', 1793612080603),
	(371, 2, 4, 144, '["拒绝策略 · 四种内置策略"]', 'AbortPolicy：抛 RejectedExecutionException，是 ThreadPoolExecutor 默认策略', 1793612080614),
	(372, 2, 4, 144, '["拒绝策略 · 四种内置策略"]', 'CallerRunsPolicy：提交线程自己跑，天然反压、不丢任务', 1793612080614),
	(373, 2, 4, 144, '["拒绝策略 · 四种内置策略"]', 'DiscardPolicy 静默丢新任务；DiscardOldestPolicy 丢队头最老任务后重新提交当前任务', 1793612080614),
	(374, 2, 4, 149, '["线程池 · 为什么要用"]', 'new Thread 的问题：创建/销毁开销大、线程数无上限导致上下文切换与资源耗尽、无法统一管理监控', 1793612080626),
	(375, 2, 4, 149, '["线程池 · 为什么要用"]', '线程池两大机制：Worker 线程复用（省创建销毁）+ 核心/最大线程数与队列控量（削峰、防雪崩）', 1793612080626),
	(376, 2, 4, 149, '["线程池 · 为什么要用"]', '核心线程与非核心线程都复用，区别是空闲超时后非核心线程会被回收', 1793612080626),
	(377, 2, 4, 150, '["线程池参数 · workQueue","线程池参数 · handler","拒绝策略 · AbortPolicy"]', '四策略一句话：Abort 抛异常（默认）、CallerRuns 提交线程执行（反压限流）、Discard 静默丢、DiscardOldest 丢队头最老任务', 1793612080638),
	(378, 2, 4, 150, '["线程池参数 · workQueue","线程池参数 · handler","拒绝策略 · AbortPolicy"]', '无界队列 = 永不拒绝 + 无限堆积 OOM；有界队列 = 可控内存 + 触发拒绝策略，队列越小越早扩到最大线程数', 1793612080638),
	(379, 2, 4, 150, '["线程池参数 · workQueue","线程池参数 · handler","拒绝策略 · AbortPolicy"]', '突发流量搭配：核心线程按常态流量、队列中小容量、最大线程数设弹性上限，队列满先扩线程、再拒绝', 1793612080638),
	(380, 2, 4, 150, '["线程池参数 · workQueue","线程池参数 · handler","拒绝策略 · AbortPolicy"]', '自定义拒绝策略核心：拒绝时落库/MQ 兜底 + 异步补录重试，配套限流降级、监控告警、扩容，取舍在延迟/存储成本与不丢任务之间', 1793612080638),
	(381, 2, 4, 157, '["拒绝策略 · DiscardPolicy 与 DiscardOldestPoli"]', 'AbortPolicy：抛 RejectedExecutionException，任务被拒，调用方能感知。', 1793690690213),
	(382, 2, 4, 157, '["拒绝策略 · DiscardPolicy 与 DiscardOldestPoli"]', 'DiscardPolicy：静默丢弃，不抛异常，任务丢失无感知。', 1793690690213),
	(383, 2, 4, 157, '["拒绝策略 · DiscardPolicy 与 DiscardOldestPoli"]', '差异本质是失败是否对调用方可见：要兜底用 Abort，允许丢才用 Discard。', 1793690690213),
	(384, 2, 4, 157, '["拒绝策略 · DiscardPolicy 与 DiscardOldestPoli"]', '另两种：DiscardOldest 丢队首最老任务；CallerRunsPolicy 让提交任务的线程自己执行。', 1793690690213),
	(385, 2, 4, 151, '["线程池参数 · threadFactory"]', 'threadFactory 是生产线程池中线程的工厂，默认 Executors.defaultThreadFactory()。', 1793690690229),
	(386, 2, 4, 151, '["线程池参数 · threadFactory"]', '项目里最核心的作用：给线程统一起业务名，线程 dump/日志一眼定位归属。', 1793690690229),
	(387, 2, 4, 151, '["线程池参数 · threadFactory"]', '还能设置守护线程、优先级、线程分组、UncaughtExceptionHandler。', 1793690690229),
	(388, 2, 4, 151, '["线程池参数 · threadFactory"]', '写法：实现 ThreadFactory，在 newThread 里 setName("业务名-" + 自增序号) 再返回。', 1793690690229),
	(389, 2, 4, 158, '["拒绝策略 · 自定义拒绝策略"]', '自定义拒绝策略 = 实现 RejectedExecutionHandler，重写 rejectedExecution(Runnable r, ThreadPoolExecutor e)。', 1793690690245),
	(390, 2, 4, 158, '["拒绝策略 · 自定义拒绝策略"]', '实现后作为 ThreadPoolExecutor 构造参数传入，可封装成静态类或工厂方法。', 1793690690245),
	(391, 2, 4, 158, '["拒绝策略 · 自定义拒绝策略"]', '典型兜底：记日志/告警、落库或发 MQ 补偿重试、降级走备用线程池。', 1793690690245),
	(392, 2, 4, 158, '["拒绝策略 · 自定义拒绝策略"]', '注意：兜底方法里不要再向同一个线程池提交任务，避免死循环。', 1793690690245),
	(393, 2, 4, 153, '["线程池参数调优 · CPU/IO密集型线程数设置"]', 'CPU 密集型：线程数 = CPU 核心数 + 1，+1 是防止某线程短暂停顿时 CPU 空转。', 1793690690262),
	(394, 2, 4, 153, '["线程池参数调优 · CPU/IO密集型线程数设置"]', 'IO 密集型：线程数 = 核心数 × 2 起（2~n 倍），靠压测定具体值。', 1793690690262),
	(395, 2, 4, 153, '["线程池参数调优 · CPU/IO密集型线程数设置"]', '差异根源：CPU 密集线程不阻塞，多了只增加切换；IO 密集线程常阻塞，多了才能喂饱 CPU。', 1793690690262),
	(396, 2, 4, 153, '["线程池参数调优 · CPU/IO密集型线程数设置"]', '线程多了不是越多越好，切换开销和内存都要算进去。', 1793690690262),
	(397, 2, 4, 154, '["线程池 · 同步移交队列适用场景"]', 'SynchronousQueue 不存储元素，每个 put 必须等一个 take，任务是直接交接的。', 1793690690278),
	(398, 2, 4, 154, '["线程池 · 同步移交队列适用场景"]', '有空闲线程就直接移交任务；没有且未达 maxPoolSize 才新建线程；达上限走拒绝策略。', 1793690690278),
	(399, 2, 4, 154, '["线程池 · 同步移交队列适用场景"]', '典型场景：任务突发、执行短、量不可预期，要求立即执行不排队，如 CachedThreadPool。', 1793690690278),
	(400, 2, 4, 154, '["线程池 · 同步移交队列适用场景"]', '它不缓冲，所以没有"队列积压"概念，也不存在"队列满"。', 1793690690278),
	(401, 2, 4, 155, '["四种内置线程池 · 为什么不推荐直接用 Executors 创建"]', 'Fixed/Single：LinkedBlockingQueue 无界队列 → 任务堆积 OOM，拒绝策略形同虚设。', 1793690690293),
	(402, 2, 4, 155, '["四种内置线程池 · 为什么不推荐直接用 Executors 创建"]', 'Cached：SynchronousQueue + maxPoolSize=Integer.MAX_VALUE → 线程数暴涨 OOM。', 1793690690293),
	(403, 2, 4, 155, '["四种内置线程池 · 为什么不推荐直接用 Executors 创建"]', '阿里手册要求手写 new ThreadPoolExecutor：容量参数显式可控，能配拒绝策略与监控。', 1793690690293),
	(404, 2, 4, 155, '["四种内置线程池 · 为什么不推荐直接用 Executors 创建"]', '核心风险是"边界不可控"：要么队列无界，要么线程数无界。', 1793690690293),
	(405, 2, 4, 159, '["线程池参数 · keepAliveTime 与 unit"]', 'keepAliveTime 是空闲时长的数值，unit 是它的单位，二者相乘才是回收阈值。', 1793690690294),
	(406, 2, 4, 159, '["线程池参数 · keepAliveTime 与 unit"]', '只有 corePoolSize 之外多创建的线程空闲超过该时长才会被回收。', 1793690690294),
	(407, 2, 4, 159, '["线程池参数 · keepAliveTime 与 unit"]', 'allowCoreThreadTimeOut(true) 可让核心线程也在空闲超时后回收。', 1793690690294),
	(408, 2, 4, 159, '["线程池参数 · keepAliveTime 与 unit"]', '注意：开启后 keepAliveTime 必须 > 0，否则会抛 IllegalStateException。', 1793690690294),
	(409, 2, 4, 152, '["内置线程池的风险 · 无界队列与MAX_VALUE"]', 'FixedThreadPool：LinkedBlockingQueue 无界队列 + 线程数固定 → 积压 OOM，拒绝策略永不触发。', 1793690690313),
	(410, 2, 4, 152, '["内置线程池的风险 · 无界队列与MAX_VALUE"]', 'CachedThreadPool：SynchronousQueue + maxPoolSize=Integer.MAX_VALUE → 无空闲线程就新建，线程暴涨 OOM。', 1793690690313),
	(411, 2, 4, 152, '["内置线程池的风险 · 无界队列与MAX_VALUE"]', '不适合生产的本质：队列容量/线程数上限不可控，无法限流与兜底。', 1793690690313),
	(412, 2, 4, 152, '["内置线程池的风险 · 无界队列与MAX_VALUE"]', '生产要手写 ThreadPoolExecutor：显式设核心数、最大数、有界队列、拒绝策略。', 1793690690313),
	(413, 2, 4, 160, '["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · corePoolSize 与 maximumPoolSize"]', '无界队列会吞掉所有任务，永不触发非核心线程创建，maximumPoolSize 失效', 1793690690337),
	(414, 2, 4, 160, '["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · corePoolSize 与 maximumPoolSize"]', '扩容到最大线程数的触发条件是『队列满』，所以队列必须有界且容量要小', 1793690690337),
	(415, 2, 4, 160, '["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · corePoolSize 与 maximumPoolSize"]', 'core < max，队列有界，拒绝策略按业务选（CallerRunsPolicy 会阻塞调用方）', 1793690690337),
	(416, 2, 4, 160, '["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · corePoolSize 与 maximumPoolSize"]', '参数定值看压测与监控：CPU 密集看核数，IO 密集可加大线程数', 1793690690337),
	(417, 2, 4, 165, '["同步移交队列SynchronousQueue · 特性与适用场景"]', 'SynchronousQueue 不存任务，任务来一个就直接交给线程（核心满了就开非核心线程）', 1793692354883),
	(418, 2, 4, 165, '["同步移交队列SynchronousQueue · 特性与适用场景"]', '适合低延迟、任务短、突发且并发量不可预估的场景', 1793692354883),
	(419, 2, 4, 165, '["同步移交队列SynchronousQueue · 特性与适用场景"]', '提交速率 > 处理速率时线程涨到 maximumPoolSize，仍接不下就走拒绝策略', 1793692354883),
	(420, 2, 4, 166, '["四种内置线程池 · newFixedThreadPool 的队列陷阱"]', '固定线程数配置对应 newFixedThreadPool，线程数构造时显式指定', 1793692354883),
	(421, 2, 4, 166, '["四种内置线程池 · newFixedThreadPool 的队列陷阱"]', '并发量可预估 → 线程数直接按预期并发设，稳定且省去线程创建开销', 1793692354883),
	(422, 2, 4, 166, '["四种内置线程池 · newFixedThreadPool 的队列陷阱"]', '无界队列风险：任务堆积占内存导致 OOM，且最大线程数形同虚设', 1793692354883),
	(423, 2, 4, 167, '["串联 · 一次线程池 OOM 排查到参数重建"]', 'CachedThreadPool 隐患：max=Integer.MAX_VALUE，突发下线程数暴涨', 1793692354903),
	(424, 2, 4, 167, '["串联 · 一次线程池 OOM 排查到参数重建"]', 'FixedThreadPool 隐患：无界队列堆积任务，堆内存 OOM', 1793692354903),
	(425, 2, 4, 167, '["串联 · 一次线程池 OOM 排查到参数重建"]', '有界化关键：有界队列容量 + 显式 maximumPoolSize + 合适的拒绝策略', 1793692354903),
	(426, 2, 4, 168, '["四种内置线程池 · newCachedThreadPool 的线程爆炸"]', '短平快任务适合 newCachedThreadPool：SynchronousQueue 不排队，提交即执行', 1793692354915),
	(427, 2, 4, 168, '["四种内置线程池 · newCachedThreadPool 的线程爆炸"]', '线程数爆的原因：max=Integer.MAX_VALUE + 提交速率超过执行速率 → 线程无限新建', 1793692354915),
	(428, 2, 4, 168, '["四种内置线程池 · newCachedThreadPool 的线程爆炸"]', '缓解：限提交速率/换有界线程池，别指望线程回收能扛住持续高并发', 1793692354915),
	(429, 2, 4, 161, '["线程池 · submit 与 execute 区别"]', 'execute：无返回值，异常抛给 Worker 线程（UncaughtExceptionHandler），需自己 try-catch', 1793692354930),
	(430, 2, 4, 161, '["线程池 · submit 与 execute 区别"]', 'submit：返回 Future，异常被封装，get() 时抛 ExecutionException', 1793692354930),
	(431, 2, 4, 161, '["线程池 · submit 与 execute 区别"]', 'invokeAll：批量提交并阻塞等待全部完成，返回 List<Future>', 1793692354930),
	(432, 2, 4, 162, '["自定义线程池 · 队列容量与非核心线程创建的平衡"]', '任务流转顺序：核心线程 → 队列 → 非核心线程 → 拒绝策略', 1793692354930),
	(433, 2, 4, 162, '["自定义线程池 · 队列容量与非核心线程创建的平衡"]', '队列太小：容易建满线程甚至拒绝；太大/无界：排队堆积、延迟不可控甚至 OOM', 1793692354930),
	(434, 2, 4, 162, '["自定义线程池 · 队列容量与非核心线程创建的平衡"]', '容量按「可容忍排队时长 × 吞吐」估算，宁可有界 + 合理拒绝策略', 1793692354930),
	(435, 2, 4, 163, '["拒绝策略 · 自定义拒绝策略"]', 'reject() 跑在提交任务的调用线程，里面不能长时间阻塞或做重活', 1793692354946),
	(436, 2, 4, 163, '["拒绝策略 · 自定义拒绝策略"]', '兜底不丢任务 = 快速持久化（DB/磁盘/MQ）+ 事后补偿/定时重试', 1793692354946),
	(437, 2, 4, 163, '["拒绝策略 · 自定义拒绝策略"]', '抛异常本身等于丢任务，需调用方捕获转降级或落库，二者是取舍', 1793692354946),
	(438, 2, 4, 164, '["线程池 · 无界队列适用场景"]', '无界队列适用：总量有限/可预估、允许排队的批处理、脚本类任务', 1793692354970),
	(439, 2, 4, 164, '["线程池 · 无界队列适用场景"]', '代价一：任务堆积占内存，极端时 OOM', 1793692354970),
	(440, 2, 4, 164, '["线程池 · 无界队列适用场景"]', '代价二：排队延迟不可控，且 maximumPoolSize 永远不生效（队列永远不满）', 1793692354970),
	(441, 2, 4, 169, '["线程池参数 · threadFactory命名与问题定位"]', '线程名前缀是线程的**身份标识**：dump 线程栈时能立刻区分是哪个业务线程池、哪类任务的线程', 1793692363664),
	(442, 2, 4, 169, '["线程池参数 · threadFactory命名与问题定位"]', '给线程统一加前缀靠**自定义 ThreadFactory**（setName 前缀+自增序号）或 Guava 的 ThreadFactoryBuilder', 1793692363664),
	(443, 2, 4, 169, '["线程池参数 · threadFactory命名与问题定位"]', '线程池**构造器没有线程名参数**，ThreadFactory 是唯一入口，且要作为 threadFactory 参数传入', 1793692363664),
	(444, 2, 4, 170, '["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · workQueue"]', '线程池复用的两大机制：**Worker 线程执行完任务不退出、循环从阻塞队列取任务** + **阻塞队列缓冲待执行任务**', 1793692363680),
	(445, 2, 4, 170, '["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · workQueue"]', '复用省去线程**创建/销毁开销**与上下文切换，线程数可控，内存与 GC 压力小', 1793692363680),
	(446, 2, 4, 170, '["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · workQueue"]', '流转口诀：**核心满 → 入队 → 队满建非核心 → 达最大走拒绝**', 1793692363680),
	(447, 2, 4, 170, '["线程池 · 为什么要用","线程池 · 核心工作流程","线程池参数 · workQueue"]', '核心线程数：CPU 密集 **N+1**，IO 密集 **2N 起步靠压测调**；最大线程数用于抗突发，需与队列容量权衡', 1793692363680),
	(448, 2, 5, 175, '["循环依赖 · 构造器注入为何不行"]', '构造器循环依赖在**实例化阶段**就卡死：A 要 B、B 要 A，谁都无法先成型，启动即抛异常', 1793696539918),
	(449, 2, 5, 175, '["循环依赖 · 构造器注入为何不行"]', 'setter/字段注入靠**先实例化后填属性**的两阶段流程打破循环', 1793696539918),
	(450, 2, 5, 175, '["循环依赖 · 构造器注入为何不行"]', '早期引用通过缓存暴露，使后创建的 Bean 能注入到尚未初始化完的实例上', 1793696539918),
	(451, 2, 5, 177, '["Bean延迟加载 · @Lazy"]', '@Lazy 在**声明处**：Bean 变懒加载，首次使用才实例化', 1793696539934),
	(452, 2, 5, 177, '["Bean延迟加载 · @Lazy"]', '@Lazy 在**注入点**：注入的是**代理**，首次调用方法才换取真实 Bean', 1793696539934),
	(453, 2, 5, 177, '["Bean延迟加载 · @Lazy"]', '注入点的 @Lazy 常用于**打破循环依赖**或延迟重量级 Bean 的初始化', 1793696539934),
	(454, 2, 5, 171, '["IoC/DI · 概念与两种注入方式"]', '官方推荐**构造器注入**：依赖显式、对象创建即完整、便于测试与不可变设计', 1793696539949),
	(455, 2, 5, 171, '["IoC/DI · 概念与两种注入方式"]', '构造器参数可声明 **final**，注入后不可变，是"依赖不可变"的直接体现', 1793696539949),
	(456, 2, 5, 171, '["IoC/DI · 概念与两种注入方式"]', '构造器注入**解决不了循环依赖**，反而让循环在启动时 fail-fast 抛异常', 1793696539949),
	(457, 2, 5, 179, '["动态代理 · JDK与CGLIB"]', '有接口默认 **JDK 动态代理**，无接口默认 **CGLIB** 生成子类', 1793696539963),
	(458, 2, 5, 179, '["动态代理 · JDK与CGLIB"]', 'JDK 代理基于接口 + **InvocationHandler** 反射调用目标方法', 1793696539963),
	(459, 2, 5, 179, '["动态代理 · JDK与CGLIB"]', 'CGLIB 基于继承生成子类 + **MethodInterceptor** 拦截，注意目标类不能是 final', 1793696539963),
	(460, 2, 5, 188, '["AOP · 失效场景与原理"]', '切面只对**Spring 容器管理的 Bean 的代理对象**调用生效，自己 new 的对象没有代理，切面必然失效。', 1793778099689),
	(461, 2, 5, 188, '["AOP · 失效场景与原理"]', '方法必须是 **public 实例方法**且非 final/static，代理（JDK/CGLIB）才拦得住。', 1793778099689),
	(462, 2, 5, 188, '["AOP · 失效场景与原理"]', 'CGLIB 靠子类实现，**final 类或 final 方法**无法被覆写，增强失效。', 1793778099689),
	(463, 2, 5, 186, '["循环依赖 · 破坏方式与现状"]', '三级缓存救的是**属性填充期**的循环依赖，靠**提前暴露半成品早期引用**。', 1793778099695),
	(464, 2, 5, 186, '["循环依赖 · 破坏方式与现状"]', '构造器注入的依赖在**实例化阶段**就必须给全，此时对象尚未创建、无法暴露早期引用，所以必然失败。', 1793778099695),
	(465, 2, 5, 186, '["循环依赖 · 破坏方式与现状"]', '保留双向依赖时常用 **@Lazy 延迟注入**、抽第三对象、事件/getBean 延迟获取来破环。', 1793778099695),
	(466, 2, 5, 187, '["构造器注入 · 不可变性优势"]', 'final 字段只保证**引用不可重新赋值**，**不保证引用对象的内部状态不可变**。', 1793778099698),
	(467, 2, 5, 187, '["构造器注入 · 不可变性优势"]', '真正不可变类：类 final（或不泄漏 this）+ 字段 **private final** + 不提供修改方法。', 1793778099698),
	(468, 2, 5, 187, '["构造器注入 · 不可变性优势"]', '可变成员必须做**防御性拷贝**：入参拷贝进来、返回值拷贝出去。', 1793778099698),
	(469, 2, 5, 189, '["动态代理 · JDK与CGLIB选型"]', '无接口默认 **CGLIB**（子类代理），有接口时 JDK/CGLIB 都可，默认曾是 JDK。', 1793778099702),
	(470, 2, 5, 189, '["动态代理 · JDK与CGLIB选型"]', 'JDK 动态代理基于 **java.lang.reflect.Proxy + 接口**，无接口则无法生成代理。', 1793778099702),
	(471, 2, 5, 189, '["动态代理 · JDK与CGLIB选型"]', 'Spring Boot 强制 CGLIB：**spring.aop.proxy-target-class=true**。', 1793778099702),
	(472, 2, 5, 182, '["初始化与销毁 · 回调方式"]', '初始化顺序：**@PostConstruct → InitializingBean.afterPropertiesSet() → 自定义 init-method**。', 1793778099705),
	(473, 2, 5, 182, '["初始化与销毁 · 回调方式"]', 'afterPropertiesSet() **就是** InitializingBean 接口的回调，不是两个独立阶段。', 1793778099705),
	(474, 2, 5, 182, '["初始化与销毁 · 回调方式"]', '@PostConstruct 由注解处理器触发，在属性填充之后、接口回调之前执行。', 1793778099705),
	(475, 2, 5, 183, '["Bean配置 · 组件扫描与注册方式"]', '@ComponentScan 的 **value/basePackages** 指定扫描包，命中注解的类注册为 Bean，可指定多个。', 1793778099708),
	(476, 2, 5, 183, '["Bean配置 · 组件扫描与注册方式"]', 'Spring Boot 不显式指定时，扫描 **@SpringBootApplication 启动类所在包及其子包**。', 1793778099708),
	(477, 2, 5, 183, '["Bean配置 · 组件扫描与注册方式"]', '启动类放在子包会导致同级包漏扫——启动类要放在根包。', 1793778099708),
	(478, 2, 5, 190, '["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy"]', '构造器注入与字段注入都会在**启动期创建依赖**，启动耗时相同；只有 **@Lazy** 能把初始化推迟到首次调用。', 1793778099712),
	(479, 2, 5, 190, '["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy"]', '**Bean 上加 @Lazy** 延迟的是该 Bean 自身的创建；**注入点上加 @Lazy** 延迟的是这次注入（给的是延迟代理，多注入点各自决定）。', 1793778099712),
	(480, 2, 5, 190, '["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy"]', '依赖不可用：构造器注入**启动即失败（fail-fast）**，字段注入**首次调用才暴露**；可测试性上构造器注入最好（可直接 new）。', 1793778099712),
	(481, 2, 5, 190, '["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy"]', '配合 @Lazy 后，readiness 探针不能依赖风控 Bean 已初始化，应以应用自身就绪（端口/健康接口）为准。', 1793778099712),
	(482, 2, 5, 197, '["Bean生命周期 · 主干流程"]', 'Bean 生命周期主干顺序：实例化 → 属性赋值（DI）→ 初始化 → 使用 → 销毁。', 1793779949393),
	(483, 2, 5, 197, '["Bean生命周期 · 主干流程"]', '初始化阶段包含 Aware 回调、BeanPostProcessor 前置处理、init-method/@PostConstruct、BeanPostProcessor 后置处理（AOP 代理在此生成）。', 1793779949393),
	(484, 2, 5, 197, '["Bean生命周期 · 主干流程"]', '顺序不能颠倒：依赖没注入完不能进入初始化，否则 init 方法里拿到的依赖是 null。', 1793779949393),
	(485, 2, 5, 198, '["依赖注入 · @Autowired装配规则"]', '@Autowired 默认 **byType**；找不到再考虑 @Qualifier / @Primary / 名称回退。', 1793779949429),
	(486, 2, 5, 198, '["依赖注入 · @Autowired装配规则"]', '消歧优先级：@Qualifier 显式指定 > @Primary 首选 > 字段名或参数名与 Bean 名称一致。', 1793779949429),
	(487, 2, 5, 198, '["依赖注入 · @Autowired装配规则"]', '@Resource 默认是 byName，和 @Autowired 的默认策略正好相反。', 1793779949429),
	(488, 2, 5, 193, '["循环依赖 · 构造器注入无法解决循环依赖"]', '构造器注入的循环依赖报错根因：**实例化就必须拿到依赖**，而此时对方也还没实例化，无法提前暴露早期引用。', 1793779949436),
	(489, 2, 5, 193, '["循环依赖 · 构造器注入无法解决循环依赖"]', '改成 setter/字段注入后，依赖在属性赋值阶段才注入，可以通过三级缓存暴露早期引用解决循环。', 1793779949436),
	(490, 2, 5, 193, '["循环依赖 · 构造器注入无法解决循环依赖"]', '@Lazy 在注入点生成代理，把真实 Bean 的获取推迟到首次调用，从而打破实例化时的死锁。', 1793779949436),
	(491, 2, 5, 194, '["循环依赖 · 成因与检测"]', '循环依赖的判定标志：创建前把 Bean 名放入 **singletonsCurrentlyInCreation**，重复进入即视为循环。', 1793779949444),
	(492, 2, 5, 194, '["循环依赖 · 成因与检测"]', '单例 + setter 注入的循环靠三级缓存可解；**构造器注入、prototype 作用域**的循环解不了，直接抛 BeanCurrentlyInCreationException。', 1793779949444),
	(493, 2, 5, 194, '["循环依赖 · 成因与检测"]', '三级缓存：singletonObjects（成品）、earlySingletonObjects（早期引用）、singletonFactories（ObjectFactory）。', 1793779949444),
	(494, 2, 5, 195, '["AOP · 失效场景与原理"]', 'AOP 生效铁律：**调用必须走容器里的代理对象**，走原始对象一定失效。', 1793779949449),
	(495, 2, 5, 195, '["AOP · 失效场景与原理"]', '典型失效：类内 this 自调用、手动 new 对象、private/static/final 方法、非 Spring 管理的类。', 1793779949449),
	(496, 2, 5, 195, '["AOP · 失效场景与原理"]', '自调用可用 AopContext.currentProxy() 或拆到另一个 Bean 里调用来绕过。', 1793779949449),
	(497, 2, 5, 199, '["AOP · 核心概念与切点"]', '四要素：**Aspect 切面类**、**Advice 通知（做什么+何时做）**、**Pointcut 切点表达式（对谁做）**、**Joinpoint 连接点（可织入的执行点，通常是方法）**。', 1793779949451),
	(498, 2, 5, 199, '["AOP · 核心概念与切点"]', '常见通知：@Before、@After、@AfterReturning、@AfterThrowing、@Around。', 1793779949451),
	(499, 2, 5, 199, '["AOP · 核心概念与切点"]', '切点表达式 execution(* com.xx.service..*.*(..)) 用来圈定连接点集合。', 1793779949451),
	(500, 2, 5, 200, '["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy","Bean配置 · 组件扫描与注册方式"]', '组件扫描的成本在于**遍历包下所有 class 并解析注解/条件**，范围越大、无关类越多，启动越慢；应用 basePackages 精确到业务包。', 1793779949455),
	(501, 2, 5, 200, '["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy","Bean配置 · 组件扫描与注册方式"]', '@Lazy 收益是**把重初始化从启动期挪到首访期**；风险是问题延迟暴露、首访卡顿、启动时无法校验该 Bean 可用。', 1793779949455),
	(502, 2, 5, 200, '["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy","Bean配置 · 组件扫描与注册方式"]', '取舍原则：启动必须保证可用的核心 Bean 用构造器注入并**不加 @Lazy**；低频、重初始化、失败可容忍的 Bean 用 @Lazy。', 1793779949455),
	(503, 2, 5, 200, '["IoC/DI · 概念与两种注入方式","Bean延迟加载 · @Lazy","Bean配置 · 组件扫描与注册方式"]', '构造器注入保证对象创建即完整，setter/字段注入粒度更松、易掩盖循环依赖。', 1793779949455),
	(504, 2, 5, 201, '["循环依赖 · 三级缓存机制"]', '一级 singletonObjects：成品 Bean；二级 earlySingletonObjects：提前暴露的早期引用；三级 singletonFactories：ObjectFactory 工厂', 1793848341583),
	(505, 2, 5, 201, '["循环依赖 · 三级缓存机制"]', '获取依赖时按 一级 → 二级 → 三级 顺序查，任一层命中即返回并回填到上一级', 1793848341583),
	(506, 2, 5, 201, '["循环依赖 · 三级缓存机制"]', '三级缓存的 getObject 可能返回原始对象，也可能返回提前生成的 AOP 代理，这是三级缓存存在的关键理由', 1793848341583),
	(507, 2, 5, 224, '["Bean作用域 · singleton与prototype"]', '单例：容器只创建一个实例，所有注入点共享同一引用，容器负责完整生命周期', 1793848341589),
	(508, 2, 5, 224, '["Bean作用域 · singleton与prototype"]', '原型：每次 getBean 都新建实例，容器不缓存、也不负责销毁，销毁由调用方自己处理', 1793848341589),
	(509, 2, 5, 224, '["Bean作用域 · singleton与prototype"]', '原型 Bean 依赖单例没问题，单例 Bean 注入原型 Bean 只会拿到注入那一刻的那一个实例', 1793848341589),
	(510, 2, 5, 202, '["@Lazy · 延迟加载注入点"]', '@Lazy 标在 Bean 定义上：该 Bean 延迟初始化，第一次被使用才创建', 1793848341593),
	(511, 2, 5, 202, '["@Lazy · 延迟加载注入点"]', '@Lazy 标在注入点：注入延迟代理，调用该代理方法时才去容器取真实 Bean', 1793848341593),
	(512, 2, 5, 202, '["@Lazy · 延迟加载注入点"]', '注入点级别的懒加载彼此隔离，只影响标注的那一处注入', 1793848341593),
	(513, 2, 5, 202, '["@Lazy · 延迟加载注入点"]', '注入点 @Lazy 常用于打断构造器循环依赖', 1793848341593),
	(514, 2, 5, 203, '["依赖注入 · @Lazy延迟加载解决循环依赖"]', '构造器注入要求依赖在实例化时就已就绪，这是构造器循环依赖无法用三级缓存解决的根本原因', 1793848341597),
	(515, 2, 5, 203, '["依赖注入 · @Lazy延迟加载解决循环依赖"]', '构造器参数上加 @Lazy 注入的是延迟代理，启动时不会触发真实 Bean 的创建', 1793848341597),
	(516, 2, 5, 203, '["依赖注入 · @Lazy延迟加载解决循环依赖"]', '@Lazy 打断循环依赖的实质：把「必须先有真实对象」变成「先给一个占位代理」', 1793848341597),
	(517, 2, 5, 216, '["AOP · 内部方法自调用导致切面失效"]', 'this 调用绕过代理对象，直接走原始对象的实例方法，AOP 增强不会执行', 1793848341600),
	(518, 2, 5, 216, '["AOP · 内部方法自调用导致切面失效"]', 'Spring AOP 两种代理：接口用 JDK 动态代理，无接口用 CGLIB 子类代理', 1793848341600),
	(519, 2, 5, 216, '["AOP · 内部方法自调用导致切面失效"]', '解决自调用失效的常见方式：注入自身代理、AopContext.currentProxy()、拆分到另一个 Bean', 1793848341600),
	(520, 2, 5, 217, '["AOP · 与生命周期的关系"]', '代理对象在初始化完成之后、通过 BeanPostProcessor 环节生成，并替换掉容器中的 Bean 引用', 1793848341603),
	(521, 2, 5, 217, '["AOP · 与生命周期的关系"]', '容器按名字取、注入到其他 Bean 的永远是代理对象，不是原始对象', 1793848341603),
	(522, 2, 5, 217, '["AOP · 与生命周期的关系"]', '原始对象只作为代理的 target 存在；自调用时的 this 就是它，想从代码里取需 AopContext.currentProxy() 或解代理', 1793848341603),
	(523, 2, 5, 225, '["AOP · @Aspect/@Pointcut/@JoinPoint注解"]', '切面类：@Component + @Aspect；切点用 @Pointcut("execution(* com.example.service..*(..))") 圈定', 1793848341606),
	(524, 2, 5, 225, '["AOP · @Aspect/@Pointcut/@JoinPoint注解"]', 'execution 表达式结构：修饰符 返回类型 包.类.方法(参数)，.. 表示任意层级包或任意参数', 1793848341606),
	(525, 2, 5, 225, '["AOP · @Aspect/@Pointcut/@JoinPoint注解"]', '统计耗时最常用 @Around：proceed() 之前取开始时间、之后取结束时间相减，异常路径也能覆盖', 1793848341606),
	(526, 2, 5, 218, '["循环依赖 · 构造器注入无法解决"]', '提前暴露的关键窗口：实例化之后、属性填充之前，此时对象已分配但属性未填', 1793848341609),
	(527, 2, 5, 218, '["循环依赖 · 构造器注入无法解决"]', 'setter/字段注入发生在实例化之后，所以能接受半成品引用；构造器注入要在实例化之前拿到依赖，没有这个窗口', 1793848341609),
	(528, 2, 5, 218, '["循环依赖 · 构造器注入无法解决"]', '流程：new A → 暴露 A 的 ObjectFactory 到三级缓存 → 创建 B → 从缓存取 A 早期引用注入 → B 完成 → 回来完成 A → 清二三级缓存', 1793848341609),
	(529, 2, 5, 204, '["Bean生命周期 · @PostConstruct/@PreDestroy注解初"]', '初始化回调：@PostConstruct；销毁回调：@PreDestroy', 1793848341617),
	(530, 2, 5, 204, '["Bean生命周期 · @PostConstruct/@PreDestroy注解初"]', '@PostConstruct 在依赖注入完成后、初始化方法之前执行', 1793848341617),
	(531, 2, 5, 204, '["Bean生命周期 · @PostConstruct/@PreDestroy注解初"]', '@PreDestroy 在容器关闭、Bean 销毁前执行', 1793848341617),
	(532, 2, 5, 204, '["Bean生命周期 · @PostConstruct/@PreDestroy注解初"]', '也可以用 @Bean(initMethod/destroyMethod) 或实现 InitializingBean/DisposableBean 达到同样效果', 1793848341617),
	(533, 2, 5, 205, '["AOP · JDK动态代理基于接口实现"]', 'JDK 动态代理依赖接口，生成实现相同接口的代理对象，无接口则无法代理', 1793848341619),
	(534, 2, 5, 205, '["AOP · JDK动态代理基于接口实现"]', 'CGLIB 通过继承生成子类代理，无法代理 final 类和 final 方法', 1793848341619),
	(535, 2, 5, 205, '["AOP · JDK动态代理基于接口实现"]', 'Spring 的判断依据：目标类是否实现了接口', 1793848341619),
	(536, 2, 5, 205, '["AOP · JDK动态代理基于接口实现"]', 'Spring Boot 2.x 起 AOP 默认 proxyTargetClass=true，默认走 CGLIB', 1793848341619),
	(537, 2, 5, 206, '["@Autowired · 注入点与循环依赖"]', '构造器注入：实例化之前就要解析出全部构造参数依赖，拿不到就启动失败', 1793848341621),
	(538, 2, 5, 206, '["@Autowired · 注入点与循环依赖"]', '字段/Setter 注入：实例化之后才做属性填充，对象已存在，可以先暴露后解析', 1793848341621),
	(539, 2, 5, 206, '["@Autowired · 注入点与循环依赖"]', '注入时机不同是理解循环依赖能否被解决的关键前提', 1793848341621),
	(540, 2, 5, 207, '["Bean后处理器 · BeanPostProcessor"]', 'BeanPostProcessor 作用于容器中所有 Bean 实例', 1793848341624),
	(541, 2, 5, 207, '["Bean后处理器 · BeanPostProcessor"]', '两个回调时机：初始化方法之前（before）和之后（after）', 1793848341624),
	(542, 2, 5, 207, '["Bean后处理器 · BeanPostProcessor"]', 'AOP 自动代理就是通过 BeanPostProcessor 在初始化后生成代理对象', 1793848341624),
	(543, 2, 5, 207, '["Bean后处理器 · BeanPostProcessor"]', 'BeanPostProcessor 自身及其依赖的 Bean 不会被其它后置处理器处理', 1793848341624),
	(544, 2, 5, 208, '["AOP失效 · 同类内部this调用"]', '同类内部 this 调用不经过代理对象，AOP 增强失效', 1793848341626),
	(545, 2, 5, 208, '["AOP失效 · 同类内部this调用"]', '解决方式一：AopContext.currentProxy()，需 exposeProxy=true', 1793848341626),
	(546, 2, 5, 208, '["AOP失效 · 同类内部this调用"]', '解决方式二：把自己（代理）注入到自身字段，通过该字段调用', 1793848341626),
	(547, 2, 5, 208, '["AOP失效 · 同类内部this调用"]', '解决方式三：拆到另一个 Bean 里调用（本题不采用）', 1793848341626),
	(548, 2, 5, 210, '["依赖注入 · @Primary与@Qualifier消歧"]', '@Qualifier 位置：字段、构造器参数、方法参数，按 Bean 名称精确指定', 1793848341629),
	(549, 2, 5, 210, '["依赖注入 · @Primary与@Qualifier消歧"]', '@Conditional 位置：@Bean 方法、@Configuration 类，也可作元注解派生出 @ConditionalOnXxx', 1793848341629),
	(550, 2, 5, 210, '["依赖注入 · @Primary与@Qualifier消歧"]', '@Qualifier 解决同类型多 Bean 的歧义；@Conditional 解决是否注册/是否生效', 1793848341629),
	(551, 2, 5, 212, '["循环依赖 · 构造器注入为何不行"]', '属性注入：先实例化并暴露早期引用，再做属性填充，能打破循环', 1793848341631),
	(552, 2, 5, 212, '["循环依赖 · 构造器注入为何不行"]', '构造器注入：实例化前就要拿到完整依赖，无法暴露半成品，循环依赖直接报错', 1793848341631),
	(553, 2, 5, 212, '["循环依赖 · 构造器注入为何不行"]', 'Spring 的三级缓存就是为“提前暴露早期引用”服务', 1793848341631),
	(554, 2, 5, 212, '["循环依赖 · 构造器注入为何不行"]', '@Lazy 可以打断构造器注入的循环依赖', 1793848341631),
	(555, 2, 5, 213, '["AOP · 核心概念与切点"]', 'execution(返回值 类.方法(参数)) 是标准写法', 1793848341634),
	(556, 2, 5, 213, '["AOP · 核心概念与切点"]', '第一个 `*` 表示任意返回类型', 1793848341634),
	(557, 2, 5, 213, '["AOP · 核心概念与切点"]', '`get*` 表示以 get 开头的方法名', 1793848341634),
	(558, 2, 5, 213, '["AOP · 核心概念与切点"]', '`(..)` 表示任意个数、任意类型的参数，含无参', 1793848341634),
	(559, 2, 5, 214, '["初始化与销毁 · 回调方式"]', '@PostConstruct：依赖注入完成后、初始化阶段调用，早于 afterPropertiesSet', 1793848341669),
	(560, 2, 5, 214, '["初始化与销毁 · 回调方式"]', '@PreDestroy：容器关闭、Bean 销毁前调用，早于 DisposableBean.destroy', 1793848341669),
	(561, 2, 5, 214, '["初始化与销毁 · 回调方式"]', '「创建时」的说法不准确，要区分实例化与初始化', 1793848341669),
	(562, 2, 5, 215, '["IoC/DI · 概念与两种注入方式"]', '强制依赖用构造器注入：缺失即启动失败，字段可 final', 1793848341673),
	(563, 2, 5, 215, '["IoC/DI · 概念与两种注入方式"]', '可选依赖用 setter 或字段注入 + required=false，允许为空', 1793848341673),
	(564, 2, 5, 215, '["IoC/DI · 概念与两种注入方式"]', '@Lazy 解决的是延迟创建和循环依赖，不是可选依赖', 1793848341673),
	(565, 2, 5, 220, '["Bean延迟加载 · @Lazy"]', '@Lazy：推迟到首次使用才创建，可加在类、@Bean 方法或注入点上', 1793848341676),
	(566, 2, 5, 220, '["Bean延迟加载 · @Lazy"]', 'prototype：每次获取都新建实例，容器不缓存、不负责销毁', 1793848341676),
	(567, 2, 5, 220, '["Bean延迟加载 · @Lazy"]', 'prototype 适合有状态、不可共享的对象', 1793848341676),
	(568, 2, 5, 221, '["动态代理 · JDK与CGLIB"]', '有接口 → JDK 动态代理，代理类实现同一接口，只能按接口类型取', 1793848341680),
	(569, 2, 5, 221, '["动态代理 · JDK与CGLIB"]', '无接口 → CGLIB 生成子类代理，按类类型可取', 1793848341680),
	(570, 2, 5, 221, '["动态代理 · JDK与CGLIB"]', '决定因素：目标类是否实现接口 + proxyTargetClass 配置（Spring Boot 默认 CGLIB）', 1793848341680),
	(571, 2, 5, 222, '["循环依赖 · 破坏方式与现状"]', '字段、setter 循环依赖：在其中一个注入点加 @Lazy 即可拆环', 1793848341683),
	(572, 2, 5, 222, '["循环依赖 · 破坏方式与现状"]', '@Lazy 注入的是代理，首次调用时才解析真实 Bean', 1793848341683),
	(573, 2, 5, 222, '["循环依赖 · 破坏方式与现状"]', '注入关系由「强依赖实例」变为「持有代理、按需解析」', 1793848341683),
	(574, 2, 5, 223, '["Bean配置 · 组件扫描与注册方式"]', '@Component 标类，靠 ComponentScan 扫描注册', 1793848341685),
	(575, 2, 5, 223, '["Bean配置 · 组件扫描与注册方式"]', '@Bean 标在 @Configuration 的方法上，方法返回值即 Bean', 1793848341685),
	(576, 2, 5, 223, '["Bean配置 · 组件扫描与注册方式"]', '@Bean 适合第三方类、条件装配、自定义初始化/销毁', 1793848341685),
	(577, 2, 5, 219, '["AOP · 失效场景与原理"]', '同类自调用走 this，不经过代理，增强不生效', 1793848341688),
	(578, 2, 5, 219, '["AOP · 失效场景与原理"]', '只有从代理对象外部调用时增强才生效', 1793848341688),
	(579, 2, 5, 219, '["AOP · 失效场景与原理"]', '解法：注入自身代理、AopContext.currentProxy()、或拆到另一个 Bean', 1793848341688),
	(580, 2, 5, 226, '["Bean生命周期 · 实例化与初始化顺序"]', '单例 Bean 在容器 refresh 阶段被实例化；原型 Bean 在每次 getBean 时创建。', 1793863407400),
	(581, 2, 5, 226, '["Bean生命周期 · 实例化与初始化顺序"]', 'Bean 生命周期主干：实例化 → 属性填充（依赖注入）→ 初始化（Aware 回调、BeanPostProcessor 前置、@PostConstruct/afterPropertiesSet/init-method、后置）→ 使用 → 销毁。', 1793863407400),
	(582, 2, 5, 227, '["Spring 作用域 · prototype 适用场景"]', 'request：一次 HTTP 请求一个实例；session：一个会话一个实例；prototype：每次 getBean 一个新实例，不绑定请求边界。', 1793863407400),
	(583, 2, 5, 227, '["Spring 作用域 · prototype 适用场景"]', '有会话/请求状态的可变对象优先用 request/session，不能放单例。', 1793863407400),
	(584, 2, 5, 227, '["Spring 作用域 · prototype 适用场景"]', '在单例中注入 prototype 只会注入一次，需用 ObjectProvider/@Lookup 等按需获取。', 1793863407400),
	(585, 2, 5, 228, '["Spring 注入方式 · 构造器注入与 setter 注入选型"]', '强依赖 → 构造器注入：保证非空、不可变、启动即失败；只有一个构造器时可省略 @Autowired。', 1793863407410),
	(586, 2, 5, 228, '["Spring 注入方式 · 构造器注入与 setter 注入选型"]', '可选依赖 → setter 注入 + @Autowired(required=false) 或 @Nullable，缺依赖也能启动。', 1793863407410),
	(587, 2, 5, 228, '["Spring 注入方式 · 构造器注入与 setter 注入选型"]', '@Lazy 用于生成延迟解析的代理，解决循环依赖或延迟初始化，不是「可选依赖」的必需品。', 1793863407410),
	(588, 2, 5, 231, '["Bean后处理器 · BeanPostProcessor"]', 'AOP 增强目标是切点匹配到的方法（连接点），不是整个类。', 1793863407414),
	(589, 2, 5, 231, '["Bean后处理器 · BeanPostProcessor"]', '统一增强靠 BeanPostProcessor 在初始化后自动生成代理（JDK 接口代理 / CGLIB 子类代理）并替换容器中的 Bean。', 1793863407414),
	(590, 2, 5, 231, '["Bean后处理器 · BeanPostProcessor"]', '典型横切场景：日志、事务、权限校验、耗时监控、缓存。', 1793863407414),
	(591, 2, 5, 232, '["Bean生命周期 · 主干流程"]', '销毁顺序：@PreDestroy（postProcessBeforeDestruction）→ DisposableBean.destroy() → 自定义 destroy-method。', 1793863407416),
	(592, 2, 5, 232, '["Bean生命周期 · 主干流程"]', '只有单例 Bean 会被容器管理销毁；prototype 的销毁容器不负责。', 1793863407416),
	(593, 2, 5, 234, '["Spring 注入注解 · @Qualifier 与 @Conditional "]', '多候选消歧：@Primary 定默认、@Qualifier("name") 按名称选、字段名/参数名与 bean 名匹配、@Resource 按名称。', 1793863407416),
	(594, 2, 5, 234, '["Spring 注入注解 · @Qualifier 与 @Conditional "]', '@Conditional 及其派生注解（如 @ConditionalOnProperty）控制 Bean 是否注册；条件不满足则不创建，强依赖注入它会启动失败。', 1793863407416),
	(595, 2, 5, 235, '["AOP 切入点表达式 · execution 通配匹配"]', 'execution(* com.example.service.UserService.*(..))：返回任意、UserService 类中任意方法、参数任意。', 1793863407416),
	(596, 2, 5, 235, '["AOP 切入点表达式 · execution 通配匹配"]', '位置含义：第一个 * 是返回值，第二个 * 是方法名，() 内 .. 表示任意个任意类型参数，`类名+` 才表示含子类。', 1793863407416),
	(597, 2, 5, 230, '["AOP · 核心概念与切点","AOP · 与生命周期的关系","动态代理 · JDK与CGLIB"]', 'AOP 代理创建时机：初始化阶段、BeanPostProcessor 的 postProcessAfterInitialization 里由 AbstractAutoProxyCreator 包一层代理。', 1793863407416),
	(598, 2, 5, 230, '["AOP · 核心概念与切点","AOP · 与生命周期的关系","动态代理 · JDK与CGLIB"]', '单例 Bean 默认容器启动时预实例化（finishBeanFactoryInitialization）就完成代理创建，非懒加载。', 1793863407416),
	(599, 2, 5, 230, '["AOP · 核心概念与切点","AOP · 与生命周期的关系","动态代理 · JDK与CGLIB"]', '事务用 @Around 是因为要控制目标方法执行前后：能捕获异常决定回滚、能决定是否执行目标方法、能改写返回值。', 1793863407416),
	(600, 2, 5, 230, '["AOP · 核心概念与切点","AOP · 与生命周期的关系","动态代理 · JDK与CGLIB"]', 'JDK 代理基于接口（Proxy + InvocationHandler），CGLIB 基于继承生成子类，无法代理 final 类/方法。', 1793863407416),
	(601, 2, 5, 233, '["@Autowired · 注入点与循环依赖"]', '字段注入与 setter 注入都在**属性填充（populateBean）**阶段完成，都在初始化回调（@PostConstruct / afterPropertiesSet）之前。', 1793863413070),
	(602, 2, 5, 233, '["@Autowired · 注入点与循环依赖"]', '区别在执行方式：字段注入用**反射直接写字段**，setter 注入是**调用 setter 方法**。', 1793863413070),
	(603, 2, 5, 233, '["@Autowired · 注入点与循环依赖"]', '实际差异：setter 注入可以在 setter 里做校验、默认值、包装等逻辑；字段注入绕过方法，没有这个插入点。', 1793863413070),
	(604, 2, 5, 233, '["@Autowired · 注入点与循环依赖"]', '字段注入的副作用还包括：依赖被隐藏、单元测试需容器或反射、不能注入 static/final 字段。', 1793863413070),
	(613, 2, 6, 236, '["配置加载 · 多环境与优先级"]', '命名约定：主配置 application.yml，环境配置 application-{profile}.yml，如 application-dev.yml、application-prod.yml。', 1794275251924),
	(614, 2, 6, 236, '["配置加载 · 多环境与优先级"]', '激活属性是 spring.profiles.active（不是 spring.active.profile），可多个 profile 用逗号分隔。', 1794275251924),
	(615, 2, 6, 236, '["配置加载 · 多环境与优先级"]', '激活方式四类：主配置文件里写、命令行参数、环境变量 SPRING_PROFILES_ACTIVE、@ActiveProfiles/setAdditionalProfiles。', 1794275251924),
	(616, 2, 6, 236, '["配置加载 · 多环境与优先级"]', 'profile 专属配置会覆盖 application.yml 中的同名配置项。', 1794275251924),
	(617, 2, 6, 237, '["自动配置 · 条件注解"]', '@ConditionalOnClass：类路径存在指定类才生效，如存在 DispatcherServlet 才装配 WebMvc 自动配置。', 1794275251940),
	(618, 2, 6, 237, '["自动配置 · 条件注解"]', '@ConditionalOnMissingBean：容器中没有该类型 Bean 才注册默认 Bean，这是用户自定义 Bean 能覆盖自动配置的原因。', 1794275251940),
	(619, 2, 6, 237, '["自动配置 · 条件注解"]', '@ConditionalOnProperty：配置项满足条件才生效，如 xxx.enabled=true、matchIfMissing 控制缺省行为。', 1794275251940),
	(620, 2, 6, 237, '["自动配置 · 条件注解"]', '其他常用：@ConditionalOnMissingClass、@ConditionalOnWebApplication、@ConditionalOnBean。', 1794275251940),
	(621, 2, 6, 239, '["自动配置 · 基本原理"]', '@SpringBootApplication = @SpringBootConfiguration + @EnableAutoConfiguration + @ComponentScan。', 1794275251952),
	(622, 2, 6, 239, '["自动配置 · 基本原理"]', '自动配置开关是 @EnableAutoConfiguration，它 @Import 了 AutoConfigurationImportSelector。', 1794275251952),
	(623, 2, 6, 239, '["自动配置 · 基本原理"]', 'AutoConfigurationImportSelector 读取 META-INF/spring.factories 中 EnableAutoConfiguration 对应的配置类全限定名（2.7+ 为 META-INF/spring/AutoConfiguration.imports）。', 1794275251952),
	(624, 2, 6, 239, '["自动配置 · 基本原理"]', '导入的配置类还要经 @Conditional 系列注解筛选，满足条件才注册 Bean。', 1794275251952),
	(625, 2, 6, 249, '["过滤器 · 基本概念与用法"]', 'Filter 属于 Servlet 规范，由 Servlet 容器（Tomcat）管理，运行在 DispatcherServlet 之前，能拦截所有进入容器的请求。', 1794275251956),
	(626, 2, 6, 249, '["过滤器 · 基本概念与用法"]', '实现方式：implements Filter，重写 doFilter，处理完调用 chain.doFilter(req,res) 放行。', 1794275251956),
	(627, 2, 6, 249, '["过滤器 · 基本概念与用法"]', 'Spring Boot 注册三种方式：@Bean FilterRegistrationBean（可配 urlPatterns/order）、直接 @Bean Filter、@WebFilter + @ServletComponentScan。', 1794275251956),
	(628, 2, 6, 249, '["过滤器 · 基本概念与用法"]', 'Filter 与 Spring 的拦截器区别：Filter 在容器层、拿不到 Spring MVC 的 HandlerMethod；拦截器在 Spring MVC 层。', 1794275251956),
	(629, 2, 6, 250, '["参数绑定 · 常用注解"]', '@RequestParam：URL 查询串或表单参数，绑 String / 基本类型及其包装类，靠 ConversionService 转型。', 1794275251956),
	(630, 2, 6, 250, '["参数绑定 · 常用注解"]', '@PathVariable：URL 路径模板变量（/user/{id}），同样绑 String / 基本类型。', 1794275251956),
	(631, 2, 6, 250, '["参数绑定 · 常用注解"]', '@RequestBody：取请求体，用 HttpMessageConverter 反序列化为对象/DTO（JSON 场景靠 Jackson）。', 1794275251956),
	(632, 2, 6, 250, '["参数绑定 · 常用注解"]', '三者取数位置：查询串 / 路径 / 请求体，是区分它们的核心。', 1794275251956),
	(633, 2, 6, 253, '["统一异常处理 · @ControllerAdvice"]', '全局异常处理 = @ControllerAdvice（容器类）+ @ExceptionHandler（处理方法）。', 1794275251956),
	(634, 2, 6, 253, '["统一异常处理 · @ControllerAdvice"]', '@ControllerAdvice 对所有 Controller 生效；返回 JSON 用 @RestControllerAdvice，等价于 @ControllerAdvice + @ResponseBody。', 1794275251956),
	(635, 2, 6, 253, '["统一异常处理 · @ControllerAdvice"]', '@ExceptionHandler 在方法上声明要捕获的异常类型，方法参数接异常对象，返回值即响应体。', 1794275251956),
	(636, 2, 6, 253, '["统一异常处理 · @ControllerAdvice"]', '匹配原则是就近优先：Controller 内部的 @ExceptionHandler 优先于全局的。', 1794275251956),
	(637, 2, 16, 331, '["研发效能 · 度量与价值流动"]', '工作量/工时衡量的是**投入**，价值流动衡量的是**产出到用户的速度**，前者容易掩盖等待与返工。', 1794276231693),
	(638, 2, 16, 331, '["研发效能 · 度量与价值流动"]', '价值流动度量的核心是**流动效率（有效工作时间/总交付周期）**、**周期时间**和**在制品数量**。', 1794276231693),
	(639, 2, 16, 331, '["研发效能 · 度量与价值流动"]', '作用：**识别瓶颈与浪费、压缩等待与在制品、缩短交付周期**，把改进指向价值交付而非忙碌程度。', 1794276231693),
	(640, 2, 16, 332, '["技术债 · 识别与管理"]', '识别技术债的入口：**代码/架构评审、静态扫描与质量度量（重复率、复杂度）、缺陷复盘根因、迭代回顾、临时方案登记**。', 1794276231709),
	(641, 2, 16, 332, '["技术债 · 识别与管理"]', '技术债要**建台账**：记录内容、成因、影响与偿还成本，不能只写进风险登记册。', 1794276231709),
	(642, 2, 16, 332, '["技术债 · 识别与管理"]', '管理靠**排优先级+纳入迭代backlog+约定固定偿还比例（如每迭代20%容量）+指定责任人+看趋势**。', 1794276231709),
	(643, 2, 16, 333, '["数字化生产系统 · 项目管理应用"]', '数字化生产系统的价值主线：**把项目数据在线化、可视化，让PM从“靠人汇报”转为“看数据决策”**。', 1794276231709),
	(644, 2, 16, 333, '["数字化生产系统 · 项目管理应用"]', '计划：**用历史工时、模板与基线做估算**，计划可追溯到WBS与资源。', 1794276231709),
	(645, 2, 16, 333, '["数字化生产系统 · 项目管理应用"]', '跟踪：**任务、工时、进度、缺陷实时可视，偏差自动预警**；风险：**在线登记、跟踪闭环，复用历史应对方案**。', 1794276231709),
	(646, 2, 16, 328, '["AI 提效 · 项目管理场景选型"]', '判断依据一：**任务是否有大量结构化数据、规则明确、可模式化**（数据核对、进度预警、报表汇总适合）。', 1794276231709),
	(647, 2, 16, 328, '["AI 提效 · 项目管理场景选型"]', '判断依据二：**结果可验证、出错成本低、容错度高**（文档初稿、会议纪要适合；关键决策拍板不适合）。', 1794276231709),
	(648, 2, 16, 328, '["AI 提效 · 项目管理场景选型"]', '不适合的典型：**涉及人的情绪、关系、冲突协调与责任决策**，数据少、后果重，AI只能辅助不能主导。', 1794276231709),
	(649, 2, 16, 329, '["知识沉淀 · 经验资产化"]', '沉淀要**条目化**：背景—问题—做法—效果—**适用条件**，而不是流水账文档。', 1794276231709),
	(650, 2, 16, 329, '["知识沉淀 · 经验资产化"]', '资产要**入组织资产库、分类打标签**，与WBS模板、检查单、流程规范关联，保证可检索。', 1794276231709),
	(651, 2, 16, 329, '["知识沉淀 · 经验资产化"]', '关键是**嵌入流程**：把教训转成checklist、评审要素与准入准出条件，在关键节点强制执行。', 1794276231709),
	(652, 2, 16, 329, '["知识沉淀 · 经验资产化"]', '要有**Owner定期维护更新**并跟踪复用效果，否则资产会过期、还是没人看。', 1794276231709),
	(653, 2, 6, 541, '["Starter · 是什么与约定"]', 'starter = 依赖聚合（pom 带入所需 jar）+ 自动配置模块两部分', 1794276897660),
	(654, 2, 6, 541, '["Starter · 是什么与约定"]', '自动配置类靠 @ConditionalOnClass / @ConditionalOnMissingBean + 默认值，实现「引入即用」', 1794276897660),
	(655, 2, 6, 541, '["Starter · 是什么与约定"]', '加载入口是 @SpringBootApplication 内的 @EnableAutoConfiguration', 1794276897660),
	(656, 2, 6, 541, '["Starter · 是什么与约定"]', '2.7 前读 META-INF/spring.factories，2.7/3.x 读 META-INF/spring/...AutoConfiguration.imports', 1794276897660),
	(657, 2, 6, 542, '["Bean 注册 · @Component 与 @Bean"]', '第三方 jar 类注册 Bean：在本项目的 @Configuration 类里用 @Bean 方法 new 出来返回', 1794276897676),
	(658, 2, 6, 542, '["Bean 注册 · @Component 与 @Bean"]', '@Bean 方法名默认就是 bean 名，可用 @Bean("xxx") 改名', 1794276897676),
	(659, 2, 6, 542, '["Bean 注册 · @Component 与 @Bean"]', '注解方式不适用的原因：源码不可改 + 不在本项目组件扫描路径下', 1794276897676),
	(660, 2, 6, 542, '["Bean 注册 · @Component 与 @Bean"]', '承载 @Bean 的类本身必须被 Spring 管理（@Configuration/@Component）', 1794276897676),
	(661, 2, 6, 544, '["过滤器与拦截器 · 区别与选型"]', 'Filter 在 Servlet 容器层，DispatcherServlet 之前，拿原始 request/response，可包装请求，能拦所有请求', 1794276897676),
	(662, 2, 6, 544, '["过滤器与拦截器 · 区别与选型"]', 'Interceptor 在 Spring MVC 层，能拿到 HandlerMethod，便于按注解做权限判断', 1794276897676),
	(663, 2, 6, 544, '["过滤器与拦截器 · 区别与选型"]', '鉴权放哪都行，答题必须给出层次与可获取对象两方面的取舍', 1794276897676),
	(664, 2, 6, 545, '["依赖注入 · @Autowired 与 @Resource"]', '@Autowired：默认 byType，多个候选时按字段名/参数名匹配，用 @Qualifier("beanName") 指定', 1794276897676),
	(665, 2, 6, 545, '["依赖注入 · @Autowired 与 @Resource"]', '@Resource：默认 byName（取字段名），用 name 属性指定，找不到再回退 byType', 1794276897676),
	(666, 2, 6, 545, '["依赖注入 · @Autowired 与 @Resource"]', '@Resource 是 JDK 注解，@Autowired 是 Spring 注解', 1794276897676),
	(667, 2, 6, 546, '["配置文件 · spring.profiles.active 切换"]', 'application.yml 放公共配置，application-{profile}.yml 放各环境差异配置', 1794276897676),
	(668, 2, 6, 546, '["配置文件 · spring.profiles.active 切换"]', '激活哪个 profile 就加载哪个文件，并覆盖主配置同名项', 1794276897676),
	(669, 2, 6, 546, '["配置文件 · spring.profiles.active 切换"]', '配置方式：spring.profiles.active: dev', 1794276897676),
	(670, 2, 6, 546, '["配置文件 · spring.profiles.active 切换"]', '命令行方式：--spring.profiles.active=prod 或 -Dspring.profiles.active=prod', 1794276897676),
	(671, 2, 6, 550, '["Starter · 自定义步骤"]', '触发入口：@SpringBootApplication 内的 @EnableAutoConfiguration', 1794276897676),
	(672, 2, 6, 550, '["Starter · 自定义步骤"]', 'Spring Boot 2.x：META-INF/spring.factories，key 为 org.springframework.boot.autoconfigure.EnableAutoConfiguration', 1794276897676),
	(673, 2, 6, 550, '["Starter · 自定义步骤"]', 'Spring Boot 2.7 起 / 3.x：META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports，一行一个类，配合 @AutoConfiguration', 1794276897676),
	(674, 2, 6, 550, '["Starter · 自定义步骤"]', '文件没写、写错位置、类没登记进去，配置类就不生效', 1794276897676),
	(675, 2, 6, 548, '["配置绑定 · @ConfigurationProperties"]', '让 @ConfigurationProperties 类生效：加 @Component/@Configuration，或 @EnableConfigurationProperties(Xxx.class)，或 @ConfigurationPropertiesScan', 1794276897676),
	(676, 2, 6, 548, '["配置绑定 · @ConfigurationProperties"]', '只加 @ConfigurationProperties 而不注册成 Bean，配置不会绑定', 1794276897676),
	(677, 2, 6, 548, '["配置绑定 · @ConfigurationProperties"]', 'prefix 必须全小写，多单词用短横线分隔（kebab-case）', 1794276897676),
	(678, 2, 6, 549, '["参数绑定 · 常用注解","统一异常处理 · @ControllerAdvice","自动配置 · 条件注解"]', '@Value 单值注入：@Value("${order.timeout}")，默认值写 ${order.timeout:30}', 1794276897692),
	(679, 2, 6, 549, '["参数绑定 · 常用注解","统一异常处理 · @ControllerAdvice","自动配置 · 条件注解"]', '@ConfigurationProperties：写在类上 (prefix="order")，字段给 getter/setter，再用 @Component 或 @EnableConfigurationProperties 注册', 1794276897692),
	(680, 2, 6, 549, '["参数绑定 · 常用注解","统一异常处理 · @ControllerAdvice","自动配置 · 条件注解"]', '两个主要区别：批量/嵌套绑定 vs 单值；支持松散绑定与 JSR-303 校验 vs 不支持', 1794276897692),
	(681, 2, 6, 549, '["参数绑定 · 常用注解","统一异常处理 · @ControllerAdvice","自动配置 · 条件注解"]', '配置缺失：@Value 无默认值会启动报错；@ConfigurationProperties 字段为 null/默认值，不报错', 1794276897692),
	(682, 2, 6, 555, '["Starter · 开箱即用的设计"]', 'spring-boot-starter-web = spring-boot-starter（核心+日志）+ spring-web/spring-webmvc + 内嵌 Tomcat + Jackson（spring-boot-starter-json）。', 1794278403065),
	(683, 2, 6, 555, '["Starter · 开箱即用的设计"]', 'starter 的核心价值：一站式依赖坐标 + 统一版本管理，不用自己逐个写 groupId/artifactId/version。', 1794278403065),
	(684, 2, 6, 555, '["Starter · 开箱即用的设计"]', 'starter 只是「引依赖」，真正的默认装配由自动配置类完成，两者配合才开箱即用。', 1794278403065),
	(685, 2, 6, 557, '["自动配置 · 加载与顺序"]', 'Spring Boot 2.7+ 自动配置入口：META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports。', 1794278403068),
	(686, 2, 6, 557, '["自动配置 · 加载与顺序"]', '文件内容是自动配置类的全限定名，一行一个。', 1794278403068),
	(687, 2, 6, 557, '["自动配置 · 加载与顺序"]', '老版本（2.7 之前）用 META-INF/spring.factories，key 为 EnableAutoConfiguration。', 1794278403068),
	(688, 2, 6, 559, '["@Value 读取配置项"]', '@Value 注入配置必须写成 @Value("${app.name}")，引号不能省。', 1794278403071),
	(689, 2, 6, 559, '["@Value 读取配置项"]', '${...} 是属性占位符，运行时从 Environment 解析 key 对应的值并替换。', 1794278403071),
	(690, 2, 6, 559, '["@Value 读取配置项"]', '配置文件、系统属性、环境变量都是 Environment 的属性来源。', 1794278403071),
	(691, 2, 6, 551, '["@Autowired 与 @Resource 注入区别"]', '@Autowired：Spring 提供，默认 byType，配合 @Qualifier 按名称，required=false 可允许为空。', 1794278403074),
	(692, 2, 6, 551, '["@Autowired 与 @Resource 注入区别"]', '@Resource：JSR-250 规范（JDK）提供，默认 byName（按字段名），找不到再按类型。', 1794278403074),
	(693, 2, 6, 551, '["@Autowired 与 @Resource 注入区别"]', '@Resource 显式指定 name 就不是默认匹配了，属于手动指定。', 1794278403074),
	(694, 2, 6, 563, '["@Bean 注解注册 Bean"]', '第三方 jar 里是编译后的 class，无法给它的类加 @Component。', 1794292870195),
	(695, 2, 6, 563, '["@Bean 注解注册 Bean"]', '第三方包路径一般不在你的组件扫描范围内，加了注解也扫不到。', 1794292870195),
	(696, 2, 6, 563, '["@Bean 注解注册 Bean"]', '@Configuration + @Bean 能在自己代码里控制构造参数与条件装配（@ConditionalOnMissingBean）。', 1794292870195),
	(697, 2, 6, 566, '["过滤器与拦截器的选择使用"]', 'Interceptor 能拿到 HandlerMethod，可结合自定义注解做接口级权限判断；Filter 只能按 URL 判断。', 1794292870206),
	(698, 2, 6, 566, '["过滤器与拦截器的选择使用"]', 'Interceptor 用 addPathPatterns/excludePathPatterns 精确控制范围；Filter 用 urlPatterns/FilterRegistrationBean 控制。', 1794292870206),
	(699, 2, 6, 566, '["过滤器与拦截器的选择使用"]', '最外层通用处理（编码、CORS、XSS）用 Filter；业务鉴权、登录校验优先用 Interceptor。', 1794292870206),
	(700, 2, 6, 566, '["过滤器与拦截器的选择使用"]', '过滤器先于 DispatcherServlet，拦截器在 DispatcherServlet 之后、Controller 之前。', 1794292870206),
	(701, 2, 6, 567, '["profile 多环境配置文件"]', 'application-{profile}.yml 由 Profile 机制自动加载，无需 import。', 1794292870214),
	(702, 2, 6, 567, '["profile 多环境配置文件"]', '激活哪个 profile 由 spring.profiles.active 决定。', 1794292870214),
	(703, 2, 6, 567, '["profile 多环境配置文件"]', '运行时切换：java -jar app.jar --spring.profiles.active=prod，或环境变量 SPRING_PROFILES_ACTIVE=prod。', 1794292870214),
	(704, 2, 6, 567, '["profile 多环境配置文件"]', 'profile 专属配置与 application.yml 合并，同名 key 以 profile 专属的为准。', 1794292870214),
	(705, 2, 6, 568, '["SpringBoot 配置加载 · spring.factories 机制"]', 'Spring Boot 2.x 的 key：org.springframework.boot.autoconfigure.EnableAutoConfiguration。', 1794292870222),
	(706, 2, 6, 568, '["SpringBoot 配置加载 · spring.factories 机制"]', '链路：@EnableAutoConfiguration → @Import(AutoConfigurationImportSelector) → SpringFactoriesLoader 读 spring.factories → 条件过滤 → 注册配置类。', 1794292870222),
	(707, 2, 6, 568, '["SpringBoot 配置加载 · spring.factories 机制"]', '不是包扫描，是读 META-INF/spring.factories 文件。', 1794292870222),
	(708, 2, 6, 568, '["SpringBoot 配置加载 · spring.factories 机制"]', '配置类还要过 @ConditionalOnClass/@ConditionalOnMissingBean 等条件才会生效。', 1794292870222),
	(709, 2, 6, 568, '["SpringBoot 配置加载 · spring.factories 机制"]', 'Spring Boot 2.7+ 起新增 AutoConfiguration.imports 文件，3.0 移除 spring.factories 方式。', 1794292870222),
	(710, 2, 6, 569, '["过滤器 · 基本概念与用法"]', 'Filter 属于 Java Servlet 规范，由 Servlet 容器（Tomcat）调用，先于 DispatcherServlet。', 1794292870232),
	(711, 2, 6, 569, '["过滤器 · 基本概念与用法"]', '核心方法：doFilter(ServletRequest, ServletResponse, FilterChain)，末尾 chain.doFilter 放行。', 1794292870232),
	(712, 2, 6, 569, '["过滤器 · 基本概念与用法"]', '两种注册：@Component 或 @WebFilter + @ServletComponentScan；FilterRegistrationBean（可设 order/urlPatterns）。', 1794292870232),
	(713, 2, 6, 569, '["过滤器 · 基本概念与用法"]', '继承 OncePerRequestFilter 可保证一次请求只过滤一次，重写 doFilterInternal。', 1794292870232),
	(726, 2, 6, 694, '["过滤器与拦截器 · 典型应用"]', '鉴权失败要中途直接返回、不进 Controller：用 **Filter**，靠 `doFilter` 中不调用 `chain.doFilter()` 拦死。', 1794294875539),
	(727, 2, 6, 694, '["过滤器与拦截器 · 典型应用"]', '需要按 Handler 方法/注解做精细控制、或要统计包含异常在内的完整耗时：用 **Interceptor**，`preHandle` 记开始、`afterCompletion` 记结束。', 1794294875539),
	(728, 2, 6, 694, '["过滤器与拦截器 · 典型应用"]', '`afterCompletion` 在请求完全结束后执行且异常也会进入，是计算耗时的可靠结束点。', 1794294875539),
	(729, 2, 6, 696, '["请求处理 · 核心流程"]', '接收并分发 HTTP 请求的核心组件是 DispatcherServlet，它是 Spring MVC 的前端控制器（本质是一个 Servlet）。', 1794297232171),
	(730, 2, 6, 696, '["请求处理 · 核心流程"]', '分发依据是 HandlerMapping：按请求 URL 等条件映射到对应的 Handler（Controller 方法）。', 1794297232171),
	(731, 2, 6, 696, '["请求处理 · 核心流程"]', '匹配到 Handler 后由 HandlerAdapter 负责调用，DispatcherServlet 只做统一调度。', 1794297232171),
	(732, 2, 6, 697, '["统一响应与跨域 · 常用配置"]', '跨域预检请求是 OPTIONS，被拦截器或 Spring Security 拦掉是「配了跨域还报跨域」的头号原因。', 1794297353003),
	(733, 2, 6, 697, '["统一响应与跨域 · 常用配置"]', '统一跨域配置放在**过滤器**（CorsFilter / CorsConfigurationSource）而不是拦截器，因为过滤器在 DispatcherServlet 与拦截器之前执行。', 1794297353003),
	(734, 2, 6, 697, '["统一响应与跨域 · 常用配置"]', '拦截器在 Handler 映射之后才执行，OPTIONS 预检常常到不了拦截器；在拦截器里加 CORS 头对预检无效。', 1794297353003),
	(735, 2, 6, 697, '["统一响应与跨域 · 常用配置"]', 'WebMvcConfigurer 不是自动配置类，它只是给 MVC 做定制的扩展点。', 1794297353003),
	(736, 2, 6, 697, '["统一响应与跨域 · 常用配置"]', 'XML 或跨域配置写在 Controller 上时，只对单个接口生效，且同样挡不住预检被提前拦截的问题。', 1794297353003),
	(743, 2, 6, 703, '["过滤器 · Filter 概念定位"]', 'Filter 在 Servlet 容器层生效，链式执行在 DispatcherServlet 之前，Controller 在最后。', 1794297683156),
	(744, 2, 6, 703, '["过滤器 · Filter 概念定位"]', 'Filter 的典型用途：编码设置、权限认证、日志和耗时、CORS、XSS 过滤、包装 request 和 response。', 1794297683156),
	(745, 2, 6, 703, '["过滤器 · Filter 概念定位"]', 'Filter 作用于请求进入 Servlet 之前和响应返回之后，一次请求会进出双向经过 Filter。', 1794297683156),
	(746, 2, 6, 703, '["过滤器 · Filter 概念定位"]', '定位记忆：Filter（容器层）先于 DispatcherServlet，再由 Interceptor（Spring MVC 层）进入 Handler、Controller。', 1794297683156),
	(753, 2, 6, 707, '["参数绑定 · @RequestParam 取 URL 参数"]', '参数名与形参名相同：可裸写 @RequestParam，也可写 @RequestParam("id")，裸写依赖形参名，需编译时保留参数名。', 1794297797502),
	(754, 2, 6, 707, '["参数绑定 · @RequestParam 取 URL 参数"]', '参数名与形参名不同：用 @RequestParam("userId") String id 把前端参数名映射到任意形参名。', 1794297797502),
	(755, 2, 6, 707, '["参数绑定 · @RequestParam 取 URL 参数"]', 'name 与 value 互为别名，都表示请求参数名，不写时默认取形参名。', 1794297797502),
	(756, 2, 6, 707, '["参数绑定 · @RequestParam 取 URL 参数"]', 'required 默认 true，缺失抛 MissingServletRequestParameterException；设 false 时缺失注入 null，配合 defaultValue 可给默认值。', 1794297797502),
	(757, 2, 16, 577, '["进度管理 · 活动与关键路径"]', '关键路径是网络图中累计工期最长的路径，它决定项目总工期；本例 A-C-E-F=9 天 > A-B-D-F=8 天。', 1794298157513),
	(758, 2, 16, 577, '["进度管理 · 活动与关键路径"]', '关键路径上的活动没有总时差，任何延误都 1:1 传导到总工期；C 延误 2 天，总工期由 9 天变 11 天。', 1794298157513),
	(759, 2, 16, 577, '["进度管理 · 活动与关键路径"]', '非关键路径上的活动（B、D）有浮动时间，小幅延误在时差内不影响总工期。', 1794298157513),
	(760, 2, 16, 577, '["进度管理 · 活动与关键路径"]', '要保住原工期，必须在关键路径上赶工同等天数（压缩 C 本身或 E、F），否则只能接受延期并更新进度基准。', 1794298157513),
	(761, 2, 6, 708, '["参数绑定 · @PathVariable 取路径变量"]', '路径变量绑定用 **@PathVariable**，配合 URL 模板占位符 `/users/{id}` 使用。', 1794298253400),
	(762, 2, 6, 708, '["参数绑定 · @PathVariable 取路径变量"]', '注解作用：把 **URL 模板占位符的值绑定到方法参数**，并按参数类型自动转换。', 1794298253400),
	(763, 2, 6, 708, '["参数绑定 · @PathVariable 取路径变量"]', '`@PathVariable("id") Long id` 中名字要与 `{id}` 一致，同名时可省略括号内名称。', 1794298253400),
	(764, 2, 6, 708, '["参数绑定 · @PathVariable 取路径变量"]', '注意拼写是 PathVariable（Path + Variable），不是 PathVarible。', 1794298253400),
	(781, 2, 6, 709, '["Spring Boot Starter · spring-boot-starte"]', 'spring-boot-starter-data-redis 默认使用 **Lettuce** 客户端，并支持切换到 Jedis，同时自动配置 **RedisConnectionFactory**、**RedisTemplate** 和 **StringRedisTemplate**。', 1794298410701),
	(782, 2, 6, 709, '["Spring Boot Starter · spring-boot-starte"]', 'starter 是“**依赖聚合 + 自动配置**”的组合包，引入 starter 就等于引入一组经过版本对齐的依赖和对应自动配置。', 1794298410701),
	(783, 2, 6, 709, '["Spring Boot Starter · spring-boot-starte"]', 'spring-boot-starter-web 带来 **Spring MVC + 内嵌 Tomcat + Jackson**，并自动配置 DispatcherServlet、WebMvcAutoConfiguration 和消息转换器。', 1794298410701),
	(784, 2, 6, 709, '["Spring Boot Starter · spring-boot-starte"]', '自动配置类在 Spring Boot 2.x 中注册于 `META-INF/spring.factories`，在 2.7+ 中推荐注册于 `...AutoConfiguration.imports`。', 1794298410701),
	(801, 2, 6, 726, '["自动配置 · AutoConfiguration.imports 文件"]', 'Spring Boot 2.x 自动配置的注册文件是 **`META-INF/spring.factories`**，位于 classpath 的 META-INF 目录下。', 1794298522098),
	(802, 2, 6, 726, '["自动配置 · AutoConfiguration.imports 文件"]', 'spring.factories 的写法是键值对：key 为 `org.springframework.boot.autoconfigure.EnableAutoConfiguration`，值为自动配置类的全限定名列表。', 1794298522098),
	(803, 2, 6, 726, '["自动配置 · AutoConfiguration.imports 文件"]', 'Spring Boot 2.7+/3.x 改用 **`META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports`**，文件内直接一行一个配置类全限定名。', 1794298522098),
	(804, 2, 6, 726, '["自动配置 · AutoConfiguration.imports 文件"]', '两个易混点：`spring.factories` 在 `META-INF/` 下、是键值格式；`.imports` 在 `META-INF/spring/` 下、是纯列表格式。', 1794298522098),
	(821, 2, 6, 736, '["SpringBoot · 命令行指定 profile 加载配置"]', '正确的属性名是 spring.profiles.active（profiles 为复数），命令行写法为 `java -jar app.jar --spring.profiles.active=dev`。', 1794298764384),
	(822, 2, 6, 736, '["SpringBoot · 命令行指定 profile 加载配置"]', '第二种常用写法是 JVM 系统属性：`java -Dspring.profiles.active=dev -jar app.jar`，注意 -D 要放在 -jar 之前。', 1794298764384),
	(823, 2, 6, 736, '["SpringBoot · 命令行指定 profile 加载配置"]', '命令行参数会被封装为 commandLineArgs 属性源，优先级高于 application.yml 与 Java 系统属性，所以同名的 yml 配置会被覆盖。', 1794298764384),
	(824, 2, 6, 736, '["SpringBoot · 命令行指定 profile 加载配置"]', 'SpringApplication 在 prepareEnvironment 阶段就解析 spring.profiles.active，据此加载 application-{profile}.yml。', 1794298764384),
	(843, 2, 6, 737, '["SpringBoot · 自动配置类扫描全限定名并注册 Bean"]', '入口链路：@SpringBootApplication → @EnableAutoConfiguration → @Import(AutoConfigurationImportSelector.class)。', 1794299027253),
	(844, 2, 6, 737, '["SpringBoot · 自动配置类扫描全限定名并注册 Bean"]', '加载时机：容器启动解析配置类时（ConfigurationClassPostProcessor 调 ImportSelector），由 SpringFactoriesLoader 读取 META-INF/spring.factories。', 1794299027253),
	(845, 2, 6, 737, '["SpringBoot · 自动配置类扫描全限定名并注册 Bean"]', '自动配置类注册的是**配置类 BeanDefinition**，它里面 @Bean 方法才注册出实际 Bean。', 1794299027253),
	(846, 2, 6, 737, '["SpringBoot · 自动配置类扫描全限定名并注册 Bean"]', 'Spring Boot 2.7+ 改用 AutoConfiguration.imports 文件（spring.factories 兼容保留）。', 1794299027253),
	(865, 2, 6, 751, '["过滤器与拦截器 · 静态资源是否经过过滤器"]', 'Filter 在 DispatcherServlet 之前执行，按 URL 拦截，静态资源请求同样会经过 Filter。', 1794299165133),
	(866, 2, 6, 751, '["过滤器与拦截器 · 静态资源是否经过过滤器"]', 'Filter 内判断 request.getRequestURI() 前缀，命中静态资源就 chain.doFilter 直接放行。', 1794299165133),
	(867, 2, 6, 751, '["过滤器与拦截器 · 静态资源是否经过过滤器"]', 'FilterRegistrationBean 通过 addUrlPatterns 收窄拦截范围（只拦接口），间接避开静态资源。', 1794299165133),
	(868, 2, 6, 751, '["过滤器与拦截器 · 静态资源是否经过过滤器"]', '继承 OncePerRequestFilter 并重写 shouldNotFilter，可按路径精确跳过某些请求。', 1794299165133),
	(875, 2, 6, 762, '["AOP · 基本概念与场景"]', 'AOP 处理的是横切关注点：日志、耗时统计、权限校验、事务、缓存、限流等与业务语义无关的统一逻辑。', 1794299608427),
	(876, 2, 6, 762, '["AOP · 基本概念与场景"]', '切面的定位边界：只管「非业务」的重复统一逻辑，业务规则必须留在业务层。', 1794299608427),
	(877, 2, 6, 762, '["AOP · 基本概念与场景"]', '业务逻辑进切面的代价：调用链不可见、难调试难单测、事务与异常语义被隐藏。', 1794299608427),
	(878, 2, 6, 762, '["AOP · 基本概念与场景"]', '判断标准一句话：这段逻辑换一个业务方法还成立吗？成立→可切面；不成立→是业务，留在 Service。', 1794299608427),
	(879, 2, 6, 763, '["拦截器 · 基本概念与用法"]', 'preHandle 返回 boolean：返回 false 中断请求，后续拦截器与 Controller 都不执行（已通过的拦截器会触发 afterCompletion）。', 1794299713948),
	(880, 2, 6, 763, '["拦截器 · 基本概念与用法"]', 'postHandle、afterCompletion 返回 void，无法中止请求。', 1794299713948),
	(881, 2, 6, 763, '["拦截器 · 基本概念与用法"]', '执行顺序：preHandle（Controller 前）→ Controller → postHandle（Controller 后、视图渲染前）→ 视图渲染 → afterCompletion（渲染后）。', 1794299713948),
	(882, 2, 6, 763, '["拦截器 · 基本概念与用法"]', '典型用途：preHandle 做登录/权限校验，postHandle 加工 ModelAndView，afterCompletion 做资源清理与耗时统计。', 1794299713948),
	(883, 2, 50, 766, '["B+树 · 结构特征"]', '非叶子节点只存索引键 → 单页容纳更多键、扇出更大 → 树高更低 → 磁盘 I/O 更少。', 1794300694209),
	(884, 2, 50, 766, '["B+树 · 结构特征"]', '完整数据集中在叶子节点且叶子在同一层，查询路径长度稳定。', 1794300694209),
	(885, 2, 50, 766, '["B+树 · 结构特征"]', '叶子节点双向链表用于范围查询和有序遍历：定位起点后沿链表顺序读取。', 1794300694209),
	(886, 2, 50, 766, '["B+树 · 结构特征"]', '范围查询不必每行都从根节点下探，沿叶子链表扫描即可。', 1794300694209),
	(887, 2, 6, 764, '["依赖注入 · @Autowired 与 @Resource 区别"]', '按类型注入时，如果出现多个同类型候选，Spring 会自动回退为按名称匹配，即用字段名、参数名去匹配 bean 名称。', 1794301901516),
	(888, 2, 6, 764, '["依赖注入 · @Autowired 与 @Resource 区别"]', '字段名与某个 bean 名称一致时，注入成功；都不一致时才抛 NoUniqueBeanDefinitionException。', 1794301901516),
	(889, 2, 6, 764, '["依赖注入 · @Autowired 与 @Resource 区别"]', '显式消歧用 @Primary（优先级）和 @Qualifier("beanName")（指定名称）。', 1794301901516),
	(890, 2, 6, 764, '["依赖注入 · @Autowired 与 @Resource 区别"]', '常见易错点：把「按类型注入失败」直接等同于「改字段名也没用」，忽略了名称回退。', 1794301901516),
	(891, 2, 6, 764, '["依赖注入 · @Autowired 与 @Resource 区别"]', 'Bean 默认名称是类名首字母小写：ServiceA → serviceA。', 1794301901516),
	(892, 2, 6, 765, '["依赖注入 · @Autowired 与 @Resource 区别"]', '@Autowired：默认按类型（ByType）注入，找不到该类型的 Bean 直接抛 NoSuchBeanDefinitionException。', 1794302183946),
	(893, 2, 6, 765, '["依赖注入 · @Autowired 与 @Resource 区别"]', '@Autowired 的“按名称”只出现在同类型多候选时，用字段名/参数名做消歧，并非全局退化机制。', 1794302183946),
	(894, 2, 6, 765, '["依赖注入 · @Autowired 与 @Resource 区别"]', '@Resource：默认按名称（ByName）注入，未指定 name 时取字段名，名称匹配不上再退化为按类型。', 1794302183946),
	(895, 2, 6, 765, '["依赖注入 · @Autowired 与 @Resource 区别"]', '需要明确指定注入哪个 Bean 时，@Autowired 配 @Qualifier，@Resource 直接用 name 属性。', 1794302183946),
	(896, 2, 6, 768, '["自动配置 · 排除与调试"]', 'yml 方式：spring.autoconfigure.exclude=com.xxx.XxxAutoConfiguration，多个用逗号分隔，写全限定类名', 1794302338003),
	(897, 2, 6, 768, '["自动配置 · 排除与调试"]', '注解方式：@SpringBootApplication(exclude = XxxAutoConfiguration.class)，或 @EnableAutoConfiguration(exclude = {...})', 1794302338003),
	(898, 2, 6, 768, '["自动配置 · 排除与调试"]', '排除的是「自动配置类」本身，不是普通 @Configuration，类名必须是自动配置的候选类', 1794302338003),
	(899, 2, 6, 768, '["自动配置 · 排除与调试"]', '配置项是 spring.autoconfigure.exclude，不是 spring.exclude，这是最易错的点', 1794302338003),
	(900, 2, 6, 769, '["SpringBoot · OncePerRequestFilter 保证单次执行"]', 'forward 是服务器内部转发，容器会把目标路径按 FORWARD 类型再走一遍过滤器链，request 对象是同一个。', 1794302648596),
	(901, 2, 6, 769, '["SpringBoot · OncePerRequestFilter 保证单次执行"]', 'OncePerRequestFilter 在 request 的 attribute 上打标记，已标记则直接放行不做业务，从而保证一次请求只执行一次。', 1794302648596),
	(902, 2, 6, 769, '["SpringBoot · OncePerRequestFilter 保证单次执行"]', '改造方式：继承 OncePerRequestFilter，把过滤逻辑写进 doFilterInternal，不再自己实现 doFilter。', 1794302648596),
	(903, 2, 6, 769, '["SpringBoot · OncePerRequestFilter 保证单次执行"]', '核心区别：request 是同一个对象，attribute 才能跨 forward 传递；若用 ThreadLocal 之类也需注意清理。', 1794302648596),
	(904, 2, 6, 770, '["Spring Boot Starter · spring-boot-starte"]', 'starter 的本质 = 依赖聚合 + 自动配置，本身通常不含业务代码。', 1794302820601),
	(905, 2, 6, 770, '["Spring Boot Starter · spring-boot-starte"]', '官方 starter 命名为 spring-boot-starter-xxx，第三方约定命名 xxx-spring-boot-starter。', 1794302820601),
	(906, 2, 6, 770, '["Spring Boot Starter · spring-boot-starte"]', 'spring-boot-starter-web = Spring MVC + 内嵌 Tomcat 等 Web 运行所需依赖。', 1794302820601),
	(907, 2, 6, 770, '["Spring Boot Starter · spring-boot-starte"]', 'spring-boot-starter-data-redis = Spring Data Redis，含 RedisTemplate、连接工厂及自动配置；spring-boot-starter-validation = Bean Validation 实现（Hibernate Validator）。', 1794302820601),
	(908, 2, 6, 771, '["SpringBoot · 命令行指定 profile 加载配置"]', '-D 是 JVM 系统属性写法，如 `java -Dspring.profiles.active=dev -jar app.jar`。', 1794302913886),
	(909, 2, 6, 771, '["SpringBoot · 命令行指定 profile 加载配置"]', '-- 是 Spring Boot 应用参数写法，如 `java -jar app.jar --spring.profiles.active=dev`。', 1794302913886),
	(910, 2, 6, 771, '["SpringBoot · 命令行指定 profile 加载配置"]', '-D 由 JVM 系统属性进入 Environment；`--` 由 SpringApplication 解析为命令行参数 PropertySource。', 1794302913886),
	(911, 2, 6, 771, '["SpringBoot · 命令行指定 profile 加载配置"]', '-D 参数必须带 `=值`，只写 `-Dspring.profiles.active` 不构成完整示例。', 1794302913886),
	(912, 2, 50, 773, '["B+树 · 树高与磁盘IO"]', '树高估算 = 页大小 16KB ÷ 单条索引项大小（主键宽 + 页号约 6 字节），得到单页扇出，再按层数连乘。', 1794364116323),
	(913, 2, 50, 773, '["B+树 · 树高与磁盘IO"]', '非叶子页只存「键 + 子页号」，扇出可达千级；叶子页存整行，每页行数由行宽决定，两者要分开估。', 1794364116323),
	(914, 2, 50, 773, '["B+树 · 树高与磁盘IO"]', '根节点常驻 Buffer Pool，走三层通常只需约 2 次磁盘 IO（第二层 1 次 + 叶子层 1 次）。', 1794364116323),
	(915, 2, 50, 773, '["B+树 · 树高与磁盘IO"]', '树高低是 B+ 树 IO 少的根本原因：每下降一层最多一次磁盘 IO。', 1794364116323),
	(916, 2, 50, 774, '["索引 · 页与数据组织"]', 'InnoDB 磁盘 IO 的最小单位是**页**，默认 **16KB**，一次读整页进 Buffer Pool。', 1794364419334),
	(917, 2, 50, 774, '["索引 · 页与数据组织"]', '按页读的两条理由：磁盘顺序读远快于随机读；局部性原理——读到一条记录，相邻记录大概率随后被用。', 1794364419334),
	(918, 2, 50, 774, '["索引 · 页与数据组织"]', '页大小决定单页能装多少索引项 → 决定 B+ 树**扇出**，扇出越大**树高越低**，查一条记录需要的 IO 次数越少。', 1794364419334),
	(919, 2, 50, 774, '["索引 · 页与数据组织"]', '页越大单次 IO 数据量越大、Buffer Pool 能缓存的页数越少，所以不是越大越好。', 1794364419334),
	(920, 2, 50, 775, '["索引 · 主键选择与自增"]', 'InnoDB 聚簇索引按主键顺序组织数据，主键有序 = 写入有序，自增主键只在尾部追加。', 1794365581661),
	(921, 2, 50, 775, '["索引 · 主键选择与自增"]', 'UUID 随机无序，插入落在页中间会触发页分裂并产生碎片，这是不用 UUID 做主键的核心理由。', 1794365581661),
	(922, 2, 50, 775, '["索引 · 主键选择与自增"]', '二级索引叶子节点存的是主键值，主键越短，二级索引记录越小、整棵索引树越省空间。', 1794365581661),
	(923, 2, 50, 775, '["索引 · 主键选择与自增"]', '主键要同时满足：自增（有序）、类型短（int/bigint），两者共同决定聚簇索引与二级索引的开销。', 1794365581661),
	(924, 2, 50, 776, '["索引 · 索引失效常见场景"]', '联合索引 idx(a,b,c) 能被使用的前提是从最左列 a 开始、且中间不跳过列。', 1794365786249),
	(925, 2, 50, 776, '["索引 · 索引失效常见场景"]', 'where 条件的书写顺序不影响索引使用，优化器会对齐等值条件与索引列顺序。', 1794365786249),
	(926, 2, 50, 776, '["索引 · 索引失效常见场景"]', '等值条件下，a、b 都出现即满足最左前缀，可同时用上 a 和 b 两列。', 1794365786249),
	(927, 2, 50, 776, '["索引 · 索引失效常见场景"]', '缺最左列 a 时（如只有 b、c），该索引既不能做检索，也不能做排序/覆盖。', 1794365786249),
	(928, 2, 50, 777, '["聚簇索引 · 概念与数据存放"]', 'InnoDB 有主键时，聚簇索引就建在主键列上，主键即聚簇索引键。', 1794365865311),
	(929, 2, 50, 777, '["聚簇索引 · 概念与数据存放"]', '聚簇索引的叶子节点存整行数据，索引即数据，按主键查无需回表。', 1794365865311),
	(930, 2, 50, 777, '["聚簇索引 · 概念与数据存放"]', '这张表的聚簇索引叶子节点里就是 id、name、age 组成的完整行记录。', 1794365865311),
	(931, 2, 50, 778, '["二级索引 · 结构与存储内容"]', 'InnoDB 二级索引叶子节点存的是：索引列值 + 主键值，不是行数据也不是行指针。', 1794365945858),
	(932, 2, 50, 778, '["二级索引 · 结构与存储内容"]', '整行数据只存一份，在聚簇索引（主键索引）的叶子节点上。', 1794365945858),
	(933, 2, 50, 778, '["二级索引 · 结构与存储内容"]', '二级索引不存整行的原因：避免同一行在多个索引里重复存储，省空间、少维护副本、写性能更好。', 1794365945858),
	(934, 2, 50, 778, '["二级索引 · 结构与存储内容"]', '通过二级索引查非索引列要拿主键值回聚簇索引再查一次，这就是回表。', 1794365945858),
	(935, 2, 50, 779, '["主键 · 与二级索引的关系"]', 'InnoDB 二级索引叶子节点存的是**索引列值 + 主键值**，不是整行数据。', 1794366329041),
	(936, 2, 50, 779, '["主键 · 与二级索引的关系"]', '主键越长，**每一个二级索引**都要跟着变长（每个二级索引都要存一份主键）。', 1794366329041),
	(937, 2, 50, 779, '["主键 · 与二级索引的关系"]', 'INT 占 4 字节，VARCHAR(50) 在 utf8mb4 下最多 200 字节，二级索引体积会成倍膨胀、树变高。', 1794366329041),
	(938, 2, 50, 779, '["主键 · 与二级索引的关系"]', '所以主键优先用短且有序的自增整型，别用长字符串。', 1794366329041),
	(939, 2, 50, 780, '["索引组织表 · 与堆表的区别"]', 'InnoDB 聚簇索引的叶子节点直接存整行数据，主键索引即数据本身，找到索引就找到行。', 1794366511272),
	(940, 2, 50, 780, '["索引组织表 · 与堆表的区别"]', 'MyISAM 是非聚簇（堆表）：索引叶子存行地址（物理偏移），查到后要回数据文件按地址再取一次行。', 1794366511272),
	(941, 2, 50, 780, '["索引组织表 · 与堆表的区别"]', '按主键聚簇组织数据的好处：范围查询和按主键排序可以顺序扫描，减少随机 IO；堆表按插入顺序存放，范围查询要在不同磁盘位置跳读。', 1794366511272),
	(942, 2, 50, 780, '["索引组织表 · 与堆表的区别"]', '堆表没有索引时只能按插入顺序全表扫描；聚簇索引表如果没有显式主键，InnoDB 会选唯一非空索引或隐式 rowid 来聚簇。', 1794366511272),
	(943, 2, 50, 781, '["联合索引 · 最左前缀规则"]', '联合索引(a,b,c)的列使用必须从最左列开始**连续**匹配，中间断一列，后面的列全部失效——a=1 AND c=3 只能用 a。', 1794366779973),
	(944, 2, 50, 781, '["联合索引 · 最左前缀规则"]', '等值 + 范围混合时：范围列本身可以用索引，但**范围列之后的列不再参与索引定位**（a=1 AND b>2 AND c=3 只用到 a、b）。', 1794366779973),
	(945, 2, 50, 781, '["联合索引 · 最左前缀规则"]', '不含最左列的条件（如 b=2 AND c=3）走不了该联合索引，只能全表扫描或走别的索引。', 1794366779973),
	(946, 2, 50, 781, '["联合索引 · 最左前缀规则"]', 'WHERE 里条件的书写顺序不影响，优化器会自动按索引列顺序匹配；起决定作用的是**存在哪些列条件**。', 1794366779973),
	(947, 2, 50, 782, '["联合索引 · 列顺序设计"]', '联合索引遵循最左前缀：等值列放前面、范围列放后面，才能让等值列定位、范围列在区间内扫描，两列都用上。', 1794366863874),
	(948, 2, 50, 782, '["联合索引 · 列顺序设计"]', '如果范围列在前（如 (b, a) 中的 b > ?），范围列之后的列无法参与索引定位与过滤，只能在回表后过滤。', 1794366863874),
	(949, 2, 50, 782, '["联合索引 · 列顺序设计"]', '判断联合索引优劣的固定判断标准：能否把索引列用到「等值定位 + 范围收窄」两段上，而不是只看列是否出现在索引里。', 1794366863874),
	(950, 2, 50, 784, '["最左前缀 · 范围条件的影响"]', '联合索引 (a,b,c)：a 等值、b 范围时，a、b 可用于索引定位，c 不可。', 1794367062126),
	(951, 2, 50, 784, '["最左前缀 · 范围条件的影响"]', '最左前缀原则：从最左列起连续匹配，遇到范围条件后，后续列失去索引定位能力。', 1794367062126),
	(952, 2, 50, 784, '["最左前缀 · 范围条件的影响"]', '范围列之后的列只能作为过滤条件（可在 ICP 下于引擎层过滤，减少回表）。', 1794367062126),
	(953, 2, 50, 784, '["最左前缀 · 范围条件的影响"]', '等值列在前、范围列在后，是设计联合索引的常见顺序原则。', 1794367062126),
	(954, 2, 50, 786, '["回表 · 过程与代价"]', '二级索引（普通索引）叶子节点存的是：索引列的值 + 主键值，不存整行。', 1794376176472),
	(955, 2, 50, 786, '["回表 · 过程与代价"]', '回表 = 用二级索引拿到的 id，再走一次聚簇索引 B+ 树取完整行。', 1794376176472),
	(956, 2, 50, 786, '["回表 · 过程与代价"]', '聚簇索引叶子节点存整行数据，主键查询一次树查找即可返回，不回表。', 1794376176472),
	(957, 2, 50, 786, '["回表 · 过程与代价"]', '回表的代价是多一次 B+ 树查找（若干次页访问），所以二级索引查询通常比主键查询慢。', 1794376176472),
	(958, 2, 50, 787, '["回表 · 减少回表的办法"]', '回表：二级索引叶子节点只存「索引列+主键」，取整行数据须按主键再查一次聚簇索引。', 1794376378806),
	(959, 2, 50, 787, '["回表 · 减少回表的办法"]', '回表代价：每行一次随机 I/O，命中行数越多代价越大，所以订单列表这类多行查询要尽量少回表。', 1794376378806),
	(960, 2, 50, 787, '["回表 · 减少回表的办法"]', '减少回表的两种常见做法：①索引覆盖（把查询列建成联合索引，或只查索引内的列）；②延迟关联/先用覆盖索引取主键再关联取列。', 1794376378806),
	(961, 2, 50, 787, '["回表 · 减少回表的办法"]', '判断是否回表看 EXPLAIN 的 Extra：出现 Using index 表示覆盖索引、不回表。', 1794376378806),
	(962, 2, 50, 788, '["索引覆盖 · 判定与使用"]', 'InnoDB 二级索引叶子节点存「索引列 + 主键值」，这是索引覆盖能成立的根本原因。', 1794376662444),
	(963, 2, 50, 788, '["索引覆盖 · 判定与使用"]', '索引覆盖 = 查询涉及的所有列都能从索引里取到；本例只需 id，而 id 就在二级索引里，故不回表。', 1794376662444),
	(964, 2, 50, 788, '["索引覆盖 · 判定与使用"]', '最左前缀解决的是「索引能不能用上」，索引覆盖解决的是「要不要回表」，两个概念不要混。', 1794376662444),
	(965, 2, 50, 788, '["索引覆盖 · 判定与使用"]', '主键列天然包含在二级索引中，所以 `SELECT 主键 FROM t WHERE 索引列=...` 通常是覆盖查询。', 1794376662444),
	(966, 2, 16, 791, '["项目生命周期 · 阶段划分与选择"]', '交付物定义清晰、变更少、强合规 → **预测型/瀑布生命周期**', 1794381885001),
	(967, 2, 16, 791, '["项目生命周期 · 阶段划分与选择"]', '合规审查是**阶段关口（Stage Gate）**，设在各阶段末作为准出条件', 1794381885001),
	(968, 2, 16, 791, '["项目生命周期 · 阶段划分与选择"]', '阶段门的作用：通过评审才放行下一阶段，风险与合规前置拦截', 1794381885001),
	(969, 2, 16, 792, '["敏捷实践 · 三大支柱与价值观"]', 'Scrum 三支柱：**透明、检视、适应**', 1794381885014),
	(970, 2, 16, 792, '["敏捷实践 · 三大支柱与价值观"]', '站会只报顺利、隐藏风险 → 信息不透明，后续检视与适应都建立在失真信息上', 1794381885014),
	(971, 2, 16, 792, '["敏捷实践 · 三大支柱与价值观"]', '补救靠**可视化（看板）+ 安全氛围 + 主持人引导追问阻碍**', 1794381885014),
	(972, 2, 16, 793, '["Scrum · 角色与仪式"]', '产品待办列表优先级 → **产品负责人（PO）**负责排序', 1794381885018),
	(973, 2, 16, 793, '["Scrum · 角色与仪式"]', '每日站会的产出 = **当日工作计划与团队共识 + 障碍暴露**，不是进度汇报', 1794381885018),
	(974, 2, 16, 793, '["Scrum · 角色与仪式"]', '站会三问：昨天做了什么、今天做什么、有什么阻碍', 1794381885018),
	(975, 2, 16, 796, '["质量管理 · 代码评审与技术评审"]', '代码评审解决“这段代码对不对”，项目层评审解决“这个版本能不能上”', 1794381885021),
	(976, 2, 16, 796, '["质量管理 · 代码评审与技术评审"]', '顺序：**代码评审在前（合入基线的准入/准出）→ 上线评审在后（上线放行的准出）**', 1794381885021),
	(977, 2, 16, 796, '["质量管理 · 代码评审与技术评审"]', '上线评审的准入：测试通过、缺陷收敛、交付物齐备、风险与回滚方案明确', 1794381885021),
	(978, 2, 16, 798, '["总工期影响分析"]', '关键路径**没有浮动时间**，拖延多久总工期就延多久', 1794381885025),
	(979, 2, 16, 798, '["总工期影响分析"]', '非关键活动有**总浮动时间**，拖延 ≤ 浮时不影响工期', 1794381885025),
	(980, 2, 16, 798, '["总工期影响分析"]', '判断条件：**拖延量 vs 总浮动时间**；超过则工期延长超出部分，可能形成新关键路径', 1794381885025),
	(981, 2, 16, 799, '["风险管理 · 风险识别后登记与责任人落实"]', '风险条目要素：**描述 + 概率/影响等级 + 唯一责任人 + 应对措施 + 触发条件 + 截止时间 + 状态**', 1794381885027),
	(982, 2, 16, 799, '["风险管理 · 风险识别后登记与责任人落实"]', '例会只看高等级与逾期项，按“上次承诺→下一步→何时完成→需要什么支持”追问', 1794381885027),
	(983, 2, 16, 799, '["风险管理 · 风险识别后登记与责任人落实"]', '无人认领：当场指定责任人并公示；盯不住：转为带负责人和截止日的行动项，固定议程 + 逾期升级', 1794381885027),
	(984, 2, 16, 794, '["关键路径识别"]', '本题三条路径：**A-B-D-F=14 / A-C-D-F=12 / A-C-E-F=10**，漏路径是最常见失分点', 1794381885030),
	(985, 2, 16, 794, '["关键路径识别"]', '关键路径 = 最长路径 = 总工期，本题 **A-B-D-F，14 天**', 1794381885030),
	(986, 2, 16, 794, '["关键路径识别"]', '压缩工期只压**关键路径上的活动**，并优先选成本低、可压缩、风险小的；压完要重算网络图', 1794381885030),
	(987, 2, 50, 789, '["索引覆盖 · 代价与取舍"]', '覆盖索引不是索引类型，而是查询所需列全部落在同一索引中、无需回表的使用状态', 1794384442248),
	(988, 2, 50, 789, '["索引覆盖 · 代价与取舍"]', '判断依据：SELECT 列 + WHERE/ORDER BY/GROUP BY 列都在该索引键列内，二级索引叶子自带主键，执行计划出现 Using index', 1794384442248),
	(989, 2, 50, 789, '["索引覆盖 · 代价与取舍"]', '减少回表的原理：二级索引叶子节点已存所需字段，不必按主键再回聚簇索引取整行', 1794384442248),
	(990, 2, 50, 789, '["索引覆盖 · 代价与取舍"]', '主要代价：索引冗余列变多，占空间、增大写放大与维护成本', 1794384442248),
	(991, 2, 50, 803, '["索引 · 区分度与选择性"]', '低区分度列指不同取值种类很少、重复度很高的列，如状态、性别、布尔标记。', 1794384537002),
	(992, 2, 50, 803, '["索引 · 区分度与选择性"]', '区分度（选择性/基数）= count(distinct col) / count(*)，越接近 1 越好，越接近 0 越差。', 1794384537002),
	(993, 2, 50, 803, '["索引 · 区分度与选择性"]', '区分度太低时，一次等值查询仍要扫回大量行，优化器往往放弃索引直接全表扫描。', 1794384537002),
	(994, 2, 50, 803, '["索引 · 区分度与选择性"]', '索引本身占空间、增删改都要维护，区分度低的列维护成本大于查询收益。', 1794384537002),
	(995, 2, 50, 804, '["Explain · 关键列解读"]', 'type 是访问类型，性能排序大致为 system > const > eq_ref > ref > range > index > ALL，出现 ALL 说明全表扫描', 1794384622393),
	(996, 2, 50, 804, '["Explain · 关键列解读"]', 'key 是优化器实际选中的索引，为 NULL 表示没有用到索引；possible_keys 只是候选', 1794384622393),
	(997, 2, 50, 804, '["Explain · 关键列解读"]', 'rows 是优化器估算需要扫描的行数，是估算值不是精确值，越小越好', 1794384622393),
	(998, 2, 50, 804, '["Explain · 关键列解读"]', 'Extra 常见值：Using index（索引覆盖、不回表）、Using where（server 层过滤）、Using filesort / Using temporary（额外排序或临时表，重点优化对象）', 1794384622393),
	(999, 2, 50, 805, '["索引设计 · 建索引的取舍"]', '索引收益：把全表扫描变索引定位，减少扫描行数、可用覆盖索引避免回表、加速排序与连接', 1794385360313),
	(1000, 2, 50, 805, '["索引设计 · 建索引的取舍"]', '索引代价：占磁盘与缓冲池空间、增删改要同步维护（写放大）、索引多了优化器可能选错', 1794385360313),
	(1001, 2, 50, 805, '["索引设计 · 建索引的取舍"]', '读多写少的表写维护代价被稀释，可适当多建；写多读少的表要克制', 1794385360313),
	(1002, 2, 50, 805, '["索引设计 · 建索引的取舍"]', '建索引要落到真实 SQL 的过滤/排序/连接字段，不为低选择性或几乎不用的字段建', 1794385360313),
	(1003, 2, 50, 806, '["深分页 · 慢查询优化"]', 'LIMIT offset,n 的代价是扫描并丢弃前 offset 行，深翻页成本随 offset 线性增长；SELECT * 还会伴随**大量无效回表**。', 1794386240703),
	(1004, 2, 50, 806, '["深分页 · 慢查询优化"]', '游标/延迟分页：`WHERE id > 上一页最后id ORDER BY id LIMIT n`，用索引**直接定位起点**，不扫前面所有行。', 1794386240703),
	(1005, 2, 50, 806, '["深分页 · 慢查询优化"]', '延迟关联：先用**覆盖索引**子查询取出目标 10 个主键，再 join 回原表取整行，减少无效回表。', 1794386240703),
	(1006, 2, 50, 806, '["深分页 · 慢查询优化"]', '业务上限制可跳页深度、只允许「下一页」是规避手段，不改变单条 SQL 本身的代价。', 1794386240703),
	(1007, 2, 50, 808, '["慢查询 · 索引相关排查思路"]', 'EXPLAIN 先看 type 判断访问类型，ALL/index 要警惕，const/ref/range 较优。', 1794386918425),
	(1008, 2, 50, 808, '["慢查询 · 索引相关排查思路"]', 'key 看实际使用索引，key_len 看联合索引用到第几列，rows 看预估扫描行数。', 1794386918425),
	(1009, 2, 50, 808, '["慢查询 · 索引相关排查思路"]', 'Extra 重点看 Using filesort、Using temporary、Using index。', 1794386918425),
	(1010, 2, 50, 808, '["慢查询 · 索引相关排查思路"]', '先看 Extra 也能快速抓排序、临时表、覆盖索引信号，但需回看 type/key/rows 定位。', 1794386918425),
	(1011, 2, 50, 809, '["联合索引 · 排序与分组"]', 'ORDER BY 用索引避免排序的三个条件：前导列等值匹配、排序列顺序与索引列顺序一致、方向一致或全部相反。', 1794387161106),
	(1012, 2, 50, 809, '["联合索引 · 排序与分组"]', 'WHERE 中一旦对某列做范围查询，其后的索引列就失去排序能力。', 1794387161106),
	(1013, 2, 50, 809, '["联合索引 · 排序与分组"]', '降序索引 idx(a, b DESC) 让 a=? ORDER BY b DESC 直接靠索引有序性免排序。', 1794387161106),
	(1014, 2, 50, 809, '["联合索引 · 排序与分组"]', '方向混合排序（b DESC, c ASC）无法靠单方向索引或反向扫描解决，需专门建 DESC 索引。', 1794387161106),
	(1015, 2, 50, 811, '["最左前缀 · 跳跃扫描"]', '单列索引在对应列的等值或范围条件上通常可被使用。', 1794388429105),
	(1016, 2, 50, 811, '["最左前缀 · 跳跃扫描"]', '联合索引遵循最左前缀：查询条件要从最左列开始连续使用。', 1794388429105),
	(1017, 2, 50, 811, '["最左前缀 · 跳跃扫描"]', '跳过联合索引最左列、直接用后续列，通常无法用于该条件的索引定位。', 1794388429105),
	(1018, 2, 50, 811, '["最左前缀 · 跳跃扫描"]', 'SELECT * 可能需要回表，但索引仍可先用于筛选。', 1794388429105),
	(1019, 2, 50, 812, '["前缀索引 · 使用与代价"]', '前缀索引只存前 N 个字符，单条索引记录更短，索引占用空间和树高都更小。', 1794388538264),
	(1020, 2, 50, 812, '["前缀索引 · 使用与代价"]', '前缀索引会命中相同前缀的多个值，必须回表取整行再按完整值过滤，回表次数比整列索引多。', 1794388538264),
	(1021, 2, 50, 812, '["前缀索引 · 使用与代价"]', '整列索引的索引值即完整值，等值查询定位到的就是精确匹配，通常回表一次即可。', 1794388538264),
	(1022, 2, 50, 812, '["前缀索引 · 使用与代价"]', '前缀索引不含完整列值，因此无法实现索引覆盖。', 1794388538264),
	(1023, 2, 50, 813, '["Explain · 关键列解读"]', '判断能否用索引：看 WHERE 的等值列是否按最左前缀连续命中，再看是否有范围条件截断后续列。', 1794388649642),
	(1024, 2, 50, 813, '["Explain · 关键列解读"]', 'ORDER BY 的列若紧接在等值列之后、且排序方向一致，可借索引顺序免排序；否则可能 filesort。', 1794388649642),
	(1025, 2, 50, 813, '["Explain · 关键列解读"]', '本题 idx_user_status_created(user_id, status, created_at)：两等值列命中前缀，created_at 承接排序，索引可用且无需额外排序。', 1794388649642),
	(1026, 2, 50, 813, '["Explain · 关键列解读"]', 'SELECT 列未全部被索引覆盖时仍需回表，但这不影响「能不能用上索引」的判断。', 1794388649642),
	(1027, 2, 50, 814, '["索引 · 区分度与选择性"]', '联合索引最左列的主要依据是**区分度（选择性）高**：不同取值多、重复少的列优先。', 1794388906382),
	(1028, 2, 50, 814, '["索引 · 区分度与选择性"]', '区分度高的列放最左，等值查询能一次把扫描范围缩到很小；低区分度列（如性别）放最左，过滤后仍剩大量行。', 1794388906382),
	(1029, 2, 50, 814, '["索引 · 区分度与选择性"]', '工程上还要兼顾**最左前缀的使用频率**：最常出现在查询条件里的列尽量靠左，否则索引用不上。', 1794388906382),
	(1030, 2, 50, 814, '["索引 · 区分度与选择性"]', '「最常用」与「区分度最高」冲突时，优先保证高频等值查询能走索引，但要清楚这是取舍不是原则。', 1794388906382),
	(1031, 2, 50, 815, '["联合索引 · 排序与分组"]', '联合索引 (a,b) 的叶子节点先按 a 有序、a 相同再按 b 有序，即整体按 (a,b) 字典序排列。', 1794389102060),
	(1032, 2, 50, 815, '["联合索引 · 排序与分组"]', 'ORDER BY 要走索引免排序，必须从索引最左列开始、且各列顺序与索引一致（全 ASC 或全 DESC 反向扫描亦可）。', 1794389102060),
	(1033, 2, 50, 815, '["联合索引 · 排序与分组"]', 'ORDER BY b,a 不以最左列 a 打头，无法利用 idx_ab 的顺序，EXPLAIN 会出现 Using filesort。', 1794389102060),
	(1034, 2, 50, 815, '["联合索引 · 排序与分组"]', '判断口诀：排序顺序 = 索引最左前缀顺序，才能避免额外排序。', 1794389102060),
	(1035, 2, 50, 816, '["索引覆盖 · 判定与使用"]', '二级索引叶子节点只存「索引列 + 主键值」，查询列不在索引里就必须回表。', 1794389227769),
	(1036, 2, 50, 816, '["索引覆盖 · 判定与使用"]', '回表 = 用二级索引拿到的主键值，再回聚簇索引取整行，不是「再用主键过滤」。', 1794389227769),
	(1037, 2, 50, 816, '["索引覆盖 · 判定与使用"]', '避免回表靠覆盖索引：把 SELECT 里的列（amount、create_time）加进联合索引，让查询所需列全部落在索引上。', 1794389227769),
	(1038, 2, 50, 816, '["索引覆盖 · 判定与使用"]', 'user_id 已是索引首列，无需重复添加，建覆盖索引时补上缺失列即可。', 1794389227769),
	(1039, 2, 50, 817, '["索引 · 区分度与选择性"]', '选择性（区分度）= 列的不同取值个数 / 表总行数，越接近 1 越适合建索引。', 1794389315523),
	(1040, 2, 50, 817, '["索引 · 区分度与选择性"]', '手机号接近唯一，选择性≈1，等值查询能快速定位到极少量行，应该建索引。', 1794389315523),
	(1041, 2, 50, 817, '["索引 · 区分度与选择性"]', '性别只有两三个取值，选择性极低，索引过滤后仍剩约一半数据，优化器往往不走索引，还要付出维护索引的代价，不建议单独建索引。', 1794389315523),
	(1042, 2, 50, 817, '["索引 · 区分度与选择性"]', '判断要不要建索引，本质是看这一列能把数据缩小到多少，而不是「有没有出现在 where 里」。', 1794389315523),
	(1043, 2, 50, 818, '["Explain · 关键列解读"]', '判断是否用上索引看 EXPLAIN 的 key 列（实际使用的索引），type=ALL 表示全表扫描；possible_keys 只是候选索引。', 1794389513554),
	(1044, 2, 50, 818, '["Explain · 关键列解读"]', 'Extra 里的 Using index 表示索引覆盖（不回表），不是「用上索引」的标志。', 1794389513554),
	(1045, 2, 50, 818, '["Explain · 关键列解读"]', '联合索引在 B+树中先按第一列排序、第一列相同再按第二列排序，因此跳过最左列后，后续列全局无序、无法二分定位范围。', 1794389513554),
	(1046, 2, 50, 818, '["Explain · 关键列解读"]', '最左前缀的本质是「利用索引的有序性定位范围」，不满足就无法缩小扫描区间，只能全表扫描或全索引扫描。', 1794389513554),
	(1047, 2, 56, 897, '["传播属性 · REQUIRED 与 REQUIRES_NEW 的取舍"]', 'REQUIRED 是默认传播属性：有事务则加入，无事务则新建。', 1794470583840),
	(1048, 2, 56, 897, '["传播属性 · REQUIRED 与 REQUIRES_NEW 的取舍"]', 'REQUIRES_NEW 会挂起当前事务并新建独立事务，适合日志等失败不影响主业务的旁路操作。', 1794470583840),
	(1049, 2, 56, 897, '["传播属性 · REQUIRED 与 REQUIRES_NEW 的取舍"]', '同一个类内部 this 调用不经过 Spring 代理，@Transactional 的传播属性配置会失效。', 1794470583840),
	(1050, 2, 56, 897, '["传播属性 · REQUIRED 与 REQUIRES_NEW 的取舍"]', '要让同类中的日志方法使用 REQUIRES_NEW，需拆到另一个 Bean 或通过代理/AopContext 调用。', 1794470583840),
	(1051, 2, 56, 898, '["传播属性 · NESTED 与保存点的关系"]', 'Spring 声明式事务基于 AOP 代理，只有**经过代理对象**的调用才会被事务拦截器处理。', 1794470670660),
	(1052, 2, 56, 898, '["传播属性 · NESTED 与保存点的关系"]', '同类内部 `this.B()` 调用绕过代理，B 上的 @Transactional 直接失效。', 1794470670660),
	(1053, 2, 56, 898, '["传播属性 · NESTED 与保存点的关系"]', '判断事务是否生效的第一问：这次调用**是不是从代理进来的**。', 1794470670660),
	(1054, 2, 56, 898, '["传播属性 · NESTED 与保存点的关系"]', '要生效就得走出代理：拆到另一个 Bean、自注入代理、或改用 TransactionTemplate。', 1794470670660),
	(1055, 2, 56, 899, '["传播属性 · 无事务场景的三种行为"]', 'REQUIRED（默认）：调用方有事务就加入，没有就新建。', 1794470882382),
	(1056, 2, 56, 899, '["传播属性 · 无事务场景的三种行为"]', 'REQUIRES_NEW：外层有无事务都新建独立事务，外层事务被挂起，内外提交和回滚互不影响。', 1794470882382),
	(1057, 2, 56, 899, '["传播属性 · 无事务场景的三种行为"]', 'NESTED：外层有事务时建保存点，失败只回滚到保存点；外层无事务时等同于 REQUIRED 新建事务。', 1794470882382),
	(1058, 2, 56, 899, '["传播属性 · 无事务场景的三种行为"]', 'SUPPORTS：有事务就加入，没有就以非事务方式执行。', 1794470882382),
	(1059, 2, 56, 900, '["传播属性 · 传播行为配置方式与常见误用"]', '@Transactional 用 **propagation** 属性配置传播行为，类型是 Propagation 枚举。', 1794471108013),
	(1060, 2, 56, 900, '["传播属性 · 传播行为配置方式与常见误用"]', '默认传播行为是 **Propagation.REQUIRED**。', 1794471108013),
	(1061, 2, 56, 900, '["传播属性 · 传播行为配置方式与常见误用"]', 'REQUIRED 的语义：**有事务就加入当前事务（与外层同一个事务），没有就新建一个**。', 1794471108013),
	(1062, 2, 56, 900, '["传播属性 · 传播行为配置方式与常见误用"]', 'REQUIRED 下内层方法抛出运行时异常回滚时，会连同外层一起回滚，因为它们是同一个事务。', 1794471108013),
	(1063, 2, 56, 901, '["隔离级别 · 四种级别与对应问题"]', '四种隔离级别：读未提交、读已提交、可重复读、串行化，隔离性递增。', 1794471755761),
	(1064, 2, 56, 901, '["隔离级别 · 四种级别与对应问题"]', '读未提交不防任何问题；读已提交只防脏读；串行化脏读、不可重复读、幻读全防。', 1794471755761),
	(1065, 2, 56, 901, '["隔离级别 · 四种级别与对应问题"]', 'MySQL InnoDB 默认可重复读，MVCC 快照读防不可重复读，间隙锁/next-key lock 防当前读幻读。', 1794471755761),
	(1066, 2, 56, 901, '["隔离级别 · 四种级别与对应问题"]', '标准 SQL 的 RR 允许幻读，InnoDB 的 RR 基本防幻读，答题要区分。', 1794471755761),
	(1067, 2, 56, 901, '["隔离级别 · 四种级别与对应问题"]', '脏读=读到未提交数据；不可重复读=同一行两次读值不同；幻读=同一条件两次读行数不同。', 1794471755761),
	(1068, 2, 56, 902, '["隔离级别 · 设置方式与生效范围"]', '@Transactional 用 isolation 属性指定隔离级别，取值为 Isolation 枚举（DEFAULT、READ_UNCOMMITTED、READ_COMMITTED、REPEATABLE_READ、SERIALIZABLE）。', 1794471822360),
	(1069, 2, 56, 902, '["隔离级别 · 设置方式与生效范围"]', '不指定时是 Isolation.DEFAULT，不是某个具体级别。', 1794471822360),
	(1070, 2, 56, 902, '["隔离级别 · 设置方式与生效范围"]', 'Isolation.DEFAULT 的含义是沿用底层数据库的默认隔离级别，所以默认值由所用数据库决定：MySQL InnoDB 是 REPEATABLE READ，Oracle 是 READ COMMITTED。', 1794471822360),
	(1071, 2, 56, 902, '["隔离级别 · 设置方式与生效范围"]', '隔离级别最终由数据库实现，Spring 只是把设置透传给 JDBC 连接。', 1794471822360),
	(1072, 2, 56, 903, '["隔离级别 · MySQL 默认 RR 的原因"]', 'MySQL InnoDB 默认隔离级别是可重复读（RR），Oracle 默认是读已提交（RC）。', 1794471919129),
	(1073, 2, 56, 903, '["隔离级别 · MySQL 默认 RR 的原因"]', 'RC 只能避免脏读，不可重复读和幻读都可能出现；InnoDB 的 RR 用 MVCC 解决不可重复读，用间隙锁抑制幻读。', 1794471919129),
	(1074, 2, 56, 903, '["隔离级别 · MySQL 默认 RR 的原因"]', 'Oracle 选 RC：配合 MVCC/UNDO 实现高并发、减少锁竞争、避免长事务拖累。', 1794471919129),
	(1075, 2, 56, 903, '["隔离级别 · MySQL 默认 RR 的原因"]', 'InnoDB 选 RR：历史与主从复制兼容性考虑，加上间隙锁让幻读代价可控，所以保留 RR 作默认。', 1794471919129),
	(1076, 2, 56, 904, '["隔离级别 · SERIALIZABLE 的代价"]', 'SERIALIZABLE 下普通 SELECT 会被隐式转成加共享锁的读，并对扫描范围加 next-key lock（记录锁+间隙锁），别的事务插不进新行，所以没有幻读。', 1794473492427),
	(1077, 2, 56, 904, '["隔离级别 · SERIALIZABLE 的代价"]', '防幻读的关键不是「加共享锁」本身，而是锁住了**范围**（间隙），只锁已存在的记录挡不住新插入。', 1794473492427),
	(1078, 2, 56, 904, '["隔离级别 · SERIALIZABLE 的代价"]', '代价：读写被串行化，并发度骤降，锁等待、锁超时与死锁概率明显上升。', 1794473492427),
	(1079, 2, 56, 904, '["隔离级别 · SERIALIZABLE 的代价"]', '只在一致性要求极高且并发很低的场景用，如对账、批处理、金融结算；普通业务 RR 足够。', 1794473492427),
	(1080, 2, 56, 905, '["隔离级别 · 快照读与当前读"]', '快照读：读 ReadView 可见的版本（undo 版本链），不加锁；当前读：读最新已提交版本，加锁（FOR UPDATE / LOCK IN SHARE MODE / UPDATE / DELETE）。', 1794473611863),
	(1081, 2, 56, 905, '["隔离级别 · 快照读与当前读"]', '同一事务内快照读与当前读结果不同是正常现象，因为二者数据来源不同，不是不可重复读。', 1794473611863),
	(1082, 2, 56, 905, '["隔离级别 · 快照读与当前读"]', '不可重复读 = 同一事务内两次快照读在 RC 下读到不同结果；RR 下快照读可重复。', 1794473611863),
	(1083, 2, 56, 905, '["隔离级别 · 快照读与当前读"]', 'MVCC 只解决快照读的一致性，当前读的一致性靠锁（临键锁等）保证。', 1794473611863),
	(1084, 2, 56, 906, '["并发读问题 · 脏读"]', '脏读：一个事务读到了另一个事务**尚未提交**的数据，该数据随时可能因对方回滚而消失。', 1794473784851),
	(1085, 2, 56, 906, '["并发读问题 · 脏读"]', '避免脏读最低要把隔离级别提到**读已提交（RC）**。', 1794473784851),
	(1086, 2, 56, 906, '["并发读问题 · 脏读"]', '脏读的典型危害：基于可能回滚的数据做业务决策，导致数据不一致甚至资损。', 1794473784851),
	(1087, 2, 56, 906, '["并发读问题 · 脏读"]', '转账读到对方未提交的入账，就是脏读的标准例子。', 1794473784851),
	(1088, 2, 56, 907, '["并发读问题 · 不可重复读"]', '脏读=读到别的事务未提交的数据，对方回滚后即为无效数据。', 1794473880965),
	(1089, 2, 56, 907, '["并发读问题 · 不可重复读"]', '不可重复读=同一事务内两次读同一行，中间被其他事务修改并提交，两次结果不同。', 1794473880965),
	(1090, 2, 56, 907, '["并发读问题 · 不可重复读"]', '判断口诀：看读到的数据是否已提交——未提交是脏读，已提交但前后不一致是不可重复读。', 1794473880965),
	(1091, 2, 56, 908, '["并发读问题 · 幻读"]', '幻读：同一事务内两次相同条件范围查询，因其他事务**插入/删除**提交导致结果集**行数**变化。', 1794474011312),
	(1092, 2, 56, 908, '["并发读问题 · 幻读"]', '不可重复读：同一事务内两次读**同一行**，因其他事务修改提交导致**字段值**变化。', 1794474011312),
	(1093, 2, 56, 908, '["并发读问题 · 幻读"]', '一句话区分：不可重复读变的是**值**，幻读变的是**行的集合**。', 1794474011312),
	(1094, 2, 56, 908, '["并发读问题 · 幻读"]', 'InnoDB 在 RR 下用间隙锁/Next-Key Lock（快照读靠 MVCC）抑制幻读。', 1794474011312),
	(1095, 2, 56, 909, '["并发读问题 · 三类问题对比与选型"]', '严重程度通常排序：**脏读 > 不可重复读 > 幻读**。', 1794474340128),
	(1096, 2, 56, 909, '["并发读问题 · 三类问题对比与选型"]', '脏读：读到其他事务**未提交**的数据，该数据可能回滚，所以最严重。', 1794474340128),
	(1097, 2, 56, 909, '["并发读问题 · 三类问题对比与选型"]', '不可重复读：同一事务内两次读**同一行**，因其他事务修改并提交导致值不同。', 1794474340128),
	(1098, 2, 56, 909, '["并发读问题 · 三类问题对比与选型"]', '幻读：同一查询两次返回的**行集合不同**，因其他事务插入/删除并提交，不是读不到新增。', 1794474340128),
	(1099, 2, 56, 911, '["事务失效 · 同类内部自调用"]', '@Transactional 默认靠代理拦截，只有经过代理对象的调用才会开启事务。', 1794475276136),
	(1100, 2, 56, 911, '["事务失效 · 同类内部自调用"]', '同类 this 调用绕过代理，事务注解失效。', 1794475276136),
	(1101, 2, 56, 911, '["事务失效 · 同类内部自调用"]', '解决：注入自身/代理对象调用，AopContext.currentProxy()，或拆分到另一个 Bean。', 1794475276136),
	(1102, 2, 56, 914, '["事务失效 · 异常被吞或类型不匹配"]', 'Spring 声明式事务**默认只在方法抛出 RuntimeException 或 Error 时回滚**，受检异常默认不回滚。', 1794548155897),
	(1103, 2, 56, 914, '["事务失效 · 异常被吞或类型不匹配"]', '异常被 catch 吞掉、方法正常返回 → 事务管理器感知不到 → **提交而非回滚**，需手动 setRollbackOnly 或重新抛出。', 1794548155897),
	(1104, 2, 56, 914, '["事务失效 · 异常被吞或类型不匹配"]', '想让受检异常也回滚，要显式配置 **@Transactional(rollbackFor = Exception.class)**。', 1794548155897),
	(1105, 2, 56, 990, '["事务失效 · 传播行为用错导致外层无事务"]', 'REQUIRED：有外层事务就加入，没有就新开一个物理事务，是 Spring 的默认传播行为。', 1794548265898),
	(1106, 2, 56, 990, '["事务失效 · 传播行为用错导致外层无事务"]', '各自独立事务时，先执行完的方法已经提交，后面方法抛异常不会回滚它——回滚只作用于当前事务。', 1794548265898),
	(1107, 2, 56, 990, '["事务失效 · 传播行为用错导致外层无事务"]', '同一事务内才有一致性回滚（被调用方抛异常把整个事务标记为 rollback-only）。', 1794548265898),
	(1108, 2, 56, 990, '["事务失效 · 传播行为用错导致外层无事务"]', '「隔离性」讲的是并发事务之间的可见性，不要拿它解释回滚范围。', 1794548265898),
	(1109, 2, 56, 991, '["事务失效 · 多线程与异步"]', '@Transactional 的事务上下文存在 ThreadLocal 中，只对**当前线程**生效，子线程不会继承。', 1794549707947),
	(1110, 2, 56, 991, '["事务失效 · 多线程与异步"]', '子线程里的 DB 操作不参与主线程事务：成功不随主线程提交，失败也不随主线程回滚。', 1794549707947),
	(1111, 2, 56, 991, '["事务失效 · 多线程与异步"]', '要让子线程失败影响主线程，需在主线程拿到子线程结果（如 Future.get()）后抛出非受检异常，触发主线程回滚。', 1794549707947),
	(1112, 2, 56, 991, '["事务失效 · 多线程与异步"]', '子线程自己已提交的写不会因为主线程回滚而撤销，跨线程写要么各自补偿，要么把操作收回主线程做。', 1794549707947),
	(1113, 2, 56, 992, '["事务失效 · 数据源/引擎/配置层面"]', '方法在一个事务里不代表所有写操作同生共死：内层方法若声明 REQUIRES_NEW，会挂起外层事务、自己开一个新事务并独立提交。', 1794550083158),
	(1114, 2, 56, 992, '["事务失效 · 数据源/引擎/配置层面"]', '外层事务回滚只回滚它自己事务内的操作；内层 REQUIRES_NEW 已提交的写入不受影响，于是出现「部分回滚、部分已提交」。', 1794550083158),
	(1115, 2, 56, 992, '["事务失效 · 数据源/引擎/配置层面"]', 'REQUIRED（默认）才是加入当前事务、同生共死；NESTED 用保存点实现，回滚到保存点只撤销内层那部分。', 1794550083158),
	(1116, 2, 56, 992, '["事务失效 · 数据源/引擎/配置层面"]', '判断事务边界看的是「哪个事务提交了」，不是「代码是否写在同一个方法里」。', 1794550083158),
	(1117, 2, 56, 993, '["并发读问题 · 丢失更新"]', 'A、B 先后提交、后者覆盖前者，这叫**丢失更新（更新丢失）**，属于写-写冲突，不在脏读/不可重复读/幻读这三类读问题之内。', 1794550411576),
	(1118, 2, 56, 993, '["并发读问题 · 丢失更新"]', '脏读=读到未提交数据；不可重复读=同一行两次读值不同；幻读=同一范围两次查询行数不同——三者都是「读」的问题。', 1794550411576),
	(1119, 2, 56, 993, '["并发读问题 · 丢失更新"]', '丢失更新在 RC、RR 隔离级别下**都可能发生**，RR 的行锁只保证写时不冲突，不保证你写之前别人没改过。', 1794550411576),
	(1120, 2, 56, 993, '["并发读问题 · 丢失更新"]', '解决丢失更新：乐观锁（version/时间戳 + 更新时校验）或悲观锁（SELECT ... FOR UPDATE）；SERIALIZABLE 也能防，但并发代价大。', 1794550411576),
	(1121, 2, 56, 994, '["事务失效 · 方法非 public 或 final"]', '@Transactional 仅在代理模式下对外部调用生效：同类内部 this 调用绕过代理，事务失效。', 1794550539010),
	(1122, 2, 56, 994, '["事务失效 · 方法非 public 或 final"]', 'private 方法无法被代理覆盖、protected 方法不被事务属性解析，两者加 @Transactional 都不生效。', 1794550539010),
	(1123, 2, 56, 994, '["事务失效 · 方法非 public 或 final"]', 'Spring 事务默认只对 public 方法生效（proxy 模式下事务属性解析限定 public）。', 1794550539010),
	(1124, 2, 56, 994, '["事务失效 · 方法非 public 或 final"]', '通过接口注入的代理对象从外部调用 public 方法，才能进入事务拦截器链，事务才生效。', 1794550539010),
	(1125, 2, 56, 995, '["传播属性 · 七种传播行为概览"]', 'REQUIRES_NEW：挂起外层事务、开启独立新事务，内外层回滚互不影响，常用于日志、审计等必须留痕的场景。', 1794550619260),
	(1126, 2, 56, 995, '["传播属性 · 七种传播行为概览"]', 'REQUIRED：Spring 默认传播行为，有事务就加入、没有就新建，内外层共用一个事务，一起回滚。', 1794550619260),
	(1127, 2, 56, 995, '["传播属性 · 七种传播行为概览"]', 'NOT_SUPPORTED：不参与事务，若外层有事务则挂起，以非事务方式执行。', 1794550619260),
	(1128, 2, 56, 995, '["传播属性 · 七种传播行为概览"]', '同是挂起外层，REQUIRES_NEW 会开新事务，NOT_SUPPORTED 不开事务——这是两者的关键区别。', 1794550619260),
	(1129, 2, 56, 996, '["事务失效 · 数据源/引擎/配置层面"]', 'REQUIRES_NEW＝挂起外层事务、内层独立提交，外层回滚不牵连已提交的内层，是“半边不回滚”的典型配置原因。', 1794550805735),
	(1130, 2, 56, 996, '["事务失效 · 数据源/引擎/配置层面"]', 'rollbackFor 不配时默认只回滚 RuntimeException/Error，抛受检异常的那一半不回滚。', 1794550805735),
	(1131, 2, 56, 996, '["事务失效 · 数据源/引擎/配置层面"]', '@Transactional 失效三件套：this 自调用、方法非 public、异常被 catch 吞掉。', 1794550805735),
	(1132, 2, 56, 996, '["事务失效 · 数据源/引擎/配置层面"]', '排查半边不回滚先看：传播属性、rollbackFor、注解是否失效、是否同一事务管理器/同一数据源。', 1794550805735),
	(1133, 2, 56, 998, '["事务失效 · 数据源/引擎/配置层面"]', 'MyISAM 不支持事务、没有 undo log，写入直接落盘，执行即提交，无法 rollback。', 1794551276488),
	(1134, 2, 56, 998, '["事务失效 · 数据源/引擎/配置层面"]', '回滚的前提是引擎记录 undo 日志并能撤销未提交修改；应用代码抛异常本身不会回滚任何数据。', 1794551276488),
	(1135, 2, 56, 998, '["事务失效 · 数据源/引擎/配置层面"]', 'InnoDB 支持事务、行锁与 undo/redo，未提交的修改才能被 ROLLBACK 撤销。', 1794551276488),
	(1136, 2, 56, 998, '["事务失效 · 数据源/引擎/配置层面"]', '异常+未提交≠自动回滚：只有在支持事务的引擎上、且事务未提交时，回滚才成立。', 1794551276488),
	(1137, 2, 56, 999, '["隔离级别 · 设置方式与生效范围"]', 'MySQL 默认隔离级别是 **RR（可重复读）**，核心交易服务通常直接沿用默认的 RR。', 1794551433182),
	(1138, 2, 56, 999, '["隔离级别 · 设置方式与生效范围"]', '报表类只读服务常用 **RC（读已提交）**：只读、不需要事务内快照一致，并且 RC 不加间隙锁、锁冲突小、能读到最新已提交数据。', 1794551433182),
	(1139, 2, 56, 999, '["隔离级别 · 设置方式与生效范围"]', 'RR 的价值在于让**同一事务内多次读看到同一份快照**，避免不可重复读和幻读，使「先查库存/余额再更新」的判断不失真。', 1794551433182),
	(1140, 2, 56, 999, '["隔离级别 · 设置方式与生效范围"]', 'RR 防不住**丢失更新**，这类问题要用乐观锁（版本号）或悲观锁（select for update）解决。', 1794551433182),
	(1141, 2, 56, 1001, '["隔离级别 · 快照读与当前读"]', '普通 SELECT 在 RR/RC 下都是快照读（一致性读），不加锁；UPDATE/DELETE/INSERT 及 SELECT ... FOR UPDATE 是当前读，读最新已提交数据并加锁。', 1794551810698),
	(1142, 2, 56, 1001, '["隔离级别 · 快照读与当前读"]', '快照读的可见性由 read view 决定，当前读不受 read view 约束，直接读最新版本。', 1794551810698),
	(1143, 2, 56, 1001, '["隔离级别 · 快照读与当前读"]', '「先 SELECT 判断再 UPDATE」的不一致来源于两条语句之间有别的事务提交了修改，使快照值与最新值出现偏差。', 1794551810698),
	(1144, 2, 56, 1001, '["隔离级别 · 快照读与当前读"]', '判断扣减是否成功应以 UPDATE 的影响行数为准，而不是以先前的 SELECT 结果为准。', 1794551810698),
	(1145, 2, 56, 1003, '["事务失效 · 数据源/引擎/配置层面"]', '排查 @Transactional 不回滚，先看表引擎：**MyISAM 不支持事务**，要用 InnoDB。', 1794551945175),
	(1146, 2, 56, 1003, '["事务失效 · 数据源/引擎/配置层面"]', 'Spring 默认只对 **RuntimeException 和 Error** 回滚，受检异常默认不回滚。', 1794551945175),
	(1147, 2, 56, 1003, '["事务失效 · 数据源/引擎/配置层面"]', '受检异常要回滚，需显式配置 **rollbackFor**，例如 rollbackFor = Exception.class。', 1794551945175),
	(1148, 2, 56, 1004, '["事务失效 · 数据源/引擎/配置层面"]', 'Spring 声明式事务基于代理实现，默认只对 **public 方法**生效，protected、private、包级可见方法上的 @Transactional 不生效（也不报错）。', 1794552041939),
	(1149, 2, 56, 1004, '["事务失效 · 数据源/引擎/配置层面"]', '同类内部方法调用通过 `this` 调用，**不经过代理对象**，因此被调用的 @Transactional 方法不会开启事务。', 1794552041939),
	(1150, 2, 56, 1004, '["事务失效 · 数据源/引擎/配置层面"]', '事务失效的两大高频原因：**方法非 public**、**同类内部自调用**；其余还有异常被吞、异常类型不匹配 rollbackFor、类未被 Spring 管理。', 1794552041939),
	(1151, 2, 56, 1004, '["事务失效 · 数据源/引擎/配置层面"]', '要自调用也生效，可注入自身代理、用 AopContext.currentProxy()，或把方法拆到另一个 Bean 中。', 1794552041939),
	(1152, 2, 56, 1005, '["并发读问题 · 丢失更新"]', '丢失更新是写-写冲突，不属于脏读、不可重复读、幻读这类读现象。', 1794552182438),
	(1153, 2, 56, 1005, '["并发读问题 · 丢失更新"]', '不可重复读：同一行两次读取值不同；幻读：同一条件两次查询结果集或行数变化。', 1794552182438),
	(1154, 2, 56, 1005, '["并发读问题 · 丢失更新"]', '丢失更新：两个事务都基于同一旧值读后写回，后写覆盖先写。', 1794552182438),
	(1155, 2, 56, 1005, '["并发读问题 · 丢失更新"]', '单纯提高隔离级别到RR不一定避免丢失更新，需显式锁、原子更新、版本号或可串行化。', 1794552182438),
	(1156, 2, 56, 1006, '["并发读问题 · 三类问题对比与选型"]', '脏读=读到其他事务未提交（可能回滚）的数据；不可重复读=同一行两次读值不同（多为 update）；幻读=同一范围两次读行数不同（多为 insert/delete）', 1794556193026),
	(1157, 2, 56, 1006, '["并发读问题 · 三类问题对比与选型"]', '严重性排序：脏读 > 不可重复读 > 幻读，依据是脏数据从未生效、业务无法补救，而幻读可用间隙锁/串行化控制', 1794556193026),
	(1158, 2, 56, 1006, '["并发读问题 · 三类问题对比与选型"]', '隔离级别从低到高：读未提交、读已提交（解决脏读）、可重复读（解决不可重复读+快照下大部分幻读）、串行化', 1794556193026),
	(1159, 2, 56, 1007, '["隔离级别 · MySQL 默认 RR 的原因"]', 'Oracle 默认隔离级别是 READ COMMITTED，MySQL InnoDB 默认是 REPEATABLE READ。', 1794556332308),
	(1160, 2, 56, 1007, '["隔离级别 · MySQL 默认 RR 的原因"]', '脏读两边都不会发生：Oracle RC 本就不允许，InnoDB MVCC 只读已提交版本。', 1794556332308),
	(1161, 2, 56, 1007, '["隔离级别 · MySQL 默认 RR 的原因"]', '不可重复读：Oracle RC 下同事务两次读同一行可能不同；MySQL RR 下快照读在同一事务内结果一致。', 1794556332308),
	(1162, 2, 56, 1007, '["隔离级别 · MySQL 默认 RR 的原因"]', '幻读：Oracle RC 下范围查询可能看到新插入行；MySQL RR 下快照读不出现幻读，当前读（加锁读）仍可能出现。', 1794556332308),
	(1163, 2, 56, 1009, '["传播属性 · 七种传播行为概览"]', 'REQUIRED：有事务加入，无事务新建；NESTED：有事务建保存点且不挂起外层，无事务新建。', 1794556616050),
	(1164, 2, 56, 1009, '["传播属性 · 七种传播行为概览"]', 'REQUIRES_NEW：有事务时挂起外层并新建独立事务；NOT_SUPPORTED：有事务时挂起外层，非事务执行。', 1794556616050),
	(1165, 2, 56, 1009, '["传播属性 · 七种传播行为概览"]', 'SUPPORTS：有事务加入，无事务非事务执行。', 1794556616050),
	(1166, 2, 56, 1009, '["传播属性 · 七种传播行为概览"]', 'MANDATORY 无事务抛异常；NEVER 有事务抛异常。', 1794556616050),
	(1167, 2, 56, 1010, '["传播属性 · 七种传播行为概览"]', 'REQUIRED：复用当前事务；当前无事务才新建。', 1794556804671),
	(1168, 2, 56, 1010, '["传播属性 · 七种传播行为概览"]', 'REQUIRES_NEW：总是新开事务，并挂起外层事务。', 1794556804671),
	(1169, 2, 56, 1010, '["传播属性 · 七种传播行为概览"]', 'NESTED：复用外层事务并设保存点，失败回滚到保存点。', 1794556804671),
	(1170, 2, 56, 1010, '["传播属性 · 七种传播行为概览"]', 'SUPPORTS：有事务就加入，无事务则以非事务方式执行。', 1794556804671),
	(1171, 2, 56, 1011, '["隔离级别 · MySQL 默认 RR 的原因"]', 'MySQL（InnoDB）默认隔离级别是 RR 可重复读，Oracle 默认是 RC 读已提交。', 1794556920854),
	(1172, 2, 56, 1011, '["隔离级别 · MySQL 默认 RR 的原因"]', 'RC 能防脏读，但允许不可重复读和幻读；RR 防脏读和不可重复读，幻读靠间隙锁或串行化缓解。', 1794556920854),
	(1173, 2, 56, 1011, '["隔离级别 · MySQL 默认 RR 的原因"]', 'Oracle 只支持 READ COMMITTED 和 SERIALIZABLE，没有 REPEATABLE READ 级别，迁移时想提升隔离性只能提到 SERIALIZABLE。', 1794556920854),
	(1174, 2, 56, 1011, '["隔离级别 · MySQL 默认 RR 的原因"]', '对齐手段：数据库层提升隔离级别造成锁竞争和并发下降，或应用层 SELECT ... FOR UPDATE 加锁、乐观锁版本号、合并或缓存首次查询结果。', 1794556920854),
	(1175, 2, 56, 1012, '["隔离级别 · MySQL 默认 RR 的原因"]', 'MySQL InnoDB 默认可重复读（RR），Oracle 默认读已提交（RC）。', 1794557021456),
	(1176, 2, 56, 1012, '["隔离级别 · MySQL 默认 RR 的原因"]', 'InnoDB 一致性读 = undo log 版本链 + ReadView；RR 下 ReadView 在事务内首次快照读时创建并全程复用。', 1794557021456),
	(1177, 2, 56, 1012, '["隔离级别 · MySQL 默认 RR 的原因"]', 'Oracle 的一致性读是语句级快照（基于 SCN），每条语句取新快照，效果等价于 RC。', 1794557021456),
	(1178, 2, 56, 1012, '["隔离级别 · MySQL 默认 RR 的原因"]', 'RR 下快照读靠 MVCC 防幻读，当前读（加锁读/更新）靠 next-key lock 防幻读。', 1794557021456),
	(1179, 2, 56, 1013, '["并发读问题 · 丢失更新"]', '丢失更新是并发写覆盖，不属于脏读/不可重复读/幻读。', 1794557251719),
	(1180, 2, 56, 1013, '["并发读问题 · 丢失更新"]', '悲观锁：事务内 SELECT ... FOR UPDATE 锁行后再更新。', 1794557251719),
	(1181, 2, 56, 1013, '["并发读问题 · 丢失更新"]', '乐观锁：版本号条件更新，影响行数为 0 表示冲突。', 1794557251719),
	(1182, 2, 56, 1013, '["并发读问题 · 丢失更新"]', '可串行化隔离级别可避免丢失更新。', 1794557251719),
	(1183, 2, 56, 1014, '["事务失效 · 数据源/引擎/配置层面"]', '事务管理器回滚的是它绑定的那个 DataSource 上的连接，不是方法里所有数据库操作', 1794557360778),
	(1184, 2, 56, 1014, '["事务失效 · 数据源/引擎/配置层面"]', '一个连接只能承载一个本地事务，不同数据源天然无法共享同一事务，跨库写必须显式协调', 1794557360778),
	(1185, 2, 56, 1014, '["事务失效 · 数据源/引擎/配置层面"]', '多数据源可以各配一个 DataSourceTransactionManager，但单个 @Transactional 默认只会用其中一个', 1794557360778),
	(1186, 2, 56, 1014, '["事务失效 · 数据源/引擎/配置层面"]', '跨库原子性需要 XA/JTA 两阶段提交，或 Seata、本地消息表+MQ 等最终一致方案', 1794557360778),
	(1187, 2, 56, 1015, '["事务失效 · 数据源/引擎/配置层面"]', 'Spring 声明式事务基于 AOP 动态代理，只有经过代理对象的调用才会被事务拦截器增强。', 1794557816083),
	(1188, 2, 56, 1015, '["事务失效 · 数据源/引擎/配置层面"]', '同类内部方法直接调用走的是 this，绕过代理，事务注解失效。', 1794557816083),
	(1189, 2, 56, 1015, '["事务失效 · 数据源/引擎/配置层面"]', '自调用导致事务失效的原因是代理机制未生效，与传播属性、隔离级别无关。', 1794557816083),
	(1190, 2, 56, 1015, '["事务失效 · 数据源/引擎/配置层面"]', '解决自调用的常见做法：注入自身代理、拆到另一个 Bean、或用 AopContext 暴露代理。', 1794557816083),
	(1191, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', '同类内部方法调用不经过代理，被调用方法上的 @Transactional 失效。', 1794558028736),
	(1192, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', 'REQUIRED 传播下，自调用失效的 B 不会开新事务，而是加入 A 已存在的事务。', 1794558028736),
	(1193, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', '异常从 A 方法抛出且为运行时异常时，A 的 @Transactional 默认回滚，A 和 B 的数据库操作一起回滚。', 1794558028736),
	(1194, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', '判断事务是否生效，先看调用是否经过 Spring 代理。', 1794558028736),
	(1195, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', '同类内部调用不走 Spring 代理，被调方法上的 @Transactional 不生效。', 1794558107307),
	(1196, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', '自调用时，被调方法运行在调用方已开启的事务中，不会单独提交。', 1794558107307),
	(1197, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', 'REQUIRED 默认加入当前事务；异常传播到外层会导致整个事务回滚。', 1794558107307),
	(1198, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', '事务边界由代理入口决定，不是由方法上是否写了注解单独决定。', 1794558107307),
	(1199, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', '同类内部自调用不走代理，被调方法上的 @Transactional 失效；而外层方法的事务照常存在。', 1794558636162),
	(1200, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', 'REQUIRED 的语义：已有事务则加入，没有才新建；自调用场景下 B 连“加入”这一步都没发生，只是直接跑在 A 的事务里。', 1794558636162),
	(1201, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', '事务边界在代理入口：异常必须抛出到代理方法外，才会被事务拦截器看到并触发回滚；A 内部 try-catch 吞掉则不回滚。', 1794558636162),
	(1202, 2, 56, 1016, '["事务失效 · 传播行为用错导致外层无事务"]', 'Spring 默认只对 RuntimeException 和 Error 回滚，受检异常默认不回滚（可 rollbackFor 指定）。', 1794558636162),
	(1203, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', '单方法/类上写：`@Transactional(isolation = Isolation.READ_COMMITTED)`，Isolation 来自 org.springframework.transaction.annotation 包。', 1794560982493),
	(1204, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', '全局改：`spring.datasource.hikari.transaction-isolation=TRANSACTION_READ_COMMITTED`，值是 JDBC Connection 的常量名。', 1794560982493),
	(1205, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', '两套命名不要混：Spring 侧是 `Isolation.READ_COMMITTED`，Hikari/JDBC 侧是 `TRANSACTION_READ_COMMITTED`。', 1794560982493),
	(1206, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', '注解上的 isolation 优先级高于 yml 里的全局默认值。', 1794560982493),
	(1207, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', '注解写法：@Transactional(isolation = Isolation.READ_COMMITTED)，枚举类为 org.springframework.transaction.annotation.Isolation。', 1794561066012),
	(1208, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', '全局写法：spring.datasource.hikari.transaction-isolation: TRANSACTION_READ_COMMITTED，注意前缀是 spring 不是 soring。', 1794561066012),
	(1209, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', 'Hikari 的这个配置值是 java.sql.Connection 的常量名（TRANSACTION_* 前缀），与注解枚举的写法不同，容易混淆。', 1794561066012),
	(1210, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', '注解与全局配置是两套写法：注解用 Isolation 枚举，连接池配置用 Connection 常量字符串。', 1794561066012),
	(1211, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', '注解方式：`@Transactional(isolation = Isolation.READ_COMMITTED)`，位于方法或类上，方法级优先于类级。', 1794561119001),
	(1212, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', 'HikariCP 全局配置：`spring.datasource.hikari.transaction-isolation: TRANSACTION_READ_COMMITTED`，取值是 `java.sql.Connection` 常量名而不是枚举名。', 1794561119001),
	(1213, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', 'READ COMMITTED 只能防脏读，防不住不可重复读与幻读；MySQL InnoDB 默认是 REPEATABLE_READ。', 1794561119001),
	(1214, 2, 56, 1017, '["隔离级别 · 设置方式与生效范围"]', '优先级：方法注解 > 类注解 > 连接池全局默认。', 1794561119001),
	(1215, 2, 56, 1018, '["隔离级别 · 快照读与当前读"]', '普通 SELECT 在 InnoDB 中通常是**快照读**，读取事务的一致性快照。', 1794561252028),
	(1216, 2, 56, 1018, '["隔离级别 · 快照读与当前读"]', 'UPDATE/DELETE/INSERT 以及 SELECT ... FOR UPDATE 是**当前读**，读取最新已提交数据并加锁。', 1794561252028),
	(1217, 2, 56, 1018, '["隔离级别 · 快照读与当前读"]', '先查后改在并发下不安全，因为**快照判断**和**当前扣减**可能基于不同版本的数据。', 1794561252028),
	(1218, 2, 56, 1018, '["隔离级别 · 快照读与当前读"]', '需要 `SELECT ... FOR UPDATE` 或带条件的原子 UPDATE 来保证库存校验与扣减的一致性。', 1794561252028),
	(1219, 2, 56, 1019, '["隔离级别 · MySQL 默认 RR 的原因"]', 'InnoDB 的 RR 能防脏读、不可重复读，幻读靠 next-key lock（记录锁+间隙锁）在当前读下防住，快照读靠 MVCC。', 1794561797414),
	(1220, 2, 56, 1019, '["隔离级别 · MySQL 默认 RR 的原因"]', '串行化 = 读加共享锁、写加排他锁，读写互斥、事务近似串行，并发度与吞吐骤降，易锁等待/超时/死锁。', 1794561797414),
	(1221, 2, 56, 1019, '["隔离级别 · MySQL 默认 RR 的原因"]', '实际项目默认 RR 或 RC，用 MVCC 提供一致性读；串行化只在极少数强一致、低并发场景考虑。', 1794561797414);

-- 导出  表 public.mistake 结构
CREATE TABLE IF NOT EXISTS "mistake" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"practice_id" BIGINT NOT NULL,
	"question_id" BIGINT NOT NULL,
	"source" VARCHAR(16) NULL DEFAULT NULL,
	"reason" TEXT NULL DEFAULT NULL,
	"score" DOUBLE PRECISION NULL DEFAULT NULL,
	"status" VARCHAR(16) NULL DEFAULT NULL,
	"resolved_at" BIGINT NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	"updated_at" BIGINT NOT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "mistake_updated_at_not_null1" CHECK (updated_at IS NOT NULL),
	CONSTRAINT "mistake_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "mistake_question_id_not_null1" CHECK (question_id IS NOT NULL),
	CONSTRAINT "mistake_practice_id_not_null1" CHECK (practice_id IS NOT NULL),
	CONSTRAINT "mistake_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "mistake_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_mistake_user_practice" ON "" ("user_id", "practice_id", "created_at");;

