-- 导出  表 public.note 结构
CREATE TABLE IF NOT EXISTS "note" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"practice_id" BIGINT NOT NULL,
	"question_id" BIGINT NULL DEFAULT NULL,
	"scene" VARCHAR(16) NULL DEFAULT NULL,
	"text" TEXT NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	"updated_at" BIGINT NOT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "note_updated_at_not_null1" CHECK (updated_at IS NOT NULL),
	CONSTRAINT "note_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "note_practice_id_not_null1" CHECK (practice_id IS NOT NULL),
	CONSTRAINT "note_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "note_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_note_user_practice" ON "" ("user_id", "practice_id", "created_at");;

-- 正在导出表  public.note 的数据：-1 rows
DELETE FROM "note";

-- 导出  表 public.paper 结构
CREATE TABLE IF NOT EXISTS "paper" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"practice_id" BIGINT NOT NULL,
	"sequence" INTEGER NOT NULL,
	"kind" VARCHAR(16) NULL DEFAULT NULL,
	"focus_points_json" TEXT NULL DEFAULT NULL,
	"composition_mode" VARCHAR(16) NULL DEFAULT NULL,
	"status" VARCHAR(16) NULL DEFAULT NULL,
	"summary_json" TEXT NULL DEFAULT NULL,
	"progress_json" TEXT NULL DEFAULT NULL,
	"plan_json" TEXT NULL DEFAULT NULL,
	"max_score" INTEGER NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	"submitted_at" BIGINT NULL DEFAULT NULL,
	"exam_mix_json" TEXT NULL DEFAULT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "paper_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "paper_sequence_not_null1" CHECK (sequence IS NOT NULL),
	CONSTRAINT "paper_practice_id_not_null1" CHECK (practice_id IS NOT NULL),
	CONSTRAINT "paper_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "paper_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_paper_user_practice" ON "" ("user_id", "practice_id", "sequence");;

