-- 导出  表 public.practice 结构
CREATE TABLE IF NOT EXISTS "practice" (
	"id" BIGINT NOT NULL,
	"user_id" BIGINT NOT NULL,
	"stage_id" BIGINT NULL DEFAULT NULL,
	"mode" VARCHAR(16) NULL DEFAULT NULL,
	"topic" TEXT NULL DEFAULT NULL,
	"scope_mode" VARCHAR(16) NULL DEFAULT NULL,
	"scope_text" TEXT NULL DEFAULT NULL,
	"level" VARCHAR(16) NULL DEFAULT NULL,
	"intensity" VARCHAR(16) NULL DEFAULT NULL,
	"paper_size" INTEGER NULL DEFAULT NULL,
	"review" BOOLEAN NOT NULL DEFAULT false,
	"status" VARCHAR(16) NULL DEFAULT NULL,
	"memory_json" TEXT NULL DEFAULT NULL,
	"notes_text" TEXT NULL DEFAULT NULL,
	"notes_updated_at" BIGINT NULL DEFAULT NULL,
	"digest_json" TEXT NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	"updated_at" BIGINT NOT NULL,
	"completed_at" BIGINT NULL DEFAULT NULL,
	PRIMARY KEY ("id"),
	CONSTRAINT "practice_updated_at_not_null1" CHECK (updated_at IS NOT NULL),
	CONSTRAINT "practice_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "practice_review_not_null1" CHECK (review IS NOT NULL),
	CONSTRAINT "practice_user_id_not_null1" CHECK (user_id IS NOT NULL),
	CONSTRAINT "practice_id_not_null1" CHECK (id IS NOT NULL)
)
CREATE INDEX "idx_practice_user_stage" ON "" ("user_id", "stage_id");
CREATE INDEX "idx_practice_stage" ON "" ("stage_id");;

