INSERT INTO "practice" ("id", "user_id", "stage_id", "mode", "topic", "scope_mode", "scope_text", "level", "intensity", "paper_size", "review", "status", "memory_json", "notes_text", "notes_updated_at", "digest_json", "created_at", "updated_at", "completed_at") VALUES
	(1, 2, 1, 'interview', 'java集合高频面试题', 'topic', NULL, 'mid', 'quick', 10, 'false', 'active', '{"mastered":["fail-fast机制与CME原因","迭代器remove安全删除","ArrayList非线程安全与丢失数据","CopyOnWriteArrayList适用场景","Collection存单元素Map存键值对","List/Set/Queue子接口特点","put返回旧值语义","equals相等时hashCode必须相等"],"weakPoints":["迭代器remove用法（未作答需重练）","Collection与Map关系表述不完整","synchronizedList与CopyOnWrite取舍","HashMap线程不安全的具体表现","HashSet判重依据hashCode+equals","同步计数场景应用ConcurrentHashMap","HashMap阈值扩容触发说明"],"misconceptions":["把HashSet判重说成仅基于equals","计数并发场景误选Hashtable"],"nextFocus":["HashMap扩容阈值与负载因子计算","ConcurrentHashMap计数与get/put并发","HashSet判重与equals/hashCode一致性"],"coverage":["ArrayList插入复杂度","ArrayList扩容倍数","Java集合接口体系","常见集合实现类","Comparable与Comparator","ArrayList特性与适用场景","HashSet去重","LinkedList插入删除","HashMap的equals判定","hashCode与equals一致性","Hashtable线程安全与性能","ConcurrentHashMap并发特性","ArrayList数组存储结构","数组下标随机访问","ArrayList中间增删O(n)","ArrayList扩容触发时机","Collections.synchronized","CopyOnWriteArrayList写时复制","HashMap底层结构与树化","HashMap null键值支持","HashMap线程安全性","fail-fast与ConcurrentModi","Iterator边遍历边删除","ArrayList并发写丢数据","Collection与Map关系","List/Set/Queue子接口","线程安全List选型","Map.put/get/putIfAbsent返","HashSet判重依据","HashMap阈值与负载因子","URL去重计数场景选型"],"updatedAt":1793083231785}', '', NULL, '{"overview":"已练2卷20题，均分70.2。覆盖集合体系、ArrayList增删与扩容、fail-fast与Iterator删除、HashMap结构与key约定、HashSet去重、并发集合选型。基础概念尚可但常漏\"为什么\"，中档原理细节易错，equals/hashCode判据答错过。","level":"基础中档尚可，原理细节与解释深度待补","coveredAreas":["集合接口体系","ArrayList增删与","fail-fast与迭代","HashMap结构与ke","HashSet去重判据","Map常用方法返回值","并发集合选型"],"uncoveredAreas":["LinkedList机制","HashMap扩容与负载","HashMap遍历与fa","TreeMap与有序Ma","队列与Deque","集合序列化与拷贝"],"updatedAt":1793083231785}', 1793073156389, 1793083231785, NULL),
	(2, 2, 1, 'interview', 'java多线程锁机制(volatile，CAS，synchronized锁升级，AQS，Lock等等)高频面试题', 'topic', NULL, 'mid', 'quick', 10, 'false', 'active', '{"mastered":["volatile禁止重排序保DCL安全","synchronized实例锁与类锁区分","volatile引用赋值可见性与原子性边界","check-then-act竞态条件现象描述","i++复合操作volatile不保原子性","ReentrantLock tryLock超时获取锁","wait被唤醒后需重新抢锁","count++丢失更新原因与修正"],"weakPoints":["AQS抢锁失败后自旋入队阻塞流程","happens-before定义与volatile体现","可重入语义限定与持锁过深风险","check-then-act为何整体加锁原因","Condition await释放锁与signal入队语义","synchronized锁升级各阶段触发条件","可中断锁获取与超时锁差异","Condition.await返回后while重检"],"misconceptions":["轻量锁释放后永久保持重量级(错)","notify会释放锁(持有到退出同步块)","tryLock中断时未获锁不能unlock(反了)","happens-before不等于执行时间先后(是可见性序)"],"nextFocus":["补答AQS抢锁失败后自旋/入队/阻塞顺序","补答happens-before定义与volatile如何体","补答Condition await释放锁与signal只是入"],"coverage":["volatile 不保证原子性","volatile 状态标志位","CAS 原理与 ABA 问题","ReentrantLock 适用场景","synchronized 锁升级与触发条件","AtomicInteger 原子类","wait/notify 调用条件","公平锁与非公平锁","DCL 单例与 volatile","synchronized 锁对象辨析","volatile不保证原子性","volatile状态标志位","CAS原理与ABA问题","ReentrantLock适用场景","synchronized锁升级与触发条件","AtomicInteger原子类","wait/notify调用条件","DCL单例与volatile","synchronized锁对象辨析","无锁与加锁适用场景对比","原子类常用方法","偏向锁撤销与降级规则","指令重排序与可见性","tryLock超时获取锁","CAS与synchronized自增对比","synchronized实例锁与类锁","wait/notify条件等待语义","lock()与lockInterruptibly","Condition双等待队列实现","volatile内存屏障与happens-bef","synchronized多实例失效边界","数据库条件更新与行锁方案","volatile引用与对象内部字段语义","CAS自旋开销优化与退避策略","tryLock返回值语义辨析","Condition.await调用前提","notifyAll与notify通知策略","偏向锁轻量级锁启用条件","happens-before可见性传递性","锁对象唯一性与final声明"],"updatedAt":1793348338920}', '', NULL, '{"overview":"累计10卷110题均分41.2，近卷73.1。volatile可见性/原子性、DCL重排序、synchronized锁对象、CAS与原子类选型、check-then-act答得较好；AQS队列流程、Condition、锁升级、wait/notify仍弱，大题多问易漏、方向易反。","level":"入门偏下，概念散、多问易漏，原理欠扎实","coveredAreas":["volatile可见性与","指令重排序与DCL","synchronized","CAS与原子类选型","可重入与tryLock","check-then-a","Condition基础","自旋与锁优化概念"],"uncoveredAreas":["AQS原理与同步队列","读写锁","死锁与规避","线程中断与锁","原子类实现原理","锁升级过程","wait/notify协","选型对比综合"],"updatedAt":1793348338920}', 1793083702053, 1794475409509, NULL),
	(4, 2, 1, 'interview', 'java线程池', 'range', '线程池七大参数，四种内置线程池，拒绝策略，业务中如何自定义线程池', 'mid', 'quick', 10, 'false', 'active', '{"mastered":["SynchronousQueue 直接交接不缓存","FixedThreadPool 无界队列 OOM 风险","CachedThreadPool 线程数上限风险","CachedThreadPool 60s 回收机制","任务提交 core→queue→max→拒绝流程","无界队列适用场景：总量可控批处理","自定义拒绝策略：记日志+落盘+补偿","自定义 ThreadFactory 线程命名"],"weakPoints":["shutdown 与 shutdownNow 区别未掌握","线程池用完是否关闭、核心线程回收","四大拒绝策略任务最终去向未对比","ThreadFactory 除命名外的异常兜底","execute/submit/invokeAll 返回值差异","submit 异常经 Future.get 传播","线程名前缀在排障中的具体用法","有界队列容量由等待时间与任务量权衡"],"misconceptions":["CachedThreadPool 用 Synchronous","把 ThreadFactory 问题答成不要用 Execut","自定义拒绝策略混淆为内置策略选型"],"nextFocus":["shutdown/shutdownNow 与核心线程回收，直","execute/submit/invokeAll 返回值与异","线程名前缀在 dump 排障中的具体帮法"],"coverage":["线程池任务提交处理顺序","七大参数 corePoolSize/maximu","默认拒绝策略 AbortPolicy 与 Rej","Executors 四种内置线程池适用场景","CallerRunsPolicy 反压效果","任务队列分类（无界/有界/同步移交）","拒绝策略触发时机与作用","CPU/IO 密集型线程数取值","自定义 ThreadFactory 必要性","Executors OOM 风险与手写 Thre","keepAliveTime 非核心线程存活","corePoolSize 与 maximumPo","有界队列与拒绝策略业务取值","四种内置线程池的队列类型与线程上限","自定义拒绝策略与降级补偿","线程池 shutdown 与 shutdownN","线程池关闭与核心线程回收","AbortPolicy 与 DiscardPol","SynchronousQueue 适用场景","threadFactory 定制线程创建","keepAliveTime 与 unit 参数作","allowCoreThreadTimeOut 设","Fixed/Cached 内置线程池隐患","无界队列导致 max 失效","SynchronousQueue 不缓存直接移交","FixedThreadPool 任务堆积 OOM","CachedThreadPool 线程数暴涨风险","execute/submit/invokeAll","线程名前缀便于排障定位"],"updatedAt":1793692387772}', '', NULL, '{"overview":"已练4卷40题，百分制均分65.0。七大参数、四种内置线程池、拒绝策略、队列与任务流转主干流程掌握较好；submit/execute差异、自定义线程池实战、大题多问点漏答、参数配合与调优偏弱。","level":"概念记忆尚可，多问点漏答，实战设计与调优偏弱","coveredAreas":["线程池七大参数","四种内置线程池","拒绝策略","阻塞队列","任务流转顺序","参数取值","Executors隐患","线程池关闭"],"uncoveredAreas":["自定义线程池实战","线程池监控","参数调优场景","ThreadFactor"],"updatedAt":1793692387772}', 1793608842590, 1793692387772, NULL),
	(5, 2, 2, 'interview', 'Spring核心', 'range', 'IOC容器，循环依赖，AOP动态代理，Bean生命周期等等高频面试题', 'mid', 'quick', 10, 'false', 'active', '{"mastered":["Bean生命周期主干顺序:实例化→属性填充→初始化→使用","强依赖用构造器注入,可选依赖用setter注入","@Primary与@Qualifier多候选消歧方式","@Conditional条件注册基本用法","执行期切点匹配:首*任意返回值,..任意参数","AOP日志/耗时统计等横切场景适用","构造器注入能让必需依赖在创建时完整"],"weakPoints":["会话级可变状态应选request作用域,非prototype","Aware接口举例与拿到的资源说不清(未作答)","销毁前流程只记得@PreDestroy,漏BeanPostP","字段注入与setter注入的注入时机与差异答不出","注解驱动AOP靠BeanPostProcessor生成代理说","@Before/@Around在事务与日志场景的分工"],"misconceptions":["把BeanPostProcessor当成只作用于自身实现类","@Lazy加注入点=懒加载(实为代理解循环)","注入方式选型理由说不清(构造器/setter)","把AOP增强对象说成Bean整体,未落到方法/连接点"],"nextFocus":["背:BeanNameAware/ApplicationCon","背:字段注入在属性填充后由反射完成,setter注入走set","练:销毁前三步(销毁前BeanPostProcessor→@"],"coverage":["Bean生命周期四大阶段","实例化与初始化的区别","AOP切面注解(@Aspect/@Pointcu","切入点表达式execution匹配","三级缓存解决循环依赖","构造器注入循环依赖无法解决","AOP代理与自调用失效","自调用失效的解决办法","Bean初始化回调(@PostConstruct","Bean销毁回调(@PreDestroy等)","@Lazy延迟初始化(懒加载)","@Lazy注入点代理与解循环","Bean作用域(scope)","prototype作用域声明与特性","构造器注入与setter注入对比","构造器注入与循环依赖的关系","Spring AOP默认代理方式选择","JDK动态代理与CGLIB差异","三级缓存的key与value结构","@Autowired required语义","属性填充阶段依赖缺失行为","AOP切面失效的典型场景","final关键字与不可变关系","不可变类设计条件","@ComponentScan扫描包配置","Spring Boot默认扫描包","切点与连接点的概念与关系","Bean初始化回调执行顺序","@Lazy与构造器注入场景取舍","Bean生命周期每步职责说明","AOP代理生成时机与环节","代理对象与原始Bean区别","singleton与prototype容器表现差","作用域声明方式(@Scope/scope)","@Autowired多候选消歧手段","构造器注入循环依赖报错原因","循环依赖成立条件与判定","AOP生效条件与内部调用失效","组件扫描范围与启动耗时","@Lazy延迟初始化启动优化"],"updatedAt":1793863420632}', '', NULL, '{"overview":"累计5卷65题，平均38.3分，最近一卷64.0分，进步明显但作答率仍偏低。Bean生命周期主干顺序已基本掌握，注入方式选型、多Bean冲突处理、切点表达式结论类问题答得较好。主要失分点：Bean作用域选型（会话场景误选prototype）、Aware接口、销毁阶段回调链、字段注入与setter注入在生命周期中的时机差异（未作答）、AOP通知类型与代理创建时机。","level":"基础薄弱，结论对但机制链条说不全，作答率低","coveredAreas":["Bean生命周期主干","循环依赖与三级缓存","Bean作用域选型","依赖注入方式","AOP切面与切点","JDK与CGLIB代理","条件装配与多Bean","Aware接口"],"uncoveredAreas":["BeanFactory体","配置类装配原理","@Import机制","AOP通知类型进阶","AOP代理创建时机","Bean销毁完整链"],"updatedAt":1793863420632}', 1793607477792, 1793863420632, NULL),
	(6, 2, 2, 'interview', 'SpringBoot自动配置、Starter、过滤器与拦截器等等 高频面试题', 'topic', NULL, 'mid', 'quick', 10, 'false', 'active', '{"mastered":["Starter 本质是依赖聚合加自动配置","@Bean 在配置类中注册第三方类为 Bean","自动配置入口文件：AutoConfiguration.imp","@Autowired 按类型注入，@Qualifier 指定","Profile 文件命名约定与激活方式","@SpringBootApplication 组成与 @En","@ConditionalOnClass 等条件注解的概念","全局异常处理用 @ControllerAdvice 与 @E"],"weakPoints":["@SpringBootApplication 的 exclu","Filter 实现类骨架写不出；接口是 javax.serv","application-dev.yml 靠 Profile ","Spring Boot 2.x 自动配置 key 是 org","HandlerInterceptor 三方法的执行时机与用途","AOP 的作用和典型横切场景（日志、事务、权限）没答上来","短信 Starter 的自动配置组织、条件装配、Bean 覆","拦截器写了还要 WebMvcConfigurer 注册才生效"],"misconceptions":["认为拦截器写了就生效，漏掉 WebMvcConfigurer","把 @Value 简写成 @Value(键名)，漏 ${}"],"nextFocus":["重出 HandlerInterceptor 三方法时机与执行","重出 AOP 横切关注点与场景小题","重出 exclude 排除自动配置的写法与位置题"],"coverage":["Spring Boot Profile 文件命名","配置覆盖优先级","自动配置常用条件注解及使用场景","Starter 的构成与命名约定","@SpringBootApplication 的","@EnableAutoConfiguration","@Autowired 与 @Resource 的","Filter 所属规范与 Spring Boot","@RequestParam/@PathVaria","@ConfigurationProperties","Filter 与 Interceptor 的所属","@RestControllerAdvice 与","HandlerInterceptor 三方法执行","自定义 Starter 模块结构与编写步骤","Filter 与 Interceptor 的注册","官方 Starter 省去的手动配置","AOP 适用的横切场景与横切关注点特征","排除自动配置类的写法与位置","DispatcherServlet 分发与 Ha","Filter 与 Interceptor 的层次","WebMvcConfigurer 统一跨域配置","spring.factories 自动配置入口与","@Autowired 与 @Resource 区","Filter 与 Interceptor 所属体","Filter 与 Interceptor 注册方","AOP 横切场景与横切关注点","spring.factories 自动配置入口","@Bean 手动注册第三方类","@Value 注入与默认值兜底","Filter 中计时与 try-finally","登录鉴权放 Filter 还是 Intercep","@RestControllerAdvice 与异","自定义 Starter 模块结构与步骤","AOP 适用的横切场景与特征","spring.factories 与 AutoC","spring-boot-starter-web","Starter 依赖聚合与版本管理作用","Filter 与 Interceptor 适用场","自动配置类发现机制与入口文件","@Value 占位符 ${} 写法"],"updatedAt":1794292876064}', '', NULL, '{"overview":"本卷10题仅答4题，完成度低。答得较好的是@Bean注册第三方类、Filter与拦截器区别、@Component注册Filter；spring.factories key、profile自动加载机制答不出；拦截器三方法、AOP、短信Starter大题未作答。","level":"基础零散，拦截器与Starter实战薄弱","coveredAreas":["@Bean注册三方类","Filter与拦截器区别","@Component注册","自动配置发现机制","Starter依赖聚合","@Autowired/@"],"uncoveredAreas":["自动配置排除","Profile机制","spring.facto","拦截器执行时机","AOP应用","Starter封装实战","CORS配置"],"updatedAt":1794292876065}', 1793869752965, 1794305327453, NULL),
