INSERT INTO "stage" ("id", "user_id", "name", "status", "summary_json", "created_at", "updated_at", "completed_at") VALUES
	(1, 2, '第一周', 'active', '{"overall":"本阶段练了Java集合、多线程锁机制、线程池三块，共16卷170题，百分制均分约52，属中等偏下。集合与线程池基础概念较稳，锁机制卷多、得分低且大量未作答。最突出问题是答题只给结论不讲机制、大题多问常漏答，且AQS/Condition/锁升级等原理长期薄弱。","strengths":["synchronized锁对象辨析（实例锁与类锁、多实例失效边界）","volatile语义：可见性/不保原子性/DCL防重排序","线程池任务提交主流程 core→queue→max→拒绝 与七大参数作用","HashMap/HashSet 判等与去重依据（hashCode定位+equals判等）","CAS原理与ABA问题、原子类基本选型"],"keyWeaknesses":["AQS抢锁失败后自旋入队阻塞的主干流程讲不清","Condition await释放锁/signal入队语义、await后while重检","synchronized锁升级各阶段触发条件与不可逆原因","happens-before定义及其与volatile的关系（曾答反）","答题完整性差：简答题漏答第二问、大题多问漏点、部分题未作答"],"nextSteps":["先补齐未作答与漏答习惯：做题强制分点、结论先行、逐问作答，每题写满『结论+机制+为什么』","重点攻关AQS/Condition/锁升级三条主线，各做3道基础辨析再上2道场景题，把主干流程背到能口述","复习happens-before与volatile内存语义，纠正方向性错误，配合DCL、状态标志位场景巩固","线程池补练submit与execute、关闭与回收语义，做1道参数调优+拒绝策略取舍的串联大题"],"reviewScope":"本阶段覆盖Java集合体系（ArrayList结构与扩容、HashMap结构与key约定、HashSet去重、fail-fast与Iterator删除、并发集合选型）、多线程锁机制（volatile可见性与原子性、CAS与原子类、synchronized锁对象与锁升级、ReentrantLock与Condition、AQS、wait/notify、happens-before）、线程池（七大参数、四种内置线程池、拒绝策略、队列类型、自定义线程池）。全复习须覆盖上述已练知识点但换角度出题，不要复现原题；优先考薄弱点：AQS入队阻塞流程、Condition的await/signal语义、锁升级触发与不可逆、happens-before与volatile、线程池shutdown与submit/execute差异、HashSet判重依据。深度先基础辨析后场景大题，要求能上手把机制与『为什么』讲出来，不只给结论。","generatedAt":1793692417367}', 1793073146920, 1793692417367, NULL),
	(2, 2, '第二周', 'active', '{"overall":"本阶段练了 Spring 核心（IOC、循环依赖、Bean 生命周期、AOP）、Spring Boot（自动配置、Starter、Filter 与拦截器）、MySQL 索引原理与 Spring 事务四块，共完成 2 张卷；其中 Spring 核心完成 5 卷 65 题、Spring Boot 完成 4 卷 77 题，MySQL 索引与 Spring 事务尚无有效作答。整体处于“方向对、细节缺”阶段","strengths":["能说清 Bean 生命周期主干顺序（实例化→属性填充→初始化→使用）与实例化、初始化的区别","能讲清三级缓存解决循环依赖的流程，以及构造器注入循环依赖为何无法解决","掌握 JDK 动态代理与 CGLIB 的差异和 Spring AOP 默认代理选型，能说清自调用失效及解决办法","掌握 Starter 本质（依赖聚合加自动配置）、自动配置入口文件与常用条件注解的方向","掌握 @Autowired 按类型、@Resource 按名称的默认匹配差异，以及 @Primary/@Qualifie"],"keyWeaknesses":["作答率与完整度：大量题目空白或只答一半，多问只答第一问，这是各卷失分的主因","Bean 作用域选型（会话状态应选 request 而非 prototype）、Aware 接口举例、销毁回调链（漏 B","注解驱动 AOP 靠 BeanPostProcessor 生成代理的机制、代理生成时机、@Before 与 @Aroun","Spring Boot 侧：Filter 实现类骨架写不出、HandlerInterceptor 三方法执行时机、拦截器","SQL 索引的失效场景（函数、前缀匹配改写、联合索引顺序配合 GROUP BY）与 Spring 事务的传播属性、隔离级"],"nextSteps":["先治作答率：每卷强制全答，答题按“结论+为什么+边界”三段写，先做 5 道基础辨析练完整表达","针对薄弱点专项：Bean 作用域选型、Aware 与销毁回调链、AOP 代理生成时机各做 3 道中档题，要求口述机制而非只给结论","Spring Boot 补齐骨架书写：Filter 实现、HandlerInterceptor 三方法、WebMvcConfigurer 注册、自动配置入口文件","启动 MySQL 索引与 Spring 事务两个新范围：先各做一张全基础卷（最左前缀、回表、覆盖索引；传播属性、隔离级别、失效场景），答满再进阶"],"reviewScope":"全复习覆盖 Spring 核心、Spring Boot 与 MySQL 索引、Spring 事务四大块，均按“先基础辨析、后场景大题”的顺序练，要求能口述机制而不是只给结论。Spring 核心需覆盖 Bean 生命周期四阶段与回调顺序、构造器与 setter 注入选型、@Autowired/@Resource 消歧、作用域选型（含 request 会话场景）、Aware 接口与销毁回调链、三级缓存与循环依赖成立条件、JDK 与 CGLIB 代理选型、自调用失效与 @Before/@Around 分工、代理生成时机与 BeanPostProcessor 关系。Spring Boot 覆盖 Profile 激活、条件注解、自动配置入口文件与发现机制、Starter 构成与自定义步骤、@ConfigurationProperties/@Value、Filter 与 Interceptor 的差异、注册方式与适用场景、HandlerInterceptor 三方法时机、@RestControllerAdvice 与拦截器注册、排除自动配置。MySQL 索引与 Spring 事务作为新起范围，练最左前缀、回表、覆盖索引、函数与模糊匹配导致失效、联合索引顺序配合 GROUP BY，以及传播属性、隔离级别、脏读不可重复读幻读、事务失效场景。薄弱点优先考：作用域选型、Aware 与销毁回调、AOP ","generatedAt":1794384185284}', 1793607394109, 1794384185284, NULL),
	(8, 3, 'test', 'active', '{"overall":"本阶段共练了 4 张卷 145 道题，其中 3 张已交卷、平均 33.7 分，最近一卷 35.2 分，另有一张 60 题卷和 15 题卷未交卷。整体看，基础概念（变更流程、干系人、成本估算、关键路径计算）已有零散认知，但知识碎片化、远未成体系；最突出的问题是主观题作答率低、常只答第一问，简答不给机制与做法，多选填空几乎空白，导致失分集中在漏答与要素不全。","strengths":["能说清变更控制五步流程并做影响评估，变更与基准审批判断基本稳定","掌握成本估算方法与成本基准、成本控制，能算 CV 并区分应急储备与管理储备","活动网络图与关键路径、最早完成时间计算基本会做，能判断延误是否影响总工期","PMBOK 中整合管理与项目各要素统筹权衡、利益相关者识别与冲突处理策略有概念基础","Scrum 角色职责、用户故事与验收标准、敏捷三大支柱能答出主干"],"keyWeaknesses":["主观题和子问题作答不完整，只答第一问、后两问留空，是失分最大来源","多选、填空类题型几乎全部放弃，知识覆盖不完整","项目生命周期类型选型（预测型阶段关口位置）与敏捷三大支柱举例不牢","EVM 挣值分析公式（CV/SV/SPI）与进度成本偏差判断薄弱","风险清单要素、负面风险应对策略、需求价值评估与收益管理缺乏可讲出的做法"],"nextSteps":["先从「先答全再答深」入手：每道大题按 ①②③ 逐问作答，写出结论加一句原因，限时 20 分钟练 5 道，先保证不漏问","针对 EVM 公式、生命周期选型、敏捷三支柱、风险应对策略做 10 道基础辨析与填空，再上 2 道场景题","把多选与填空单独成卷反复练，覆盖变更、风险、干系人、质量、成本各 1 到 2 道","补齐风险清单要素与需求价值评估的口述模板，各写 3 条可以口述的要点并背诵"],"reviewScope":"范围为 PM 方向，涵盖生产体系知识库（制度文件、效能平台、质量体系、敏捷实践、优秀案例、数字化生产系统）、FY26 项目经理赋能课程与 PMBOK 第 6 版及 8 版预览。已练过的整合管理与要素权衡、需求收集与确认、变更流程与影响评估、问题闭环、风险识别与应对、干系人识别与参与、团队建设与冲突策略、沟通管理、成本估算与基准控制、应急与管理储备、质量保证与质量控制、项目生命周期与预测型适应型区别、关键路径与总浮动时间、Scrum 角色与仪式、用户故事与验收标准、收尾验收与复盘、安全管理与合规、EVM 挣值分析。薄弱点优先考：项目生命周期类型选型、敏捷三支柱、EVM 偏差判断、风险清单要素与负面风险应对、需求价值评估与收益管理、主观题逐问作答与机制表述。深度上先基础辨析与填空，再上单场景大题，要求能口述结论加原因。","generatedAt":1794470732463}', 1794209003510, 1794470732463, NULL);

-- 导出  表 public.users 结构
CREATE TABLE IF NOT EXISTS "users" (
	"id" BIGINT NOT NULL,
	"username" VARCHAR(64) NOT NULL,
	"password_hash" VARCHAR(512) NOT NULL,
	"nickname" VARCHAR(64) NULL DEFAULT NULL,
	"avatar_ext" VARCHAR(8) NULL DEFAULT NULL,
	"api_key_cipher" TEXT NULL DEFAULT NULL,
	"api_key_nonce" TEXT NULL DEFAULT NULL,
	"api_key_version" INTEGER NULL DEFAULT NULL,
	"api_key_last4" VARCHAR(8) NULL DEFAULT NULL,
	"api_base" TEXT NULL DEFAULT NULL,
	"model" TEXT NULL DEFAULT NULL,
	"api_format" VARCHAR(16) NULL DEFAULT NULL,
	"temperature" DOUBLE PRECISION NULL DEFAULT NULL,
	"summary_json" TEXT NULL DEFAULT NULL,
	"summary_at" BIGINT NULL DEFAULT NULL,
	"summary_status" VARCHAR(16) NULL DEFAULT NULL,
	"summary_error" TEXT NULL DEFAULT NULL,
	"summary_started_at" BIGINT NULL DEFAULT NULL,
	"created_at" BIGINT NOT NULL,
	"updated_at" BIGINT NOT NULL,
	"active_llm_config_id" BIGINT NULL DEFAULT NULL,
	PRIMARY KEY ("id"),
	UNIQUE ("username"),
	CONSTRAINT "users_updated_at_not_null1" CHECK (updated_at IS NOT NULL),
	CONSTRAINT "users_created_at_not_null1" CHECK (created_at IS NOT NULL),
	CONSTRAINT "users_password_hash_not_null1" CHECK (password_hash IS NOT NULL),
	CONSTRAINT "users_username_not_null1" CHECK (username IS NOT NULL),
	CONSTRAINT "users_id_not_null1" CHECK (id IS NOT NULL)
);

