INSERT INTO "users" ("id", "username", "password_hash", "nickname", "avatar_ext", "api_key_cipher", "api_key_nonce", "api_key_version", "api_key_last4", "api_base", "model", "api_format", "temperature", "summary_json", "summary_at", "summary_status", "summary_error", "summary_started_at", "created_at", "updated_at", "active_llm_config_id") VALUES
	(1, 'testuser1', '$argon2id$v=19$m=16384,t=2,p=1$6CQx6Aj1BWDvC5JBLNQaFw$FfW6VwJ9IycBD4TB4fEpMsAUHZ8vzWF9MKeKYBXObmk', 'testuser1', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1793756057549, 1793756057549, NULL),
	(2, 'admin', '$argon2id$v=19$m=16384,t=2,p=1$9DBKrrIZ2bUgAmffafaD/Q$GmpM9GDVRni79dXlnoJlN9qADByKcnxPvdatlc2PGXY', '管理员', 'jpg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"profile":{"title":"Java后端初级开发者，基础概念有方向感但机制深度不足，Spring/并发/MySQL均未系统掌握","overview":"288题均分42.0，刷题均分5.1/10，作答率低（大量空白或只答一半），错题本待订正199题。Spring核心39.9分、SpringBoot 21.8分、MySQL索引卷0分、事务0卷。集合59.2分、线程池61.4分相对较好，但锁机制44.1分且AQS/Condition长期薄弱。最近一卷50.5分略有回升。整体处于‘知道方向、讲不透机制、覆盖不全’的初级阶段。"},"strengths":[{"point":"Java集合与线程池基础概念较扎实","evidence":"集合2卷均59.2分，线程池4卷均61.4分，均为各模块最高；已掌握fail-fast、SynchronousQueue、FixedThreadPool OOM风险、自定义拒绝策略等具体点。"},{"point":"部分Spring核心机制结论准确","evidence":"最强10点中循环依赖三级缓存(100)、JDK动态代理(100)、自动配置加载顺序(100)；AOP与循环依赖‘已掌握/学习中’条目多于其他Spring知识点。"},{"point":"volatile与synchronized概念辨析有基础","evidence":"volatile与可见性已掌握2、待巩固1；synchronized与锁升级已掌握1、待巩固2；记忆点含‘volatile禁止重排序’‘synchronized实例锁与类锁区分’等正确结论。"},{"point":"事务传播属性有局部正确认知","evidence":"最强10点中传播属性相关占3条（NESTED与保存点、无事务场景三行为、配置方式，均100分），事务失效同类自调用(100分)。"}],"weaknesses":[{"point":"作答完整度极低，多问只答第一问或留白","advice":"每次练习强制每题分点作答，先写完再追求深度；设定‘空白题数=0’为及格线。"},{"point":"机制讲不透，只给结论不推演‘为什么’","advice":"对每个高频题用‘结论→机制→对比→场景’四步口述录音，重点练Bean生命周期、AOP代理时机、AQS入队。"},{"point":"Spring Boot过滤器/拦截器、Starter组织、配置细节薄弱","advice":"手写Filter与HandlerInterceptor骨架并注册，整理Starter自动配置三件套（pom、AutoConfiguration.imports、条件注解）各一遍。"},{"point":"MySQL索引与Spring事务几乎零有效作答","advice":"先补索引失效场景（函数、前缀匹配、联合索引顺序）与事务传播/隔离级，各完成1张卷且不留空白。"},{"point":"并发高级主题（AQS、Condition、锁升级不可逆）长期薄弱","advice":"画AQS抢锁失败自旋入队阻塞流程图，对照Condition await/signal语义写一遍笔记，再做错题订正。"}],"jobAdvice":{"targetLevel":"junior","positions":["Java后端开发工程师（初级）","Java初级研发（业务系统/Web后端方向）"],"reasons":["大量知识点处于‘未学’或‘学习中’：事务失效场景未学4、Spring AOP未学2、Java多线程锁机制未学9，覆盖面不足。","整体均分42.0、刷题均分5.1/10、错题待订正199且已解决0，说明知识尚未闭环，达不到中级深度要求。","已覆盖集合、线程池、Spring核心基础，可匹配以业务开发为主、不要求分布式与高并发的初级后端岗位。"]},"interviewFocus":["Spring Bean生命周期与循环依赖三级缓存：能完整讲出实例化→属性填充→初始化→销毁链及每级缓存作用。","AOP代理生成时机与失效场景：BeanPostProcessor生成代理、自调用失效、JDK/CGLIB选型。","Spring Boot自动配置与Starter组织：AutoConfiguration.imports、条件注解、Filter与Interceptor区分及注册方式。","synchronized锁升级与volatile语义：各阶段触发条件、不可逆原因、happens-before与volatile关系。","MySQL索引失效场景与联合索引顺序：函数、前缀匹配改写、与GROUP BY顺序配合。"],"actionPlan":[{"step":"先清零错题本：199道待订正按模块分组，每天订正15道并口述机制，一周内已解决数>0。","why":"错题已解决0是最大硬伤，不订正则练习无效。"},{"step":"对SpringBoot模块重做1张卷，目标不留空白且均分>40；同步手写Filter与拦截器骨架。","why":"SpringBoot均分仅21.8、4卷50题，是覆盖最弱的大块。"},{"step":"补MySQL索引与Spring事务各1张卷，先复习索引失效三场景与传播属性七种，再作答。","why":"索引卷0分、事务0卷，但最强10点中已有传播属性基础，补齐成本低、收益高。"},{"step":"并发部分专攻AQS+Condition+锁升级，画流程图并做5道场景题，目标该模块均分从44.1提到55+。","why":"锁机制10卷110题均分44.1且AQS/Condition长期薄弱，是面试高频失分区。"},{"step":"所有练习执行‘分点作答+逐问检查’，每周统计空白题数，目标连续两周空白题数为0。","why":"多卷评价指出漏答、空白是失分主因，表达完整度直接决定面试得分。"}],"generatedAt":0}', 1794540200194, 'idle', NULL, NULL, 1793755971889, 1794187162597, 2),
